WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[58483] = { title = "Mementos", description = "At Heartwood Grove, I heard tales about the fall of Tirna Noch. I never thought that I would see it with my own eyes.\n\nIt brings me great sadness. And I wonder... if this is the fate that awaits my old grove as well.\n\nI can't believe that everything that was once here is truly gone. \n\nPerhaps there are still some mementos that can be recovered. Something to remember the fallen.", objectives = "" }
WordHunterWoW_QuestEN[58484] = { title = "Take What You Can", description = "We know that these invaders have taken over the remains of the grove. \n\nBut why? Why are they gathering anima and bringing it all to one place?\n\nAnd how did they enter Ardenweald?\n\nWe should stay alert and take as much anima as we can find. Perhaps some good can come out of all this loss.", objectives = "" }
WordHunterWoW_QuestEN[58485] = { title = "Built to Fall", description = "The Baruk use the forbidden arts of necromancy to trap souls of fallen mogu into the statues that fight for them. \n\nThese tactics are a disgrace to our people, and cannot be allowed to continue.\n\nBreak their precious statues, and give them no vessels with which to contaminate with their stolen spirits.", objectives = "" }
WordHunterWoW_QuestEN[58486] = { title = "He's Drust in the Way", description = "Only the heart of a grove can hold the sheer massive quantity of anima I'm sensing. \n\nWhen my grove was sacrificed, the anima within its heart was reclaimed. Now it brims with anima once again.\n\nAnima that was stolen from other groves.\n\nWe must secure the heart not just for our own sake, but for the entire forest.\n\nI suspect that we will not be allowed to simply trot our way in there. Be prepared for anything.", objectives = "" }
WordHunterWoW_QuestEN[58487] = { title = "Plunder the Plunderers", description = "Our raids on Lei Shen's treasuries did much to ensure the Thunder King's downfall. I think we should employ the same strategy here.\n\nSeek out the hoarded plunder of the mogu clans and relieve them of it. \n\nWe must do all we can to disrupt their advance.", objectives = "" }
WordHunterWoW_QuestEN[58488] = { title = "Go for the Heart", description = "I was right! A great deal of anima has been stored inside the heart of the grove.\n\nThe Drust must have collected it from all over Ardenweald.\n\nAnd now, we will take it back.\n\nQuickly, destroy that barrier and grab the heart. Niya and I will protect you.", objectives = "" }
WordHunterWoW_QuestEN[58496] = { title = "An Unwelcome Advisor", description = "<The envelope contains a message from King Anduin Wrynn.>\n\n{name},\n\nEven with the forces of the Horde and Alliance working together, we still have found no trace of N'Zoth's forces. Ever since his release, the Old God has evaded us at every turn.\n\nThe Light only knows what ill he has in store for Azeroth.\n\nMeet me in Stormwind Keep. We must put a plan together to uncover N'Zoth's schemes before it is too late!\n\nLight grant you haste,\nKing Anduin Wrynn", objectives = "" }
WordHunterWoW_QuestEN[58498] = { title = "Return of the Warrior King", description = "Ye've done a great deal fer Azeroth, hero, but unfortunately I'm gonna have tae ask ye tae do more. N'Zoth is on the loose, an there's no tellin' when or where he'll strike.\n\nThis battle is one ye can't face alone. When the time comes, ye'll have my hammer at yer side!\n\nBut first, we'll need tae fetch it.", objectives = "" }
WordHunterWoW_QuestEN[58502] = { title = "Where the Heart Is", description = "It's time we put Wrathion's plans in tae motion. \n\nHe'll be headin' back tae the Chamber of Heart, so we should meet him there.", objectives = "" }
WordHunterWoW_QuestEN[58504] = { title = "Accusatory Missive", description = "We have received word from Revendreth. It seems that Maldraxxi conspirators have been found skulking within their realm.\n\nAn emissary from Sinfall wishes to discuss the anima reserves we discovered. \n\nJoin me. We depart immediately.", objectives = "" }
WordHunterWoW_QuestEN[58506] = { title = "Network Diagnostics", description = "Unfortunately, we've got no clue where N'Zoth has been lurking since his escape. We do, however have an idea where he might strike.\n\nBack when the keepers were imprisoning the Old Gods, they built defense mechanisms against their corruption into the titan forges. If N'Zoth wants tae corrupt Azeroth, he'll have tae go through them first.\n\nFortunately, we've got ourselves hooked up tae them now, so we can monitor them from here. Go ahead an' take a look.", objectives = "" }
WordHunterWoW_QuestEN[58515] = { title = "Scrounging for Scrolls", description = "The kyrian are known for their collection of scrolls and writings. I'm particularly interested in their texts regarding those who have joined their ranks.\n\nWhy is it that some of the greatest fighters are sent to Bastion and not to Maldraxxus?\n\nPerhaps research can divine the answer.", objectives = "" }
WordHunterWoW_QuestEN[58516] = { title = "[UNUSED]", description = "", objectives = "" }
WordHunterWoW_QuestEN[58517] = { title = "[UNUSED]", description = "", objectives = "" }
WordHunterWoW_QuestEN[58518] = { title = "There's Always a Paper Trail", description = "I noticed that you were surprised to find those strange weapons here.\n\nI sense the essence of their power as well. It is strangely familiar...\n\nWe must discover where the weapons came from and who imbued them with such power.\n\n<Kael'thas smiles.>\n\nIf you and I present the proof to the Accuser together, perhaps she shall allow us to hunt down whoever is behind all of this!", objectives = "" }
WordHunterWoW_QuestEN[58523] = { title = "You're Dead To Me", description = "Your cooperation is expected, but I await results.\n\nOur reconnaissance has revealed a Maldraxxi encampment in the Endmire. We speculate that your kind have been siphoning the Master's stockpiles of anima.\n\nI have called for a carriage to take us there. Let us make haste.", objectives = "" }
WordHunterWoW_QuestEN[58524] = { title = "Sparkles Rain from Above", description = "You found the heart of the grove! And it's full of anima!\n\nThe Drust don't seem to like the idea of you taking it from them. They're massing in great numbers all over the forest!\n\nWe need to get you and the others out of here safely.\n\nI can help. How do you feel about dishing out a little sparkly mayhem?", objectives = "" }
WordHunterWoW_QuestEN[58525] = { title = "The Two Sides of History", description = "You mortals always say that history is written by the victors. But in the Shadowlands, I have found that to be untrue.\n\nEveryone has their own version of events. I would like to know them all. \n\nThere was an author of history books who made her abode in Revendreth's  Darkfall Tower. She wrote from the venthyr's perspective of various incursions and battles alongside the Primus. \n\nIf we could find copies of her works...", objectives = "" }
WordHunterWoW_QuestEN[58530] = { title = "Hidden Mirror", description = "If Renathal is going to put the Harvesters' medallions to use, he's going to need a conduit to focus that power. Denathrius's corruption taints the forges of Revendreth. Our best option is in Bastion.\n\nAs denizens of Revendreth, Bastion will not allow us to enter through Oribos. \n\nWe will need you to activate a mirror hidden away there long ago. Take this.\n\nWe concealed it at a rarely used site, the Veiled Enclave. There should be no one there, especially with the drought.", objectives = "" }
WordHunterWoW_QuestEN[58555] = { title = "A Tense Reunion", description = "We are looking for the forgelite prime, Mikanikos.\n\nOnly he will be able to craft the device we need. I've seen some of his creations. Truly impressive constructs and weaponry that rival even the mightiest of us stoneborn.  \n\nWhen last I encountered him, it was at his workshop. A place of wonders known as the Eternal Forge.\n\nWe will meet you there. Traveling as a group may draw too much attention.", objectives = "" }
WordHunterWoW_QuestEN[58557] = { title = "Assistance from Sinfall", description = "In order to defeat the Forsworn, the Crest needs an artifact that embodies repentance, atoning for past mistakes and moving forward.\n\nI have an artifact in mind. \n\nLong ago, many souls from Revendreth arrived in Bastion. Purer souls than we have ever received from Revendreth.\n\nThey bore the mark of the Seal of Contrition, a focus that expedited their cleansing.\n\nGo to Revendreth and find this seal so that we may harness its power.", objectives = "" }
WordHunterWoW_QuestEN[58558] = { title = "Overhead Intelligence", description = "The Countess knows the fates and goings-on of every noble in Revendreth. It is the best way to keep them in her debt.\n\nHowever, she has a dark secret. Despite what she may say... she was once mortal.\n\nWe will need to find where she keeps her sinstone. No easy feat, of course.\n\nWe will need to gather some intel. The venthyr of the Chalice District are constantly gossiping. Collect their letters from the couriers until you learn something of interest.", objectives = "" }
WordHunterWoW_QuestEN[58559] = { title = "Eyes of the Master", description = "I worry about entering the city. I'm sure you have noticed how well we... stand out here.\n\nDenathrius's loyalists have eyes everywhere, and no more dedicated soldiers than the stoneborn.\n\nTheir eyes and ears watch over the Chalice District. Take out their leaders so none can report our presence here before we acquire the seal.", objectives = "" }
WordHunterWoW_QuestEN[58560] = { title = "Gothic Fashion", description = "Making my way into the city unseen was not as simple as I thought.\n\nI trekked through some mud, where I came across these... small men.\n\nPerhaps Kleia is right. I draw far too much attention here to be of much use. \n\nPerhaps I can disguise myself? Please, help me by gathering some venthyr clothing as a disguise.", objectives = "" }
WordHunterWoW_QuestEN[58561] = { title = "Shards of the Countess", description = "The venthyr travel long distances through enchanted mirrors. The keys we look for are not as we have in Bastion, but rather shards of a mirror that will lead to the sinstone's location.\n\nBased on the intel you found, we know which three houses hold these shards.\n\nPrimrose, Darkvein, and Sinfang.\n\nGo to their manors and retrieve the shards. We will find the frame to piece them into.", objectives = "" }
WordHunterWoW_QuestEN[58562] = { title = "Collecting Dust", description = "If I know the Countess, which I do, her sinstone will have stronger protection than mere keys.\n\nShe is quite fond of curses to protect her gateways. I am capable of creating a residue that should protect us, but it requires the petals of a specific flower you can find in Redelav gardens.\n\nCollect the petals of these flowers so that I may protect us from the dangers to come.", objectives = "" }
WordHunterWoW_QuestEN[58563] = { title = "Through Glass", description = "The mirror frame rests at the bottom of Redelav Hall. Kleia and Pelagos wait there.\n\nWith these shards, I can piece it together.\n\nWe will go through, grab the sinstone, and go face the Countess. Let nothing stand in our way.", objectives = "" }
WordHunterWoW_QuestEN[58564] = { title = "Sins of the Past", description = "The Countess built her reputation on being a native venthyr, never a soul.\n\nRevealing her sinstone to the world would be catastrophic. This is the leverage we need for the information we seek.\n\nShe will tell us where Alwin is. Where the seal is.\n\nThis mirror leads to her estate. I will follow behind you as backup, but the kyrian shall wait here.\n\nDon't let her threaten you. You hold the power.", objectives = "" }
WordHunterWoW_QuestEN[58565] = { title = "Land of Light", description = "The Ember Ward is filled with outcasts from Revendreth society, whether they rebelled, crossed a noble, or simply looked at Denathrius wrong.\n\nIt is a Light-scorched land that drives venthyr mad, unless they manage to stay within the shadows.\n\nIf Alwin is there, it may be too late.\n\nLet us visit Theotar at the Sanctuary of the Mad. I'm sure he will be pleased to see you.", objectives = "" }
WordHunterWoW_QuestEN[58566] = { title = "Actions Speak Louder than Words", description = "<The ash ghoul inspects you, checking your weapons and armor closely.\n\nHe shifts his eyes from you to your kyrian companions before checking back in with Theotar, who nods to him.\n\nAlwin motions for you to follow him.>", objectives = "" }
WordHunterWoW_QuestEN[58567] = { title = "Skulking in the Darkness", description = "I had only heard tales of the Ember Ward before now.\n\nIt's breathtaking... yet terrible.\n\nThe Light burns the venthyr here, scorching their flesh and driving them mad.\n\nThe only reprieve is darkness, but thugs have taken over every inch of shelter outside of this sanctuary.\n\nThere is no redemption for them. Only justice.", objectives = "" }
WordHunterWoW_QuestEN[58568] = { title = "Light Respite", description = "We passed many ash ghouls on the way here, screaming in pain from their Light-dispensed burns.\n\nAnd after meeting Alwin and the others here, my heart aches for them.\n\nThey have lost much of who they once were, and suffer daily for it.\n\nPlease, collect some berries from the Ashen Traverse. I believe I could impart anima into them to create a healing salve to soothe their wounds.\n\nIt is the least I can do.", objectives = "" }
WordHunterWoW_QuestEN[58569] = { title = "The Folly of Envy", description = "<Alwin points at a venthyr on the ledge above.\n\nHe lets out a slight, low rumble.>", objectives = "" }
WordHunterWoW_QuestEN[58570] = { title = "Parting Words", description = "With the seal in hand, we must return to Bastion.\n\nAlwin has received his justice. He has bequeathed the seal to our care.\n\nLet us say our goodbyes at the Sanctuary of the Mad, then head home.\n\nI look forward to returning to the blue skies and open fields of Bastion.", objectives = "" }
WordHunterWoW_QuestEN[58571] = { title = "The Seal of Contrition", description = "Preparations for the Seal are complete.\n\nGo, insert it into the Crest. Be delicate, yet firm! Move with purpose, but a steady hand.", objectives = "" }
WordHunterWoW_QuestEN[58575] = { title = "Stuff We All Get", description = "A lot of competitors meet their end in the Theater of Pain. But their weapons are still good as new!\n\nIt can get expensive to equip a fresh recruit, especially if you're not sure they'll survive their first bout. That's why we outfit them with \"slightly used\" armaments.\n\nGather them up for me, would you? Can't let a good weapon go to waste!", objectives = "" }
WordHunterWoW_QuestEN[58582] = { title = "Return of the Black Prince", description = "<The envelope contains a message from Valeera Sanguinar.>\n\n{name},\n\nI have just returned from a meeting with King Wrynn in Stormwind.\n\nWe have much to discuss.\n\nMeet me at the Great Seal with haste.\n\nAl diel shala,\nValeera", objectives = "" }
WordHunterWoW_QuestEN[58583] = { title = "Where the Heart Is", description = "The Speaker has requested that I send you to aid him and Wrathion in their efforts.\n\nYou have proven yourself a great ally to Azeroth, and I suspect you will have a big part to play in the coming battles.\n\nLet us hope that the rest of the Horde and Alliance can put aside their squabbles to face a common enemy.", objectives = "" }
WordHunterWoW_QuestEN[58584] = { title = "Right our Wrongs", description = "General Kaal was sent here on a mission for Denathrius long ago.\n\nOn that mission, they concealed anima siphons, making their presence impossible to detect, to limit the amount of anima this workshop could use. That destabilized this area. The Forsworn must have noticed this and exploited the weakness.\n\nThese previous actions are in opposition to our goal. Take Theotar and destroy those siphons.", objectives = "" }
WordHunterWoW_QuestEN[58585] = { title = "No Friend of Mine", description = "Tools. I cannot work without my tools!\n\nFamos, my former apprentice, stole them all when she went to the Forsworn.\n\nIt breaks my heart. She had so much promise.\n\nShe must be stopped.", objectives = "" }
WordHunterWoW_QuestEN[58586] = { title = "The Right Stuff", description = "Building something that can help in your mission will require some metal.\n\nThe constructs of the Forsworn have metal parts, suitable for what we need. Tainted by the Forsworn, they will need some additional work.\n\nCollect their metal and smelt them in the flames of the Eternal Forge to purge the corruption.", objectives = "" }
WordHunterWoW_QuestEN[58589] = { title = "The Restless Dreamer", description = "Now that we have the anima we need, we must attune the heart of Tirna Noch to the shrines of Hibernal Hollow. \n\nThen we can bring the wildseed's nightmares into the light and dispel them.\n\nTake the heart to the shrines just outside of Hibernal Hollow, in the Dreamshrine basin. Then bring the heart back to the wildseed to complete the preparations for the ritual.\n\nBut be careful. Minions of the Drust seem to be amassing near the grove.", objectives = "" }
WordHunterWoW_QuestEN[58590] = { title = "Visions of the Dreamer: Origins", description = "The spirit within the wildseed dreams of her birth and youth, in the primordial days of her world.\n\nGo to the first Dreamshrine outside of Hibernal Hollow. Meditate at the shrine, and soothe this vision of how her life began.", objectives = "" }
WordHunterWoW_QuestEN[58591] = { title = "Despoilers", description = "Your efforts at Tirna Noch have enraged the Drust. \n\nThose creatures of decay and destruction swell at our borders, and already they pierce our defenses.\n\nNow we see their real faces, and know the true nature of our foe.\n\nStrike at them. It will buy us time for you to conduct Dreamweaver's ritual.", objectives = "" }
WordHunterWoW_QuestEN[58592] = { title = "Caring for the Caretakers", description = "The Drust attacked so quickly, they captured some of the spirit tenders of this grove!\n\nIt's not an easy job to do, between the drought and monsters and everything. I should know.\n\nPlease, see if you can get them out of whatever terrible magic those invaders have cast on them.", objectives = "" }
WordHunterWoW_QuestEN[58593] = { title = "End of the Dream", description = "The time has come. The ritual will be complete when you have fully entered into the spirit's dreams.\n\nIt will be as if you are her, in every aspect.\n\nShe relives the moment of her death over and over again. It torments her. Something about how she ended... she had no control over her actions. She hurt the ones she loved.\n\nSpeak to me when you are ready to immerse yourself in her nightmare of the end.", objectives = "" }
WordHunterWoW_QuestEN[58595] = { title = "Pillars of Oblivion", description = "In ages past, the black obelisks of the Old Gods would herald the coming of their forces. The dark conjurers among the k'thir and n'raqi would utilize these monuments to establish footholds in our world and usher in more of the Old Gods' minions.\n\nToday, we see these very same obelisks littering the battlefields. So long as they stand, N'Zoth's forces will be without end.\n\nMake sure they do not.", objectives = "" }
WordHunterWoW_QuestEN[58596] = { title = "Specter Of War: Visectus", description = "We have conjured Visectus to lead our attack, but we need your help to prepare it properly.\n\nWe require more anima-bound wraps to strengthen the summons.", objectives = "" }
WordHunterWoW_QuestEN[58599] = { title = "Drive A Dredge Between Them", description = "First, we ruin their operation. Questions can come later.\n\nI scouted from the overlook as we rode in. Necromancers charge crystals full of siphoned anima. Three dredgers stack them onto carts.\n\nKill those dredgers and everything will grind to a halt.", objectives = "" }
WordHunterWoW_QuestEN[58600] = { title = "A Perfect Circle", description = "I've come up with the perfect design to fit your needs--a crown capable of channeling the powers of the Harvesters.\n\nI need one more tool to put it together, a mold. Circular objects difficult to get right.\n\nGo up to my old storage. A perfect mold exists there. I'm sure of it.\n\nPerhaps in one of my old trunks. Go rummage around for it, will you?", objectives = "" }
WordHunterWoW_QuestEN[58603] = { title = "Phaestus, Genesis of Aeons", description = "Missing something sacred.\n\nForsworn ransacked our shrine to the First Forgelite and took her hammer. My hammer!\n\nDefeat their commander, retrieve Phaestus. You must go now!", objectives = "" }
WordHunterWoW_QuestEN[58606] = { title = "A Bit of Investigation", description = "{name}, this may be the discovery of a lifetime!\n\nI cannot yet say with absolute certainty, but I have a suspicion that these insects are known as the aqir.\n\nThe League has few intact records, but the last mention of these creatures describes a great war waged between the C'Thraxxi, aqir, and early troll civilizations.\n\nWe had assumed they were driven to extinction, but they may have simply been... rebuilding.\n\nCould you please collect some samples for me to examine?", objectives = "" }
WordHunterWoW_QuestEN[58608] = { title = "It's Treason, Then", description = "We've halted their efforts, but we still have more to do.\n\nSin'dane must have sent someone to oversee the encampment.\n\nFind and slay whoever is in charge. Only then can we be sure their work has ended.", objectives = "" }
WordHunterWoW_QuestEN[58609] = { title = "Taking The Seat", description = "A wise choice, {name}. Under your command, we will restore honor and glory to Maldraxxus.\n\nYour strength can change the Shadowlands for the better. Only with the Necrolords will you reach your full potential.\n\nFor now, make your way to the Seat of the Primus. Baroness Draka will meet you there and guide you further.", objectives = "" }
WordHunterWoW_QuestEN[58610] = { title = "The Speaker of Elune", description = "Fortune smiles upon us, {name}. We have found a soul in Ardenweald who was once a Night Warrior in life, as Tyrande is now. \n\nHis name is Thiernax. I am told he assists in tending to the spirits resting in the Garden of Night.\n\nSeek him out and petition him for aid. I pray he will have wisdom to share.", objectives = "" }
WordHunterWoW_QuestEN[58615] = { title = "Whispers in the Dark", description = "Did ye hear that as well? That cannae be good.\n\nIf N'Zoth gains access tae this chamber, we'll all be done for! \n\nWe need tae figure out where he's accessing the chamber and shut it down, before he does more than just whisper at us!", objectives = "" }
WordHunterWoW_QuestEN[58616] = { title = "Forging a Champion", description = "Of all the souls who have reached that stone, only you discovered its true purpose.\n\nI am no zealot, but clearly there is a deeper meaning in this. We would be wise to investigate further.\n\nFind Bonesmith Heirmir at her forge. She is the most renowned smith in Maldraxxus, and the last remaining apprentice of the Primus himself.\n\nShe will know what course to take.", objectives = "" }
WordHunterWoW_QuestEN[58617] = { title = "Maintaining Order", description = "Communication is the key to victory. The greatest strategists are rendered useless if their orders go unheard.\n\nDeliver my orders to Summoner Perex, Drill Sergeant Telice, and Secutor Mevix.\n\nAnd do it quickly. Every moment we waste is one our enemy will have to their advantage!", objectives = "" }
WordHunterWoW_QuestEN[58618] = { title = "Ossein Enchantment", description = "A potent blade requires potent components. I know of something that would suit our needs.\n\nRecently a monstrosity trained by the constructs was snared by our soldiers at the eastern side of our stronghold. Vyraz insists we can siphon \"intelligence\" from the beast's mind.\n\nHmph. The will of the Primus trumps the desires of an ambitious baron!\n\nThe bones of that beast would forge the perfect hilt for this blade. I say you lay claim to them.", objectives = "" }
WordHunterWoW_QuestEN[58619] = { title = "Read Between the Lines", description = "Ah, mortal, how fortunate that I, humble Ta'eran, happen to be standing here just as you, the outsider everyone is talking about, happens to wander by!\n\nIn the spirit of cooperation and mutual interests, there is a matter I wish to discuss.\n\nA nearby structure called the Sepulcher of Knowledge was built as a repository for military strategy. I fear the knowledge contained within may soon be lost.\n\nIf you would do me the honor of escorting me to the Sepulcher, I can share what else I know.", objectives = "" }
WordHunterWoW_QuestEN[58620] = { title = "Slaylines", description = "Gaining entrance to the Sepulcher is no easy feat, {name}!\n\nNot only were guardians put in place, but an elaborate magical lock was created to seal the door. \n\nTo open the way, the two obelisks which control the lock must be fed anima. Fortunately, there are some empowered crystals in the area we can use for this purpose.\n\nLocate the focus crystals and redirect their anima flow into the obelisks. Then the secrets of the Sepulcher will soon be ours!", objectives = "" }
WordHunterWoW_QuestEN[58621] = { title = "Repeat After Me", description = "The Primus placed guardians in the area around the Sepulcher to protect the knowledge within. Each embodied the virtues of one of the five houses.\n\nTo gain entrance, you must prove yourself worthy by besting these protectors. \n\nSeek out the rune stones that represent the houses of Maldraxxus. Pay attention to the words inscribed on each stone, then pay deference each house's values.\n\nIf you honor the stone, its protector will come forth. Defeat each of them.", objectives = "" }
WordHunterWoW_QuestEN[58622] = { title = "Secrets Among the Shelves", description = "Now that the door to the Sepulcher is unlocked, we can venture inside.\n\nAnd by \"we\", I mean \"you\". Until it's safe, at least.\n\nThe volumes within contain the collected wisdom of the greatest military minds of Maldraxxus. For the good of the Necrolords, do whatever is needed to gather these precious volumes.\n\nIt is safe to assume that the books will be protected by traps. The Primus wouldn't want just anyone laying their hands on this knowledge.\n\nOnce you clear a path, I'll join you.", objectives = "" }
WordHunterWoW_QuestEN[58623] = { title = "A Complete Set", description = "This is only volume one?\n\nWe can't just take the first volume. A rare item like this is only useful if it's in a complete set!\n\nGrab as many of the other volumes as you can, I will have to prepare a larger expedition to remove all of these volumes.", objectives = "" }
WordHunterWoW_QuestEN[58624] = { title = "Pauldrons of Imperium", description = "Now we know who is responsible for the unrest in Maldraxxus.\n\nIf Kel'Thuzad has allied with the Banished One, then he wields greater power than anyone realizes. \n\nWe must lay siege to the House of Rituals, but we need time to prepare. Attacking without a flawless strategy will only ensure our defeat.\n\nFor now, return the pauldrons to the Seat of the Primus. I will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[58625] = { title = "Connecting the Dots", description = "The old baron for the House of the Chosen? Ah, yes! I do think I remember seeing him! An angry soul, but very good at fighting.\n\nHe went off to meet with some member of the House of Rituals. There were a few of his guards with him.\n\nWhile it's been quite some time since he passed this way, you may be able to find some signs of where he went towards the old footpath up the mountains.", objectives = "" }
WordHunterWoW_QuestEN[58630] = { title = "Crown of the Harvesters", description = "Power you seek to focus is volatile. Need the Eternal Forge's flames to get it done. \n\nWithout the blessing of the flames, I fear it will overwhelm the wearer.\n\nBring venthyr friend. His magic will prove useful. Need you to absorb impurities. \n\n<Mikanikos hands you an elegant container.>\n\nUse this to capture imperfections that burn off during the process.", objectives = "" }
WordHunterWoW_QuestEN[58631] = { title = "Into Dreams", description = "I cannae believe that Ra-den sacrificed himself to save us. We cannae give up on him!\n\nThere must be a way tae find out where he went. \n\nLet's see if MOTHER can track him down!", objectives = "" }
WordHunterWoW_QuestEN[58632] = { title = "Ny'alotha, the Waking City: The Corruptor's End", description = "Usin' the mogu's research, MOTHER and Ra-den found a way tae focus the forge's Origination Protocol through the Chamber of Heart. The only problem was findin' out where tae shoot it.\n\nThat is, until now.\n\nTake these anchors and head through that portal. Ye'll need tae find some prominent landmarks tae place 'em so we can focus the weapon. Once they're set, we'll be ready tae fire.\n\nYe'll only get one shot. Make it count!", objectives = "" }
WordHunterWoW_QuestEN[58634] = { title = "Opening the Gateway", description = "The fabric of reality is torn. But there's no need for me to tell you that, {name}. You've seen it firsthand. \n\nIt's only a matter of time before these realities become one, veiled in eternal darkness. Instead of hiding, perhaps it's time we embraced the darkness.\n\nWith the help of our titan friend here we may be able to thread the needle of this reality through the fabric of another, creating a bridge of sorts.\n\nAfter all, the key to understanding an enemy's weakness is to understand their intentions.", objectives = "" }
WordHunterWoW_QuestEN[58636] = { title = "Eyes on the Amathet", description = "On behalf of the Explorers' League, I'd like tae thank ye for helping establish the Uldum Accord and buying us some cooperation from Ramkahen.\n\nIn the interest of better understanding our foes, Ramkahen has allowed the exploring of the Amathet tombs. Unfortunately, though, their forces are spread too thin to provide protection.\n\nI was hopin' ye could help out with that. \n\nThink ye could spare some time tae see what they're all about? We can start with an aerial look.", objectives = "" }
WordHunterWoW_QuestEN[58638] = { title = "A Deeper Dive", description = "Something just isn't adding up about these Amathet. Why would protectors of titan works attack and damage the Forge of Origination?\n\nI think we need tae take a closer look. I think I saw a monument on the terrace over there. Perhaps the writings there could tell us more about these tol'vir.", objectives = "" }
WordHunterWoW_QuestEN[58639] = { title = "Buried History", description = "Since the Amathet came from this region, it would only stand to reason that artifacts from their civilization would be left behind here, hidden beneath the sands.\n\nIt looks like it's time for a good old-fashioned dig!\n\nThe dunes near here must have covered up a large swath of the Amathet's former territory. Let's see what we can dig up there!", objectives = "" }
WordHunterWoW_QuestEN[58640] = { title = "A Crack in the Armor", description = "The artifacts you helped excavate show the Amathet as a tribe who prided themselves on protecting the works of the titans. \n\nThis confirms our assumptions, and indicates that something drastic must have happened to them to cause them to damage the very works they swore to protect.\n\nWe should continue to track down their writings. I think I saw a more recent monument outside the Halls of Origination.", objectives = "" }
WordHunterWoW_QuestEN[58641] = { title = "Seekers of Corruption", description = "If anyone would know more about the \"corruption\" the tablet spoke of, it would be the Suntouched that were put in charge of rooting it out.\n\nOf course, I doubt they'll be willing to turn over any information voluntarily.\n\nLuckily for me, you're a bit of a specialist at brute force investigation, aren't you?", objectives = "" }
WordHunterWoW_QuestEN[58642] = { title = "Shared Goals", description = "The decree you found made mention of a plan to defeat the Old Gods. \n\nI know that the Amathet aren't likely to work with us toward that goal, but if they have a plan tae take out N'Zoth, it's worthwhile for us tae look at it.\n\nThe decree mentions the Engine of Ascension. I think that might be what they call that solar empowering device we saw earlier. We should take a peek underneath and see if we can figure out what they're planning!", objectives = "" }
WordHunterWoW_QuestEN[58643] = { title = "Mutually Assured Destruction", description = "The Amathet want tae re-take the Forge of Origination so they can use it tae end all life on Azeroth, Old God or otherwise! \n\nThey could strike at any moment. We have tae warn the defenders of the Forge!", objectives = "" }
WordHunterWoW_QuestEN[58644] = { title = "Gather Our Forces", description = "I've finished the mirror!\n\nInform the others that we are ready to invade Maldraxxus!", objectives = "" }
WordHunterWoW_QuestEN[58645] = { title = "A World Worth Saving", description = "We could not stand against them. Their warriors... wreathed in the sun's flames...\n\nThey want the forge... to end all...\n\nGo... I will... endure...", objectives = "" }
WordHunterWoW_QuestEN[58646] = { title = "Chew On This!", description = "These mangy hyena will gnaw on anything they dig up, including priceless artifacts!\n\nWe cannae allow the history of Uldum tae go tae the dogs, so tae speak.\n\nI'm afraid we're gonna have tae thin out their numbers.", objectives = "" }
WordHunterWoW_QuestEN[58647] = { title = "Broken Webs", description = "My husband once served our people as the Speaker of Elune--until he became the Night Warrior. His feelings on the matter are... complicated, to say the least.\n\nSpriggans have been ripping the garden's soulwebs. Would you please help me repair them? I will recount our story as we work.", objectives = "" }
WordHunterWoW_QuestEN[58654] = { title = "A Plea to the Harvesters", description = "You come during strange times. Every day the tithes we must pay to the Tithelord increase, and our ability to get anima dwindles. \n\nWhat souls we have to work with here are near their final judgment and we lack the resources to harvest them without endangering the hamlet.\n\nIf you have the ear of Lord Chamberlain, then you might be able to pass a message to the Master himself. \n\nHere, take this letter. Please see that it makes it to the hands of the Chamberlain.", objectives = "" }
WordHunterWoW_QuestEN[58656] = { title = "Heavy is the Head...", description = "Crown is unstable due to Sire's lingering influence from the medallions. A test run should solve.\n\nSocketed one of your medallions. Witness its power focused into a weapon of destruction. \n\nPerfect opportunity. Forsworn finished colossi construction. Destroy them.  Bring the Forsworn the end they crave. \n\nCareful. Theotar informed me how powerful magic this is. The crown will hunger, must control it.", objectives = "" }
WordHunterWoW_QuestEN[58664] = { title = "Ultimate Makeover", description = "We now control the Apparatus of Abominable Construction! We can use it to create new constructs to contain worthy souls.\n\nEmeni is the best choice to be first. Her combat skills are unmatched, and you may need her to help secure the Stitchyard.\n\nYou will assist me in rebuilding Emeni's construct.", objectives = "" }
WordHunterWoW_QuestEN[58665] = { title = "Rebellious Souls", description = "Please hear us out, Maw Walker.\n\nWhen Margrave Gharmal launched his attack on Bastion, there were many, such as Emeni and myself, that opposed his actions. \n\nFearing dissent, Gharmal removed many souls from their constructed bodies and imprisoned them. Emeni escaped the prison, but most did not.\n\nHelp us free the other souls, and we can build you an army of constructs far greater than any that serve Gharmal.", objectives = "" }
WordHunterWoW_QuestEN[58668] = { title = "Find The Way", description = "I apprenticed at the Stitchyard for many eons. I even worked in the Body Banks with surgeon Stitchflesh to design Emeni's last construct.\n\nIf we gain control of the Body Banks, we will have the parts necessary to rebuild Emeni and create new bodies for other souls we rescue. \n\nLead us to there and we'll see if we can get it operational.", objectives = "" }
WordHunterWoW_QuestEN[58669] = { title = "A Little Pruning", description = "Spriggans sometimes invade the garden to spread mischief and mayhem. There is no end to the trouble they bring with them.\n\nUsually, the Wild Hunt keeps them in check... but their huntsmen and huntresses have had far more pressing concerns as of late. Thiernax and I have been helping to keep the garden clear, but he's run off somewhere to brood.\n\n<Qadarin shakes his head.>\n\nYou would be doing me a favor if you helped me clear the Queen's garden of these vermin.", objectives = "" }
WordHunterWoW_QuestEN[58670] = { title = "The Slaughter Daughter", description = "When I was locked up, I made a list of all the constructs that betrayed me... it is a lengthy list!\n\nHelp me teach these constructs the mistake they made. I want to destroy everyone on my list, along with Yardmaster Pralak, who is number one on the list!", objectives = "" }
WordHunterWoW_QuestEN[58671] = { title = "Bottled Up Inside", description = "There were many souls that opposed Margrave Gharmal's attack on Bastion. Those of us that spoke out, were stripped our bodies, imprisoned in the Etheric Vault, till our souls faded away, starved of anima.\n\nMy friends are still imprisoned in the vaults. We will free them, and build an army of constructs to fight for you!", objectives = "" }
WordHunterWoW_QuestEN[58672] = { title = "A Gathering of Champions", description = "The leaders of the Horde are gathering together in Orgrimmar to nominate a new Warchief of the Horde.\n\nAs a champion of the Horde, your presence at the meeting has been requested. The gathering will be held at the embassy in Orgrimmar.\n\nI will be going on ahead. Come speak with me when you arrive in Orgrimmar, I'll be waiting with the others.\n\nMake haste, champion. The future of the Horde is about to be decided...", objectives = "" }
WordHunterWoW_QuestEN[58673] = { title = "Warchief of the Horde", description = "The meeting to decide the next Warchief of the Horde is about to begin.\n\nThe other leaders of the Horde have already arrived. They are waiting for you inside the embassy.\n\nSpeak with me when you are ready, and we will greet the others together.", objectives = "" }
WordHunterWoW_QuestEN[58674] = { title = "A Gathering of Champions", description = "King Wrynn has called for an audience with the Alliance leaders in Stormwind.\n\nYour presence at the meeting has been specifically requested. The gathering will be held at the embassy.\n\nCome speak with me when you arrive in Stormwind, I'll be waiting with the others.\n\nDo hurry, {name}. It would be ill-advised to keep the king waiting...", objectives = "" }
WordHunterWoW_QuestEN[58675] = { title = "The Price of Peace", description = "The king will be addressing us shortly with news from his diplomatic mission to the Horde.\n\nThe other leaders of the Alliance have already arrived. I am sure they are eager to hear what King Wrynn has to say.\n\nSpeak with me when you are ready, and we will greet the king together.", objectives = "" }
WordHunterWoW_QuestEN[58677] = { title = "Skin in the Game", description = "This task is probably above your capabilities, but listen anyway.\n\nAs a construct I was feared throughout the Shadowlands. The magnificent skin of my construct was impervious to mortal weapons, it was a work of art that took years to perfect.\n\nWhen I was removed from my construct, it was Faldo Iscar who took great delight in stealing that skin. He keeps it on himself as a souvenir.\n\nKill Faldo Iscar, and get my skin back!", objectives = "" }
WordHunterWoW_QuestEN[58680] = { title = "Loose Threads", description = "We're missing a few tools and parts for sewing a construct. We need these items if we're to rebuild my construct!\n\nSearch the surrounding area. See if you can find us what we need.\n\nSearch tables for the Skewering Needles, you can find haulers that carry Razorthread Spools, and look for Clotting Patches on constructs you kill.", objectives = "" }
WordHunterWoW_QuestEN[58686] = { title = "Weapon of Mass Construction", description = "We are in luck!\n\nSurgeon Stitchflesh and his assistant have not returned from Bastion.  The entire Stitchyard is lightly guarded.\n\nWe must work fast. See if you can get the equipment operational. Once it is active, we can begin the construction process.", objectives = "" }
WordHunterWoW_QuestEN[58704] = { title = "The Garden of Night", description = "That should take care of things out here. Now we must tend to the inner garden. Once we're done, I'll sort out my recalcitrant husband.\n\nHopefully, any remaining spriggans will have cleared out on their own after hearing us dispatch the others.", objectives = "" }
WordHunterWoW_QuestEN[58706] = { title = "Dressing the Kill", description = "<Huln listens to your explanation, then pauses thoughtfully.>\n\nI believe I understand, {name}. But I cannot help you right now.\n\nAllow me to explain. In the meantime, will you carve up this carcass with me? Your prey always has something to teach you.", objectives = "" }
WordHunterWoW_QuestEN[58708] = { title = "Fame Waits for Gnome One", description = "Tinkmaster Overspark requests your assistance on an important research expedition. \n\nWorking with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!", objectives = "" }
WordHunterWoW_QuestEN[58714] = { title = "The Forest Has Eyes", description = "That dream! With the teeth and the claws and the heart... heart-wrenching sacrifice?\n\n<Moonberry chokes up for a moment then collects herself.>\n\nSorry! While we were in dreamland, possessed spies have snuck into Hibernal Hollow! \n\nThey must be hunted down and slain before they can report back on the grove's defenses.\n\nHere, borrow a bit of my magic. Seek out the ones hidden in the shadows and smite them!", objectives = "" }
WordHunterWoW_QuestEN[58717] = { title = "Bell of Remembrance", description = "<The bell is scratched and damaged. You remember the Curator being very interested in this item.\n\nMaybe someone at the Crypt of the Forgotten will know more.>", objectives = "" }
WordHunterWoW_QuestEN[58719] = { title = "The Droman's Call", description = "Our enemies close in swiftly, {name}. We must sound the call to defend the grove!\n\nUse this horn to call upon our protectors. Summon the Wild Hunt to slay those who would attack us.", objectives = "" }
WordHunterWoW_QuestEN[58720] = { title = "Missing!", description = "The Wild Hunt has answered the call to defend us... except for Hunt-Captain Korayn and her forces.\n\nShe had led her hunting party to the west, on the trail of a powerful foe. They may have encountered trouble.\n\nFind her and provide whatever aid she requires. \n\nWe need her hunters and her leadership if our defenses are to hold.", objectives = "" }
WordHunterWoW_QuestEN[58721] = { title = "Awaken the Dreamer", description = "Much of the Queen's focus has centered on the Grove of Awakening, where rejuvenated spirits emerge from their wildseeds and return to their worlds.\n\nPerhaps it is fitting you carry a wounded spirit with you.\n\n<Lord Herne studies Ysera's wildseed for a moment before a slow grin spreads across his face.>\n\nThis one fights with all of her being. Even now she clings to existence. \n\nCome, stranger, let us see what fate the Queen will decree for this one.", objectives = "" }
WordHunterWoW_QuestEN[58723] = { title = "The Court of Winter", description = "My Court informs me that you bear an important message.\n\nYou may now deliver it.", objectives = "" }
WordHunterWoW_QuestEN[58724] = { title = "The Queen's Request", description = "Dire portents indeed. \n\nI have used what little anima we possess to save our groves and the spirits they nurture. So many were lost... all as the Heart of the Forest grew ever weaker.\n\nKeeping the Banished One bound within the Maw will require more anima than Ardenweald can spare.\n\n<The Queen considers for a moment.>\n\nSire Denathrius is a master of anima extraction. Journey to Revendreth and inform him of our plight. I know he will lend us his aid.\n\nYour allies in Oribos can open the way.", objectives = "" }
WordHunterWoW_QuestEN[58725] = { title = "Sinkeeper", description = "This is a Bell of Remembrance. Before the recent... \"events\" we used them to beckon souls from the Crypt of the Forgotten to deem their fate. \n\nIf they are less arrogant than they were before, they may continue in the process. If not, they must spend additional time in the crypt.\n\nLet's put this one to use, shall we? It's pretty beat up, let's hope we can get at least one use out of it.", objectives = "" }
WordHunterWoW_QuestEN[58726] = { title = "Thick Skin", description = "The Primus forged a fine blade, but it will do you no good in its current state.\n\nFortunately for you, I possess the skill to finish his work!\n\nThat being said, I will require materials. The other Chosen have been too preoccupied with their combat drills to assist me at the forge, even as they demand more weapons and armor.\n\nThat's where you come in. You want a new blade? You'll have to earn it.", objectives = "" }
WordHunterWoW_QuestEN[58727] = { title = "A Place To Call Home", description = "You didn't end up on my list... so, I guess we're friends... for the moment.\n\nRathan took the soul you freed to Butchers Block near the Seat of the Primus. \n\nLet us meet him there and plan our next step together.", objectives = "" }
WordHunterWoW_QuestEN[58728] = { title = "A Promising Lead", description = "Your arrival is timely, {name}. Huln has just returned from his search.\n\nLet us hear his report and find more Night Warriors. We cannot afford to delay.", objectives = "" }
WordHunterWoW_QuestEN[58729] = { title = "Night and Day", description = "A Night Warrior? Never heard of it.\n\nI'm afraid that I don't remember any of that! Perhaps you could help me jog my memory. \n\nWill you walk with me while I make my rounds? There's so much to do around here, but I can usually manage. I won't say no to some helping hands, though.", objectives = "" }
WordHunterWoW_QuestEN[58730] = { title = "Deep Thoughts", description = "Do not look so worried, {name}! Of course I'll help you and your friends.\n\nI'm still not entirely sure how to do that, but I felt a deep memory when you mentioned this Tyrande. It is clear that she has friends who care deeply about her, and I want to help!\n\nMemories this ancient can only be safely retrieved at the Archival of Memory to the east. Meet me there and let's see who I was during my lifetime!", objectives = "" }
WordHunterWoW_QuestEN[58731] = { title = "A Shattered Vessel", description = "There is a machine that can extract the memory, but we will need to bring a few things.\n\nMemories in Bastion are stored in glass prisms, to be archived for eternity. We will need one of our own to make the device function properly.\n\nNormally this wouldn't be a problem, but I think with all of... this... going on, finding an intact crystal will be difficult.\n\nNot to worry though! If we can get enough pieces of glass, the machine should be able to repair them.\n\nGrab as many pieces as you can find!", objectives = "" }
WordHunterWoW_QuestEN[58732] = { title = "The Stuff of Memories", description = "We're going to need a lot of anima to make this work.\n\n<Selendis's voice drops to a conspiratorial whisper>\n\nI don't know if anyone has told you, but we're running a little short on it at the moment.\n\nAnima is required to make the machine work, not to mention we'll need some to rebuild the memory prism, and honestly more anima never hurt anybody.\n\nThe devices here are attuned to dealing with memories, so any anima you can get from this area will be particularly useful. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[58733] = { title = "Animamnesis", description = "We have everything we need to begin the ritual.\n\nI... I don't know what's going to happen. I thought my memories were all gone, but clearly some are buried deeper than any of us knew.\n\nThe device will pull the memories out for us to confront. Once we begin, there is no going back.\n\nSpeak to me when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[58734] = { title = "[PH] Get Memories from Archives", description = "We are going to need a little bit of preparation before we can face Voras.\n\nThe gorm of Ardenweald have developed special digestive juices that can isolate and dissipate anima in their food. It causes the devourers no small discomfort.\n\nFor a beast of that size, we will need a lot of the stuff to have any effect. Let us head to <HIVE MIND> and find a suitable one.\n\nAre you familiar with the use of a rod of reclamation? It is quite useful against the gorm. You can borrow mine.", objectives = "" }
WordHunterWoW_QuestEN[58735] = { title = "Path of Totality", description = "There's no turning back now, friend.\n\nThat prism contains the truth. The truth of the Night Warrior. My past.\n\nThe only way to remember is to relive it. Let's use the prism and find out who I really am.", objectives = "" }
WordHunterWoW_QuestEN[58736] = { title = "Selenis, Night Warrior", description = "I understand, now. What it means to be a Night Warrior.\n\nThe power, it was far too much for me to control. I surrendered to it almost immediately, and look what it did.... While I do not regret my decision or lament my fate, I do not wish to see anyone suffer as I did.\n\nCome, let's meet your friends. I will happily do what I can to help.", objectives = "" }
WordHunterWoW_QuestEN[58737] = { title = "Magni's Findings", description = "As if gettin' the Forge back up and runnin' wasn't good enough, I think we may have found the key tae takin' out N'Zoth once and for all in the archives of Mogu'shan Vaults!\n\nYe might want tae be sittin' down for this one, champion.", objectives = "" }
WordHunterWoW_QuestEN[58740] = { title = "Subjugated Serpents", description = "Where the Zan-Tien march, the warserpents are sure to follow.\n\nI cannot stress to you enough how dangerous these beasts are. It is a shame to see them subjugated by the mogu, but we cannot afford to let them run rampant.\n\nI need you to put them down before they can wreak havoc on our lines.", objectives = "" }
WordHunterWoW_QuestEN[58741] = { title = "Cutting Stone", description = "One problem with waging war against other mogu is that weapons dull and break very quickly when used against foes of stone and metal. \n\nBeing the sole blacksmith among the Rajani, it is sometimes difficult to keep up with our warriors needs.\n\nIf you come across any weapons in your battles with the mogu, I'm sure I could put them to good use.", objectives = "" }
WordHunterWoW_QuestEN[58750] = { title = "Take the Bull by the Horns", description = "I've carved out quite the reputation as a tauralus wrangler. Everyone needs a tauralus!\n\nYou do some work for me, and people will know who you are as well.\n\nTake this bone splinter and poke a few juicy nibblers. Use them to lure a tauralus to you, then ride it back to me.", objectives = "" }
WordHunterWoW_QuestEN[58751] = { title = "A Common Peril", description = "Each house in Maldraxxus has two barons. Before the fall of my first house--the House of Eyes--our margrave sent my fellow baroness to investigate suspicious behavior in the House of Rituals.\n\nI have not heard from her since. Either she has found something... or has become another casualty of their treachery. \n\nHer orders took her to the Decay in the east. If you can find the baroness, give her this summons. \n\nWe were not friends, she and I, but she is a formidable combatant. We could use her might.", objectives = "" }
WordHunterWoW_QuestEN[58754] = { title = "Champions of the Swarm", description = "It is clear that Shek'zara is fully committed to this invasion. Our scouts have spotted some of her greatest champions among the battlefield.\n\nAny one of these mantid could prove too much for the soldiers of the Golden Lotus to overcome. We must hunt them down and eliminate them ourselves.\n\nAre you in?", objectives = "" }
WordHunterWoW_QuestEN[58755] = { title = "Stashed Supplies", description = "The invading mantid have been making off with the Golden Lotus' supplies lately. They're probably hoping  they can starve us out.\n\nWell, they may be right if we can't get some of our supplies back. \n\nWhile you're taking the fight to the swarm, keep an eye out for anywhere they might have stashed our supplies. You'd be doing the Golden Lotus a big favor if you could recover some.", objectives = "" }
WordHunterWoW_QuestEN[58756] = { title = "Dread Menders", description = "The ambercasters are among the highest castes of mantid society. Through their magic, they can mend and form amber to their will, allowing hastened recovery of the mantid's forces after a battle.\n\nThey are strategic targets, and we should seek them out. \n\nCare to join us?", objectives = "" }
WordHunterWoW_QuestEN[58757] = { title = "Testing the Untested", description = "During a swarm, the mantid send their youngest in great numbers against the enemy to test their mettle. Those who survive join the swarm as true warriors of the mantid.\n\nWe should do our best to ensure that they don't make it through this test.", objectives = "" }
WordHunterWoW_QuestEN[58758] = { title = "Rampaging Destroyers", description = "The last mantid swarm is still very fresh in the memory of the Golden Lotus. Prior to the advancement of the swarm, the mantid would send their massive kunchong to soften up the defenders' lines.\n\nIt would seem their tactics have not changed.\n\nWe must stop those kunchong if the Golden Lotus hope to mount a defensive against the swarm. I'm counting on you to strike them down.", objectives = "" }
WordHunterWoW_QuestEN[58759] = { title = "The Empress' Guard", description = "The Zara'thik are the empress' elite guard. Empowered with plundered Azerite, they will stop at nothing short of absolute conquest of all of Pandaria.\n\nIf we allow them to advance past the Serpent's spine, the Golden Lotus will be no match for them.\n\nStop them at the wall, {class}.", objectives = "" }
WordHunterWoW_QuestEN[58760] = { title = "Blades of Amber", description = "The mantid are frail and easily broken, but the amber blades they wield are formidable.\n\nWith a bit of work, they could be reshaped into something suitable for the mogu.\n\nBring them to me, and I can see about repurposing them to service the Rajani.", objectives = "" }
WordHunterWoW_QuestEN[58761] = { title = "Crushed Underfoot", description = "In the past, the mantid would safeguard their hatchlings in incubation chambers until they were ready to be tested in the swarm. \n\nThese Vil'thik are sloppy, however, allowing their larvae to scurry out in the open. \n\nWouldn't it be a shame if someone crushed them?\n\nNo, of course it wouldn't.", objectives = "" }
WordHunterWoW_QuestEN[58762] = { title = "Taken by the Swarm", description = "There's something different about this mantid swarm. Instead of just killing everything in sight like the mantid usually do, they've taken to capturing our defenders and holding them alive.\n\nI really don't want to know what they have in store for the captives. \n\nWhy don't you go rescue them so we don't have to find out?", objectives = "" }
WordHunterWoW_QuestEN[58763] = { title = "Halting Production", description = "The mantid use amber in nearly all aspects of their lives, from the structures they live in to the weapons they wield. Of course, I'm more interested in the latter.\n\nIf we can deprive the mantid of their materials, we will deprive them of their means to create implements of war.\n\nFind where they keep their amber and make sure they are unable to use it.", objectives = "" }
WordHunterWoW_QuestEN[58764] = { title = "Standards of the Swarm", description = "The brazen mantid think they've already won. Even now, they fly banners along the Serpent's Spine, announcing their dominance.\n\nThey must learn that Pandaria belongs to the pandaren.\n\nBurn their banners down.", objectives = "" }
WordHunterWoW_QuestEN[58765] = { title = "Siege Breaker", description = "The Golden Lotus can hold their own against the mantid's warriors, of that I have no doubt. Their war wagons, on the other hand, have the capability of crippling an entire squad of our fighters in a single volley.\n\nIf we wish to maintain the upper hand in this battle, we will need someone to infiltrate their positions and sabotage their siege engines.\n\nI would like you to volunteer.", objectives = "" }
WordHunterWoW_QuestEN[58769] = { title = "REUSE ME", description = "Suddenly the lack of fae and souls makes much more sense. These vile creatures must have taken them as they took my husband.\n\nBut I will get them back. If you are our new champion then you will help me for the good of Ardenweald.\n\n<Thiernas snorts.>\n\nDeath did not part us. I will not be torn from him now.", objectives = "" }
WordHunterWoW_QuestEN[58771] = { title = "Directions Not Included", description = "Look at this place! What a mess. The Locus is inactive and these \"Forsworn\" have taken over.\n\nWe need to restore the Locus, but I do not know how. This place is not of my design, built long, long ago.\n\nLuckily, the previous Forgelite Prime was prolific. Recorded everything! If we can find her designs, I can certainly work it out. Even without Mnemis's help.\n\nLook around. Plenty of scrolls strewn about. Meet me near the Locus when you find what I need.", objectives = "" }
WordHunterWoW_QuestEN[58773] = { title = "The Thornspeaker Captive", description = "Good to know the old bear hasn't forgotten me.\n\nUnfortunately, neither have the Drust. I was enjoying a peaceful afterlife before they showed up.\n\nDo not bother trying to force open this cage. You can only unlock it with three separate keys, and each one is held by a different Drust commander.\n\nThey should be somewhere nearby. Find them.", objectives = "" }
WordHunterWoW_QuestEN[58774] = { title = "[REUSE AS WQ]", description = "They're draining us of our anima! Some of the weaker souls... They are close to danger. They need anima or they will lose cohesion and drift. Such a thing is dangerous, especially now with how imbalanced things are in Ardenweald.\n\nI can spare some of my own energy, but I will not have enough for everyone.\n\nChoose, champion. Who will be saved today?", objectives = "" }
WordHunterWoW_QuestEN[58775] = { title = "Meet the Queen", description = "{name}, we need only one more piece to complete the Crest of Ascension.\n\nEons ago, our Crest was originally crafted with the assistance of the fae. Deep within Ardenweald lies a portal they maintain to ferry souls back to their worlds. It is a source of great power and the final key to rebuilding the Crest.\n\nSeek out the Winter Queen in Ardenweald and plead our case. We've already sent Pelagos ahead as our envoy to arrange for your meeting.", objectives = "" }
WordHunterWoW_QuestEN[58776] = { title = "Hatching Problems", description = "The aqir are multiplying faster than we can put them down. If this pace continues, we will be outnumbered before long.\n\nThe only way to slow down their assault is to attack their hives directly and destroy their eggs, but we have been unsuccessful in doing so.\n\nThat's why I wish to conscript your services.\n\nWill you help?", objectives = "" }
WordHunterWoW_QuestEN[58777] = { title = "Put Your Foot Down", description = "<Zahra stomps on a slimy, slug-like creature as you approach.>\n\nYou see that? Doesn't look like much, but believe it or not, those bugs grow out of these things.\n\nThey're all over the places the aqir have taken over, feeding off of our dead and growing into these monstrosities.\n\nIf you happen to see any of them, do the world a favor and take your boot to 'em.", objectives = "" }
WordHunterWoW_QuestEN[58778] = { title = "Getting Ahead", description = "Morale's been down at the camp lately. Funny how getting chewed on by some bugs can spoil the mood of a place.\n\nI've got an idea to perk the troops back up, though. We need a trophy!\n\nSee if you can get me the head of one of those big tanky-looking ones so we can put it on display to show these bugs that we mean business! Just try to make sure it's not too mangled, okay?", objectives = "" }
WordHunterWoW_QuestEN[58779] = { title = "Taking the Skies", description = "I'd like to see if we can get some more of these flyers in the air to drive back the aqir, but it's nearly impossible to get back to the Obelisk of the Sun with all these bugs in the air.\n\nI think we're going to have to thin them out on the ground before we can hope to gain aerial superiority.\n\nCan I count on you to lend a hand?", objectives = "" }
WordHunterWoW_QuestEN[58780] = { title = "Heralds of the Hive", description = "The aqir that have assaulted our camp seem to mainly consist of their shock troops. However, our scouts who dare venture behind their lines have spotted a different kind of creature -- tall and thin, wielding dangerous void magic.\n\nMy instinct tells me that these creatures are the leaders behind this invasion. They should be seen as targets of opportunity, and cut down wherever they're met.\n\nAre you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[58781] = { title = "Terrors from the Deep", description = "The Aqir threaten the livelihood of the Wastewanders with each passing day, but I have heard of greater terrors that have been unearthed with them.\n\nOur fighters are able, but I fear what might happen if one of these ancient terrors falls upon us. \n\nI know that you have experience putting down great foes. I would like to ask you to do the same for us. \n\nAfter all, we can hardly help protect the forge if we've been decimated by some long-buried monster.", objectives = "" }
WordHunterWoW_QuestEN[58782] = { title = "Things Left Behind", description = "The invading aqir forced the Wastewanders to flee many of our settlements in Uldum. In our haste to escape, much was left behind.\n\nI understand you intend to take the fight to the beasts. While you're there, could you keep an eye out for any of the supplies we had to leave behind? \n\nYou can keep anything of use to you, of course.", objectives = "" }
WordHunterWoW_QuestEN[58785] = { title = "Smack and Grab", description = "Bonetooths are the backbone of Maldraxxus's armed forces. Those that have been trained well are in demand amongst all of the houses.\n \nI always need new bonetooths to train, but they can be rather difficult to collect.\n\nBring me some of the younger ones, and I will reward you greatly. Be advised that you may need to weaken them before you are able to capture them.", objectives = "" }
WordHunterWoW_QuestEN[58787] = { title = "Trial of Ascension", description = "The Forsworn threat is ever looming, and our forces are dwindling. Now, more than ever, we need more Ascended.\n\nOur generous Archon has blessed us with a portion of our anima stores to ascend our top aspirants to join our forces.\n\nKleia is amongst the chosen, and thus must complete her final trial.\n\nAs Pelagos is not yet prepared to ascend, I request you be Kleia's partner for this process. It is arduous and should not be embarked on alone.\n\nShe must bear her first soul.", objectives = "" }
WordHunterWoW_QuestEN[58788] = { title = "Censers of Guidance", description = "The Forsworn are going to great lengths to prevent us from ascension.\n\nThey mobilize to stand in our way, to dismantle our chances to partake in our rituals.\n\nThey have stolen the resources we need to start our trial. Defeat them and retrieve the incense they carry so that we may continue on this path.", objectives = "" }
WordHunterWoW_QuestEN[58789] = { title = "Misguiding Mentors", description = "These aspirants... we trained together. Learned together.\n\nThe Forsworn have swayed them from the path, now leading them to their demise.\n\nThey betray the path. Take out the Ascended that lead these forces against us.", objectives = "" }
WordHunterWoW_QuestEN[58790] = { title = "To Cross the Veil", description = "Pallessa found a scroll detailing the ritual.\n\nWe will need to take our positions and speak a chant, surrendering some of our anima with every word.\n\nYour presence is vital. I ask you to use the censers to burn the incense as we meditate. The rest should unfold on its own.", objectives = "" }
WordHunterWoW_QuestEN[58791] = { title = "A Day in the Life", description = "A Bearer's duty is to carry souls through the veil to Oribos, where they shall be judged and passed along to one of the realms of the Shadowlands.\n\nThis soul is ready to move on.\n\nDuring this trial, you will experience his final moments before his death.\n\nWhen you are prepared, you shall see how this soul passed.", objectives = "" }
WordHunterWoW_QuestEN[58792] = { title = "Where a Soul Belongs", description = "This soul is no longer tethered to his world of Azeroth.\n\nKleia must perform her duty and bear him to Oribos to be judged by the Arbiter.\n\nTake this vesper. When you are ready, it will call Ascended to ferry you back across the Veil to Oribos.\n\nGo in service.", objectives = "" }
WordHunterWoW_QuestEN[58793] = { title = "Faith Through the Darkness", description = "This drought is... so much larger than I imagined.\n\nWhy did nobody tell us?\n\nThe burden of this knowledge weighs heavy... do we bear souls to their eternal torture?\n\nWe must return home.", objectives = "" }
WordHunterWoW_QuestEN[58794] = { title = "Stabbing Wasteward", description = "I've been finding a lot of tauralus corpses lately, and I know it's all because those bonetooths Caleesy loves so much!\n\nI spotted the one that's responsible for the slaughter just west of here. Get rid of it! \n\nAnd don't mention this to Caleesy!", objectives = "" }
WordHunterWoW_QuestEN[58795] = { title = "Ascended", description = "With success over their trials, our aspirants shall now start the next chapter of their afterlives.\n\nThey have proven themselves through eons of training and cleansing, and will now earn ascendance.\n\nAs each aspirant is called, I ask you and Pelagos to please assist by ushering them up. It is a tradition we have practiced for eons, reinforcing the bonds that we share.", objectives = "" }
WordHunterWoW_QuestEN[58796] = { title = "The Forsworn Onslaught", description = "Loyalty's betrayal shall not go unnoticed.\n\nBut while the Paragons defend the city proper, it is up to us to defend Elysian Hold.\n\nI am very wounded... but I will hold strong. Pelagos and I will protect the survivors. You must aid in pushing back this assault!", objectives = "" }
WordHunterWoW_QuestEN[58797] = { title = "Forged by Trial", description = "{name}, my friend.\n\nI have thought of you as an ally for some time now. The thrill I felt when you decided to join us in Bastion... I knew you would be a boon unto our ranks.\n\nOur bond has been forged by the trials we face. Without you, I could have fallen to my newfound knowledge as Achillon did.\n\nI wish to cement our bond. I would be honored to soulbind with you.", objectives = "" }
WordHunterWoW_QuestEN[58798] = { title = "The Spires of Ascension", description = "Our task is not complete yet.\n\nWe may have pushed back the Forsworn here in Elysian Hold, but it was only a distraction to split our forces.\n\nThe Archon and the Paragons fight to retake the Spires themselves.\n\nWe cannot hesitate to aid them in this time of need!", objectives = "" }
WordHunterWoW_QuestEN[58799] = { title = "The Prime's Directive", description = "All centurion are made to serve the kyrian.\n\nThat they now work against ME, the Forgelite PRIME, is an insult to all centurions in Bastion. Look at them! Praetors! Goliaths! All... PURPLE!\n\nI hereby give you permission and expressly order you to extract their cores. I will repurpose them in a fitting manner. I will reclaim their anima to power the Locus.\n\nI can build more. Do not pity.", objectives = "" }
WordHunterWoW_QuestEN[58800] = { title = "The Mnemonic Locus", description = "<Mikanikos examines the scroll you retrieved for him.>\n\nRight, right.\n\nSoul mirrors and Locus are tied together. If we restore anima to mirrors, it should repair the Locus back to full functionality. Thankfully, the cores you brought should be sufficient.\n\nAll I need to do is enable conduits. Simple!\n\nWell? Go on. You know how to use these, yes?", objectives = "" }
WordHunterWoW_QuestEN[58801] = { title = "Enter the Void", description = "<As your approach the idol, the dark shards you carry appear to melt into your hand. You are immediately overcome with unspeakable anguish. It quickly gives way to feelings of joy, serenity, and an overwhelming desire to... kill.\n\nA hissing voice creeps into your mind.> \n\nMy faithful servant. I will grant you but a small taste of my unimaginable power, all I ask in return is that you complete one simple task. Kill any who would oppose me, spare no one. Do not fail me...", objectives = "" }
WordHunterWoW_QuestEN[58802] = { title = "The Incredible Egg", description = "<The aqir seem to have been in the process of empowering this egg with void magic.\n\nIt looks to be far from hatching, so it should be safe to study to find out what they were planning to do with it. \n\nSomeone in the Explorers' League might be interested in taking a look.>", objectives = "" }
WordHunterWoW_QuestEN[58803] = { title = "Match the Hatch", description = "Don't fret, I'm sure no ill will become of hatching this creature. After all, the aqir can't be born evil, can they?\n\nOf course, we have no idea how to take care of such an egg. I will need you to do some investigating.\n\nHead back to the aqir hives and see if you can find any other, similar eggs. If we can observe how they're being treated, we might be able to apply those learnings here.", objectives = "" }
WordHunterWoW_QuestEN[58804] = { title = "Void Incubation", description = "Well one thing is for certain with this egg, it requires great amounts of void energy in order to thrive. \n\nIt is fortunate for us that an Old God is attacking Azeroth at this very moment, yes?\n\nNo? Oh...\n\nIn any case, there should be an abundance of void energy wherever N'Zoth's minions strike. You should head out and find some.", objectives = "" }
WordHunterWoW_QuestEN[58805] = { title = "Continued Incubation", description = "The egg is doing well, but we're going to need more of those void crystals to keep it healthy.\n\nCould you go out and gather some?", objectives = "" }
WordHunterWoW_QuestEN[58806] = { title = "Warmth of the Sun", description = "The desert nights in Uldum can get awfully cold. I fear for our little egg's ability to withstand these temperatures.\n\nThese Amathet to the East seem to have mastered the harnessing of the sun's energy. If we could borrow some of their expertise, we could use it to keep the egg nice and cozy.\n\nKeep your eyes open for something we can use.", objectives = "" }
WordHunterWoW_QuestEN[58807] = { title = "Wrapping Up", description = "One oddity I have observed about this egg is that it lacks the protective webbing commonly found throughout the aqir hives. \n\nI believe this webbing has protective qualities, and could be beneficial to our egg if we can acquire some.\n\nWhile you're out fighting the insects, see if you can't bring back some of their webbing so we can make a proper cocoon for our growing egg.", objectives = "" }
WordHunterWoW_QuestEN[58808] = { title = "Encased in Amber", description = "You know who would probably know a lot about how to properly incubate this egg? The mantid!\n\nOf course, they're too busy trying to kill us to share their expertise, but there might be another way to benefit from their knowledge!\n\nPerhaps we could repurpose one of their incubation chambers. That could help speed up this process, I'm sure!\n\nIf you could find and mark one for me, I could airlift it out of there.", objectives = "" }
WordHunterWoW_QuestEN[58809] = { title = "A Shocking Technique", description = "I have heard tales that the mogu use lightning to speed up the growth of their cloud serpents. I wonder if the same principle could be used for our aqir friend?\n\nThere's only one way to find out! Go to the Vale of Eternal Blossoms and see if you can get the parts together so we can create our own lightning rods. \n\nIf they work the same as they do for the cloud serpents, it should speed up the hatching process significantly.", objectives = "" }
WordHunterWoW_QuestEN[58810] = { title = "Coming Out of His Shell", description = "It looks like our egg is ready to hatch! Isn't this exciting!\n\nCome, let us welcome our new little friend to this world.", objectives = "" }
WordHunterWoW_QuestEN[58811] = { title = "A Balanced Diet", description = "Now that our larva is hatched, we'll need to figure out what we can feed it to keep it healthy. \n\nIt would seem that the aqir are carnivores, but the only things I've seen them eat are... well... us.\n\nOf course, we can't feed our little friend people, so we'll have to find an alternative. Perhaps we could substitute animal meat?", objectives = "" }
WordHunterWoW_QuestEN[58812] = { title = "Meat Alternatives", description = "In the wild it is actually fairly common for insects to eat others of their species. I wonder if this rings true for the aqir as well.\n\nCould you bring back some meat from the aqir or mantid? We'll see if that's more palatable for our friend here.", objectives = "" }
WordHunterWoW_QuestEN[58813] = { title = "Fetid Filets", description = "You know, it occurred to me that since this creature has been imbued with void energy, it may prefer a more... corrupted food source.\n\nI speak, of course, of the Minions of N'Zoth.\n\nIt's a long shot, but it's worth a try.", objectives = "" }
WordHunterWoW_QuestEN[58814] = { title = "[UNUSED]", description = "Qadarin isn't here but I know he is close. \n\nThe Drust spoke of a leader. I suspect Qadarin is being held with them. If they are draining us of our anima, Qadarin would be a significant source.\n\nThank you for helping me this far, {name}. Now, let us finish clearing this blight from Ardenweald.", objectives = "" }
WordHunterWoW_QuestEN[58816] = { title = "Getting Backstage", description = "The next thing we need to prepare the vessel is a set of Night's Veil Flowers.\n\nWe use these flowers in our ceremonies, but since the drought we've just used them as props in our plays. There are certainly some backstage at the Star Lake Amphitheater.\n\nI bet Moonberry is there for the rehearsal of their next play. As a bonus, this will work out quite nicely for me to get revenge on her.\n\n<Willowblossom flashes a wicked grin.>", objectives = "" }
WordHunterWoW_QuestEN[58817] = { title = "Action Figures", description = "It occurs to me that our larva's current living situation is quite dull. We should try to find something to keep him entertained.\n\nAfter all, a happy larva is a healthy larva!\n\nI think the Amathet keep figures for worship of their gods. I'm sure they could also double as toys for our little friend here. See if you can find some!", objectives = "" }
WordHunterWoW_QuestEN[58818] = { title = "Bug Buddies", description = "Is it just me or does our little friend look lonely? It would make sense that aqir are social creatures, coming from a hive and all. It must be difficult for him not being around any of his kind.\n\nYou know, maybe you could find some friends for him. Nothing big and scary, of course, but perhaps some of the smaller scarabs could be safe enough to keep him company.\n\nWhat do you think?", objectives = "" }
WordHunterWoW_QuestEN[58820] = { title = "Bindings of Fleshcrafting", description = "These are the Bindings of Fleshcrafting! They empowered the Primus to shape the very flesh and bone of Maldraxxus.\n\nWe must return them to their rightful place, so their power can bolster us all.", objectives = "" }
WordHunterWoW_QuestEN[58821] = { title = "Glorious Pursuits", description = "Perhaps Draka has forgotten her loyalties, but I will fulfill my mission.\n\nMy enemy--the lich Mor'Bitan--hides within the House of Rituals. For some reason, his underlings skulk in this marsh.\n\nWe have not learned why they are here, but my devoted have spotted Mor'Bitan's second-in-command, Mephiles the Loyal. He will have our answers.\n\nCollect him for me. Once you capture him, slay his kin. Weaken his resolve.\n\nI will prime my base for his interrogation.", objectives = "" }
WordHunterWoW_QuestEN[58825] = { title = "Super Jelly", description = "My friends in the Golden Lotus have been telling me some interesting things about the new mantid swarm. Apparently they have developed a concentrated royal jelly that accelerates the growth of newly hatched mantid. \n\nIf this jelly works on mantid, logic would suggest it would work on aqir as well!\n\nSee if you can find a sufficient sample of this jelly to help with our larva's growth.", objectives = "" }
WordHunterWoW_QuestEN[58826] = { title = "A Bloody Treat", description = "I have heard that a clan of the mogu called the Dokani have mastered the harnessing of life force into a substance they call \"anima.\"\n\nIf this stuff is indeed life condensed into a liquid form, then it could have spectacular properties when applied to our aqir larva.\n\nGo see if you can bring back some of this anima in a form that we can use. We'll see if our little friend here likes it!", objectives = "" }
WordHunterWoW_QuestEN[58829] = { title = "They Grow So Fast", description = "Look! Our little larva friend has entered the pupa stage! \n\nWait... it looks like he's ready to emerge. \n\nGo on, give him a hand!", objectives = "" }
WordHunterWoW_QuestEN[58830] = { title = "Aqir Instincts", description = "In observing the aqir battling the Wastewanders, I have seen the newly hatched immediately join the aqiri assault. It would seem the need for combat is born into these creatures.\n\nWe should exercise this in our new hatchling, under your supervision of course. Take him out with you and show him how to fight our enemies. \n\nHe may not be able to fight for long, so don't call him until you're ready for training.\n\nWith luck, he will come to see us as part of his hive.", objectives = "" }
WordHunterWoW_QuestEN[58831] = { title = "Honing Instincts", description = "It looks like our little friend is anxious and ready to practice more combat.\n\nWould you care to show him the ropes?", objectives = "" }
WordHunterWoW_QuestEN[58832] = { title = "Trinkle Trinkle Little Twerp", description = "<On the note are the scribblings for a plan to steal silkstrider larvae and cook them.\n\nIt is signed by someone named Trinkle.>", objectives = "" }
WordHunterWoW_QuestEN[58833] = { title = "Calling in All Favors", description = "{name}, the time has come.\n\nWe cannot allow Kel'Thuzad to wield the Ritualists' sorcery as a weapon. He must be destroyed.\n\nRally our forces. We march on the House of Rituals!", objectives = "" }
WordHunterWoW_QuestEN[58842] = { title = "The Curator", description = "I tasked the Curator with reacquiring the Medallion of Avarice.\n\nHowever, since her return from the Maw, her mind has become... a bit chaotic. Do be kind, will you?  \n\nI ask that you lend her assistance in her search. She is at the Crypt of the Forgotten.", objectives = "" }
WordHunterWoW_QuestEN[58843] = { title = "The Vault of the Archon", description = "Behind me is the entrance to the Vault of the Archon. As you can see, it is warded against all unauthorized intrusion.\n\nTo make yourself an authorized entrant, place the offerings you collected before the guardians. You may then browse the contents of the vault at your leisure.\n\nDo consider that such access is coveted among the Forsworn and is the sole focus of their efforts here. I advise preparing for combat.", objectives = "" }
WordHunterWoW_QuestEN[58844] = { title = "Before the Dawn", description = "We shall need all we can muster if this day is to be ours.\n\nGather them all. The Watchers, Bearers, Centurions, and Collectors. Tell them that their Archon calls for them.\n\nOur Paragons will clear a staging ground at the Court of Elation for the final assault.", objectives = "" }
WordHunterWoW_QuestEN[58846] = { title = "The Greater Good", description = "The Forsworn are our former brothers and sisters in arms...our former kin. But we must see this through.\n\nWe will hit them from all sides. Fight well, but do not forget that Lysonia is our ultimate objective. If she does not fall, then she will recruit more to their cause in time.\n\nFollow the path, {name}.", objectives = "" }
WordHunterWoW_QuestEN[58847] = { title = "Kyrestia's Grace", description = "I remember this particular soul...Uther. Devos brought him before us some time ago. She pleaded her case about his soul having a connection to the Maw.\n\nShe then took him under wing, ascending him before he was ready. He became her other hand alongside Lysonia, as it were.\n\nHe may proclaim a change of heart, but we shall see. Place him under guard. He may stay by the Archon's grace, but I will not take any chances with one so...broken.", objectives = "" }
WordHunterWoW_QuestEN[58854] = { title = "Convene the Paragons", description = "We have defeated the Forsworn at every turn. Saved those not too far gone. Routed them from our blessed Archon's temples. Now only one remains.\n\nThe Temple of Loyalty.\n\nLysonia has grown desperate in defeat. Abandoned all we strive to uphold by embracing the Maw. She has rallied her most fervent loyalists to the temple, knowing we will come for her.\n\nWe shall need the Paragons to finish this. Summon them.", objectives = "" }
WordHunterWoW_QuestEN[58856] = { title = "Who Are You Fooling?", description = "We cannot conduct the ritual without a very special guest. He's a silkstrider larva named Grubby and he's my best friend.\n\nUnfortunately, the nasty spriggans took him! What's worse is they cast illusions on what they steal, so no one can take it back!\n\nThe spriggans often carry trickster powder. If you can take some of that stuff, I can reverse their illusions and rescue Grubby.", objectives = "" }
WordHunterWoW_QuestEN[58857] = { title = "Seeds Away!", description = "I think we have a problem. Plucking the seed from this root must have shaken some burrowed gorm awake. This isn't good!\n\nGrab on to me. I will fly us out of here, but we must stop the gorm before they overrun the local Vorkai defenses!", objectives = "" }
WordHunterWoW_QuestEN[58858] = { title = "More Fetid Filets", description = "Our little guy is getting hungry again. \n\nCould you pick him up a quick bite to eat?", objectives = "" }
WordHunterWoW_QuestEN[58859] = { title = "Someone His Own Size", description = "While fighting alongside you no doubt provides excellent training for our hatchling, sometimes it is better to have him fight on his own against enemies his own size.\n\nI know of one such opponent nearby, observing the Amathet near the Obelisk of the Stars. You should seek it out.", objectives = "" }
WordHunterWoW_QuestEN[58860] = { title = "Big Bad Beetle", description = "It could do our hatchling some good to face off against another aqir, to learn what his kind are capable of.\n\nI have found an opponent who could provide a challenging fight.", objectives = "" }
WordHunterWoW_QuestEN[58861] = { title = "The Mantids' Mettle", description = "Observing the combat techniques of the mantid may prove helpful for our hatchling's training, offering a different way to use the natural weapons of an insect.\n\nI have found a mantid opponent that our hatchling could face in the Vale of Eternal Blossoms. Take him there and see how he does.", objectives = "" }
WordHunterWoW_QuestEN[58862] = { title = "The Littlest Defender", description = "The Baruk mogu are known for animating ancient statues to serve as defenders of their territory. They are a resilient foe, and much can be learned from battling an enemy with such rigid defenses.\n\nFortunately, it seems like one of their Stoneshapers mistakenly animated a small idol. It has been discarded as useless to the mogu who made it, but it could prove a valuable training opportunity for our hatchling.\n\nFind this miniature defender in the Vale of Eternal Blossoms.", objectives = "" }
WordHunterWoW_QuestEN[58863] = { title = "A Custom Order", description = "I think it's safe to say that our little friend is no long a hatchling, but a fully grown aqir! He's grown so much, in fact, he could even carry you into battle.\n\nWait, that's a marvelous idea!\n\nYou should speak with Blacksmith Abasi about getting a saddle made.", objectives = "" }
WordHunterWoW_QuestEN[58865] = { title = "Otherworldly Armaments", description = "To craft a saddle for your beast, I'll need some special materials. Mainly, it will require metals much lighter than what we have available.\n\nI have noticed that the Black Empire cultists carry with them weapons made from otherworldly materials, which are impossibly light and strong. \n\nIf you could retrieve some of their weapons for me, I may be able to melt down this metal and shape it into a saddle for the aqir.", objectives = "" }
WordHunterWoW_QuestEN[58866] = { title = "My Own Drone", description = "The saddle is complete. I can't say I enjoyed working with that corrupted metal, but in the end I can easily say this is the finest saddle I have ever crafted.\n\nI know it looks... aggressive, but I assure you that your aqir will find it quite comfortable.\n\nI hope it serves you well.", objectives = "" }
WordHunterWoW_QuestEN[58869] = { title = "Battle for Hibernal Hollow", description = "This is where we make our stand. The Drust and their minions have us nearly overrun.\n\nBut we will not let them destroy Hibernal Hollow. Nor will they take our anima or our wildseeds.\n\nFight with us. Let us drive them out.", objectives = "" }
WordHunterWoW_QuestEN[58871] = { title = "Broken Harts", description = "The curse on Qadarin is a powerful one.\n\nBut I will break it.\n\n<Thiernax snorts.>\n\nDeath did not part us. I will not be torn from him now.\n\n<Thiernax studies both you and Shandris with a serious look in his eyes.>\n\nLend me your aid, and in turn I will help you with your world's Night Warrior. I do not promise I can save her... but I will share all that I know.\n\nReturn to the Heart of the Forest and tell Lord Herne what has happened. We will meet there.", objectives = "" }
WordHunterWoW_QuestEN[58876] = { title = "Lost Flight", description = "<A small dragon emerges from one of the side chambers found within N'Zoth's great carapace. It appears confused.\n\nYou surmise that such chambers must have been used to corrupt the dragons, exposing them directly to N'Zoth's dark whispers. At a young age, they would be driven mad, moreso than any other members of the twilight dragonflight that you had met before.\n\nThere would be no turning back from such madness.\n\nBut maybe it's not too late for this one...>", objectives = "" }
WordHunterWoW_QuestEN[58877] = { title = "Death's Power Grows", description = "Listen closely, {name}. A time of great destruction lies on the horizon that will challenge our very existence. Now more than ever, we must rise to the defense of Azeroth.\n\nIt is for this reason I have expanded the ranks of my champions to include your people. Your sacrifice sets you apart from all others. Hold your head high. Forevermore, you will be a death knight of the Ebon Blade.\n\nNow swear your fealty.", objectives = "" }
WordHunterWoW_QuestEN[58879] = { title = "Alpaca It Up", description = "<Sniffs curiously in the general direction of your backpack, eyeing it intently.>", objectives = "" }
WordHunterWoW_QuestEN[58887] = { title = "Alpaca It In", description = "<The friendly alpaca seems grateful to you for continuing to bring its favorite snack.>", objectives = "" }
WordHunterWoW_QuestEN[58900] = { title = "A Sure Bet", description = "You've made a name for yourself and earned the respect of everyone here, including Au'narim.\n\nYou are ready, {name}!\n\nAnzio is expecting us at the entrance to the Theater of Pain. You're going to be a champion!", objectives = "" }
WordHunterWoW_QuestEN[58902] = { title = "Defender of Azeroth", description = "An excellent choice.\n\nTroubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor.\n\nBut also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done.\n\nSpeak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.", objectives = "" }
WordHunterWoW_QuestEN[58903] = { title = "Defender of Azeroth", description = "An excellent choice.\n\nTroubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor.\n\nBut also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done.\n\nSpeak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.", objectives = "" }
WordHunterWoW_QuestEN[58904] = { title = "Shards of Corruption", description = "<You feel the pull of something dark and inhuman on your mind, it's writhing tendrils digging in, tugging at your sanity. You feel compelled to collect more shards... all of them.>", objectives = "" }
WordHunterWoW_QuestEN[58905] = { title = "Picking Up Pelagos", description = "Pelagos should have the seed by now! Can't start the ritual without the seed. He's likely still at Claw's Edge.\n\nWe'll see you there!", objectives = "" }
WordHunterWoW_QuestEN[58908] = { title = "Finding Your Way", description = "Stormwind has a lot to offer adventurers like us, but it's far too big to explore on foot. The captain has arranged for you to receive a mount to help you get around.\n\nShe said to speak with Curly at the stables in Old Town... but I can't seem to remember the way there.\n\nHave no worries, {name}! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go.\n\nLet's ask a nearby guard for directions to the stable master in Old Town!", objectives = "" }
WordHunterWoW_QuestEN[58910] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Mithlos Falconbriar to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[58911] = { title = "Home Is Where the Hearth Is", description = "I don't know about you, but all this running around has got me thirsty!\n\nWhy don't we head over to the Pig and Whistle Tavern and rest our legs over some cool pints of moonberry juice?\n\nWhile we're there, speak with Meagan the innkeeper to make the Pig and Whistle Tavern your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn.\n\nNot only is it faster than a gryphon, but you'll save a few copper in the process!", objectives = "" }
WordHunterWoW_QuestEN[58912] = { title = "An Urgent Meeting", description = "I've been looking for you all over Stormwind, {name}.\n\nThe captain has delivered her report to the king. It appears that Stormwind requires your service yet again.\n\nThe leaders of the Alliance have gathered together for a meeting at Stormwind Keep, and your presence has been requested by King Wrynn himself. I was instructed to find you and deliver the message without delay.\n\nIt has been an honor serving with you, {name}. May the Light bless you on your journey.", objectives = "" }
WordHunterWoW_QuestEN[58914] = { title = "A Warrior's End", description = "Hey, {name}! You're a {class}, right? Maybe you can deal with this... situation.\n\nI was scouting the area with Lindie's device and saw a ghost who was offering power to any \"true\" warriors.\n\nI know you're still new at this, but why don't you try going over there? \n\nWe could use every advantage against these ogres.", objectives = "" }
WordHunterWoW_QuestEN[58915] = { title = "Hjalmar's Final Execution", description = "You now wield my most powerful skill, young warrior. \n\nNow use it to finish me! These ogres trapped my spirit here long ago for daring to defy them.\n\nOnly through a glorious death will I finally be allowed to rest. \n\nIt is the only way I will see my brothers and sisters in the afterlife.", objectives = "" }
WordHunterWoW_QuestEN[58916] = { title = "Dread Priming", description = "Sire Denathrius has requested I help you prepare for the hunt. Every hunter must help prepare a soul here in the Grove of Terror.\n\nI have a stubborn soul here who's been quite uncooperative, Houndmaster Loksey. His time has come to be hunted.\n\n<The Fearstalker hands you a set of Hopebreaker Soul Chains.>\n\nDemoralize him. We can't let him leave here with any hope. The hunt is meant to break the souls so they become less... resistant to the processes of Revendreth.", objectives = "" }
WordHunterWoW_QuestEN[58917] = { title = "A Rogue's End", description = "A rogue from the lost expedition, Coulston Nereus, tried scouting the island for any threats after they made landfall.\n\nThe last time Henry saw him, he was headed for a cave not far from here.\n\nCan you make contact with Coulston? He may be able to help with our rescue mission.\n\nOh, and be careful when heading north. Alaria spotted a vicious bear roaming the area.", objectives = "" }
WordHunterWoW_QuestEN[58923] = { title = "A Paladin's Service", description = "I found something strange while using Lindie's Scout-o-Matic that you should probably know about.\n\nThe ghost of a paladin appeared on the hill nearby. She looked straight at the Scout-o-Matic and asked for you.\n\nI don't understand a whole lot about paladins and the Light, but I think you may not want to ignore her.", objectives = "" }
WordHunterWoW_QuestEN[58931] = { title = "Inquisitor Stelia's Sinstone", description = "You never truly escape your past, Maw Walker.\n\nEvery venthyr once entered Revendreth as a soul, burdened by the immoralities of their mortal lives.\n\nLike all souls, they carved their true names and most shameful transgressions into sinstones.\n\nKnowledge that intimate can be a potent weapon, if wielded properly.\n\nLocate the sinstones of the inquisitors aiding the Accuser so that you may kill them. Start with Stelia.\n\nAfter they're dead, bring me the Accuser's sinstone. I will deal with her myself.", objectives = "" }
WordHunterWoW_QuestEN[58932] = { title = "Temel, the Sin Herald", description = "<Before flying away, Echelon shouted an additional command.>\n\nExpropriate Temel as well. He will know how to exploit the sinstone properly.", objectives = "" }
WordHunterWoW_QuestEN[58933] = { title = "The Deadliest of Poisons", description = "You've got the poison. Now it's time to take out that ogre. Gutgruk the Tough.\n\nHe usually patrols around their citadel. Probably looking for your expedition as we speak!\n\nPoison your blades, then take that monster down.", objectives = "" }
WordHunterWoW_QuestEN[58936] = { title = "Beast Control", description = "The Grove of Terror's dredbats have become aggressive due to the lack of anima caused by the drought.   \n\nThis is a formal request to cull their numbers. We must re-establish dominance over our creations.\n\n-Flockmaster Sergio", objectives = "" }
WordHunterWoW_QuestEN[58937] = { title = "Evil Grubbies", description = "Oh no! This place is littered with mites!\n\nThey are cute like Grubby, but they grow into horrible gorm! If we cleared some of them out, then the Sylvari will have less to fight against later.\n\nThey can burrow away, so it's best to burn them up with Pelagos' red seeds. They'll be good for something after all.", objectives = "" }
WordHunterWoW_QuestEN[58938] = { title = "Gorm Ruin Everything", description = "These red seeds will still prove useful. They come from a very dangerous plant and are quite unstable. If we are going to recover the blue seed we really need, then these might help.\n\nLet's clear out some of these gorm and search for the real seed.", objectives = "" }
WordHunterWoW_QuestEN[58939] = { title = "The Blue Seed", description = "I remember seeing a blue seed with red leaves nearby, but it was in a cave behind a wall of brambles. I didn't think of it at the time, but maybe you could use the red seeds to get us in?\n\nI wish I didn't mix up the instructions or we wouldn't be in this mess. But maybe it's all going to work out anyway. Let's go!", objectives = "" }
WordHunterWoW_QuestEN[58941] = { title = "Alpha Bat", description = "Dredbats are quite useful to us. We make them just like stoneborn, but they lack their same... intelligence. With very little direction, they strike fear into stubborn souls' hearts.\n\nWith the anima drought, our dominion over them has waned. One, Duskterror, has wreaked the most havoc.\n\nThis presents us with an opportunity. Take this soul and draw her in. When she's weak, we can capture her for our own purposes.", objectives = "" }
WordHunterWoW_QuestEN[58946] = { title = "The Divine's Shield", description = "This island has been cursed by necrotic magic. The Light can only just reach this place.\n\nCall upon its Divine Shield to step through the barrier before us unharmed and destroy this vile altar.\n\nShow the darkness on this island that you are protected by the Light's embrace.", objectives = "" }
WordHunterWoW_QuestEN[58947] = { title = "Test Your Mettle", description = "Many of the greatest Maldraxxi legends earned their fame fighting in the Theater of Pain. \n\nIf you want to follow in their footsteps, you need to prove you have what it takes to survive in there.\n\nDefeat Valuator Malus and Tester Sahaari in combat. Let's see what you can do!", objectives = "" }
WordHunterWoW_QuestEN[58948] = { title = "Food on the Table", description = "I'm making a stew for dinner tonight, but it seems we're missing rabbit meat.\n\nWould you be able to go out back and collect some for me?\n\nOh and do be careful, I heard howling earlier. The wolves aren't normally out during the day.", objectives = "" }
WordHunterWoW_QuestEN[58949] = { title = "Millie's Garden", description = "Alma came by earlier and gave Millie some flower seeds to plant out in the garden.\n\nI love that our daughter is taking an interest in gardening, but I don't have time to wash her dress when she gets it covered in mud again!\n\nWould you help her with the digging so that she doesn't get too dirty?", objectives = "" }
WordHunterWoW_QuestEN[58950] = { title = "Lumber for Lakeshire", description = "Magistrate Solomon requested a bundle of wood for his hearth. However, he's been too busy to come by and retrieve it.\n\nIf you wouldn't mind running it down to him at the town hall, I'm sure he'd appreciate it.", objectives = "" }
WordHunterWoW_QuestEN[58951] = { title = "Lakeshire's Last Stand", description = "There's no time to evacuate... not if the Scourge are here!\n\nBoard the windows! Get everybody inside! Our only hope is to hide.", objectives = "" }
WordHunterWoW_QuestEN[58953] = { title = "A Priest's End", description = "You're a trained priest, right {name}? This might be up your alley.\n\nWe've spotted the bodies of other recruits from our expedition.\n\nI'm guessing they washed up on a different part of the island. They didn't make it very far.\n\nWhen you have a moment, could you say a few prayers over them? Just to help put their spirits at ease.\n\nWe'll give them a proper burial once we deal with the ogres.", objectives = "" }
WordHunterWoW_QuestEN[58960] = { title = "Resurrecting the Recruits", description = "The souls of these recruits aren't strong enough tae resist the dark magic bein' practiced on this island.\n\nUse Resurrect on the remains of these recruits. Beseech the Light tae give 'em another chance while their souls still linger.\n\nI've been stranded on this island for years, watchin' these ogres get away with all of this.\n\nIt's time tae make a stand.", objectives = "" }
WordHunterWoW_QuestEN[58962] = { title = "A Warlock's Bargain", description = "While you were mowing down hordes of undead, I was scouting more of the area with Lindie's device.\n\nI saw what looked like a portal out near the bridge, along with the corpse of a warlock we thought was lost in the shipwreck.\n\nThink you can go investigate the area and try to close that portal? We have enough problems on this island as it is.", objectives = "" }
WordHunterWoW_QuestEN[58976] = { title = "Chasing a Memory", description = "The attack on the Temple of Purity is unprecedented in Bastion. At least, to my knowledge.\n\nWe need to know more. The fragment that the Paragon captured may contain the answers we seek.\n\nThere is a place nearby called the Mnemonic Locus. There, aspirants and ascended alike can call forth their memories and store them away. If we can look through this fragment's memories, perhaps we can learn more about the so-called Forsworn and, with luck, uncover their plan.\n\nI will meet you there. Go in service.", objectives = "" }
WordHunterWoW_QuestEN[58977] = { title = "What's In a Memory?", description = "It may be possible to extract memories from fragment, but I worry they will not be useful. This is not whole kyrian, but a tiny piece! A weird, broken piece. It cannot even speak!\n\nWe will apply extractor and see what comes out. Extractor might explode. It might not. For this? Worth the risk, I think.\n\nDo not know what will emerge. Could be memories. Could be nothing. Could be something else. May try to fight you! Stay on your guard, yes? Collect all that look Forsworn.\n\nSpeak when ready.", objectives = "" }
WordHunterWoW_QuestEN[58978] = { title = "Lysonia's Truth", description = "If I had not seen it with my own eyes, I do not know that I would believe such a thing is possible.\n\nYou carry a significant piece of Lysonia within you, now. Go to the Soul Mirrors and open yourself to them. With luck, they will draw from her essence to draw forth a memory of the Forsworn.\n\nIf this works, we may know what they are planning within minutes!", objectives = "" }
WordHunterWoW_QuestEN[58979] = { title = "I MADE You!", description = "I have had it with this insolence!\n\nI have an idea to reset this Mnemis's personality, but you will need to keep it busy.\n\nIt will try to fight you, through whatever means it posseses. I suggest you try not to perish. Kleia can hold her own, so hide behind her if so inclined.\n\nHop to it!", objectives = "" }
WordHunterWoW_QuestEN[58980] = { title = "Mnemis, At Your Service", description = "Greetings, I am Locus-Keeper Mnemis and I would be delighted to assist you.\n\nI recall that you are trying to access a particular memory. Due to the contents, that memory can only be viewed within the Vault of the Archon.\n\nIn order to gain access to the Vault, you must collect offerings for the two guardians who watch over it. I have hidden these offerings from the Forsworn, as they are not authorized to enter.\n\nThe Forgelite Prime is the only one among you who can grant authorization. How convenient!", objectives = "" }
WordHunterWoW_QuestEN[58983] = { title = "Battle for Azeroth: Tides of War", description = "King Wrynn has called us together for an urgent war council.\n\nIt seems that there was some trouble with the Horde while we were away. The king was impressed with the valor and bravery that you demonstrated during our mission to Exile's Reach.\n\nNow that you've arrived, the meeting will begin without delay.", objectives = "" }
WordHunterWoW_QuestEN[58989] = { title = "Runeforging 101", description = "As knights of the Ebon Blade, we must always be prepared for a variety of martial situations. To this end, the dark art of runeforging is yours to command. With it, runes of great power can be engraved upon your weapons.\n\nAbove us in the Heart of Acherus are runeforges. Visit one and use your power to imbue a weapon with a rune of power.", objectives = "" }
WordHunterWoW_QuestEN[58992] = { title = "Pie Not?", description = "I want to cook something warm, savory, and gooey!\n\nThat's right! I want to make a lovely bone marrow pie! When it's done, you'll be as full as a tick. I guarantee it! \n\nNow, just any old marrow won't do. I need the very best and rarest marrow.\n\nAnd that's where you come in! I need you to help Mama out and dig that marrow up. Yes... dig. \n\nOh and be ready to knock some heads. Maldraxxus doesn't take kindly to being carved up.", objectives = "" }
WordHunterWoW_QuestEN[58995] = { title = "I Dreamed A Dream", description = "This is quite a ceremony, everyone is here. This ritual is essential to the recreation of the Crest of Ascension and the preservation of Bastion. \n\nWe owe the Winter Queen and Willowblossom a great debt. Someday, I hope we can repay them.", objectives = "" }
WordHunterWoW_QuestEN[58996] = { title = "Abel's Fate", description = "Maw Walker, I have another task for you.\n\nSome time ago, I sent Soulwatcher Abel and a few others to slay some troublesome bonemaulers.\n\nThey have yet to return. Go find them, will you?", objectives = "" }
WordHunterWoW_QuestEN[58997] = { title = "A Bittersweet Prize", description = "I... I don't know what to say.\n\nAll that is left is to return Willo... the vessel... to Polemarch Adrestes in Bastion. This sacrifice must not be in vain.", objectives = "" }
WordHunterWoW_QuestEN[59000] = { title = "Elements of Corruption", description = "Corruption behaves in mysterious ways. It spreads beyond Azeroth herself, touching our most intimate thoughts and sometimes corrupting various relics, as you've seen firsthand.\n\nThough I cannot speak to the effects of these matters directly, I am sure MOTHER has information surrounding these so-called items of corruption.", objectives = "" }
WordHunterWoW_QuestEN[59002] = { title = "A Shaman's Duty", description = "Greetings, young one. Your companions cannot see me. Only you, for you have been trained in the ways of a shaman.\n\nThe shadow energies of this island have ensnared my pack. I need your aid to free them.\n\nGather veil blossoms from the surrounding area. Burn them on the campfire and breath deep of their smoke.\n\nThen you will be able to see my packmates and release them from their bonds.", objectives = "" }
WordHunterWoW_QuestEN[59004] = { title = "Splash Damage", description = "The Jailer's troops use anima charged runes to empower their armor. Without those runes, the troops will be significantly weaker! \n\nI developed this special formula to remove tough laundry stains, but it should be capable of removing magical runes as well!\n\nSplash my Putrification Potion on Rune-hardened troops, the bigger the better! Then collect the runes that fall off, so I can extract their anima.", objectives = "" }
WordHunterWoW_QuestEN[59008] = { title = "Spriggan Snares", description = "I'm so glad you and Qadarin were passing by! These spriggans are crazy!\n\nGet me out of here!\n\nI was gathering some herbs from the garden when they nabbed me. I'm sure they've captured other souls, too!", objectives = "" }
WordHunterWoW_QuestEN[59009] = { title = "Her Rightful Place", description = "Mor'Bitan has met his end... and a painful one at that.\n\nYour fortitude contributed in no small part to my success. You have earned my allegiance... for the time being. \n\nThere is much left to do, should you truly desire ownership of this realm.\n\nLet us regroup at the Seat.", objectives = "" }
WordHunterWoW_QuestEN[59011] = { title = "In Death We Are Truly Tested", description = "Vyraz is the one who trapped me within the Maw. He has long been in league with the House of Rituals and the House of Constructs.\n\nNo doubt he intended to trap you within that hellish place as well.\n\nIt is time he be brought to justice for his treason. Stand with me, and we will face him as one.", objectives = "" }
WordHunterWoW_QuestEN[59014] = { title = "King of the Hill", description = "Loksey is ready. It is finally time to begin the hunt.\n\nTake him to Wanecrypt. The Fearstalker and the other hunters will be there already.\n\nHurry now. She does not like to be kept waiting.", objectives = "" }
WordHunterWoW_QuestEN[59016] = { title = "Call to Arms: Uldum", description = "Our objectives in Uldum are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", objectives = "" }
WordHunterWoW_QuestEN[59017] = { title = "Call to Arms: Vale of Eternal Blossoms", description = "Our objectives in Vale of Eternal Blossoms are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", objectives = "" }
WordHunterWoW_QuestEN[59018] = { title = "Call to Arms: Vale of Eternal Blossoms", description = "Our mission in Vale of Eternal Blossoms is being compromised by the Horde incursion. \n\nGet into Vale and take out as many as you can.", objectives = "" }
WordHunterWoW_QuestEN[59019] = { title = "Call to Arms: Uldum", description = "Our mission in Uldum is being compromised by the Horde incursion. \n\nGet into Uldum and take out as many as you can.", objectives = "" }
WordHunterWoW_QuestEN[59020] = { title = "The Third Fall of Kel'Thuzad", description = "The time has come to purge Maldraxxus of treachery.\n\nOur armies are rallied. Our allies stand ready. The machine of war is in motion.\n\nWe must win this battle, or all of the Shadowlands will be lost.", objectives = "" }
WordHunterWoW_QuestEN[59021] = { title = "Herald Their Demise", description = "Since the dawn of Revendreth, Temel has been charged with proclaiming the sins of souls for all to hear.\n\nEvery soul here, including venthyr, has been forced to endure his wrathful pronouncements on at least one occasion.\n\nHe will know how to wield Inquisitor Stelia's sinstone to break through her defenses.\n\nSimply command him to do so after you locate the inquisitor, and eliminate her.", objectives = "" }
WordHunterWoW_QuestEN[59023] = { title = "Ending the Inquisitor", description = "Inquisitor Vilhelm hides smugly in the back of the courtyard, flanked by several gargons and loyal venthyr.\n\nWe must kill him to break the ward on the Accuser's sinstone, so that Lord Chamberlain can use it in his battle.\n\nTemel will once again help you penetrate the inquisitor's defenses. Do not tarry.", objectives = "" }
WordHunterWoW_QuestEN[59025] = { title = "Straight to the Heart", description = "The success of Mor'Bitan's treachery has made him complacent.\n\nLet him enjoy the feeling, for it ends here. We will lure him out with this ritual... and we will avenge my margrave.\n\nStand with me now, {name}. Together, we will make an example of this traitor.", objectives = "" }
WordHunterWoW_QuestEN[59042] = { title = "A Good Heart", description = "Despite the beliefs of most people, Emeni has a kind heart.  Err...at least she will have one, once you give it to her!\n\nI can think of no one better than you, Maw Walker, to give Emeni a new heart. Perhaps this will warm her blood towards you. You might become friends or even soulbinds!\n\nPlease select and place a heart in Emeni's construct.", objectives = "" }
WordHunterWoW_QuestEN[59043] = { title = "Baker's Dozen", description = "Under this very tent, I've prepared delicacies that would make demigods cry tears of joy. I'm always in need of more baking supplies!\n\nThe brokers usually sell me eggs from parts near and far, but maybe this time you could help me out instead.\n\nYou familiar with gorm? Big insect-like creatures native to Ardenweald. Well, if you find me some eggs of theirs, I'll bake you up something nice in return! \n\nMama will even send Starchy to help you out.", objectives = "" }
WordHunterWoW_QuestEN[59063] = { title = "Curses!", description = "Oh, dear me, this is terrible! Just terrible!\n\nI know precisely which awful curse afflicts that poor soul! But these damnable spriggans keep stealing my scrolls, scattering them all over and ripping them apart! \n\nNow the falls are overrun with all manner of dangerous magic!\n\nThe spriggans have the pieces of the scroll you need. Gather them along with a binding from one of the major hexes, and you can put it all back together.", objectives = "" }
WordHunterWoW_QuestEN[59068] = { title = "A Secret Never Spoken", description = "The first reagent listed in the scroll is a secret never spoken.\n\nWell, that's easy. I know who has tons of secrets! Watcher Vesperbloom, our resident snoop. She keeps the Wild Hunt informed of any nefarious behavior that takes place in the forest.\n\nI know she'd be willing to give us a secret to save Qadarin's soul from dissolving in excruciating pain.\n\nI'll have Thiernax meet you wherever she's hidden them. It'll keep his mind off what's happening to his husband.", objectives = "" }
WordHunterWoW_QuestEN[59069] = { title = "A Token of Lost Love", description = "My sister, Alexstrasza, lost her prime consort, Korialstrasz, towards the end of our war with Deathwing.\n\nShe has loved many in her long life, but none as deeply as he. I know in my heart she loves him still.\n\nFind Alexstrasza in the Vermillion Redoubt and ask for a token of her lost love. It will surely prove a powerful reagent for the counter-curse.", objectives = "" }
WordHunterWoW_QuestEN[59070] = { title = "A Sacrifice of Anima", description = "The last thing we need for this counter-curse is some attuned anima.\n\nOf course, we don't have much to spare. That means this is more of a sacrifice than it normally would be.\n\nBut you know what? The spriggans made this mess, so they should help clean it up. Some really nasty ones have been causing mischief in Tirna Scithe. They should have the anima we need.\n\nThiernax looks like he could use some nice, vengeful, therapeutic spriggan stomping. I'll have him meet you there.", objectives = "" }
WordHunterWoW_QuestEN[59071] = { title = "Mending a Broken Hart", description = "We have all the reagents for the counter-curse!\n\nHurry up and cast it before Qadarin's soul is lost, and Thiernax refuses to help you, and Tyrande is doomed to die horribly in the Maw, and everyone is sad!\n\nBut no pressure.", objectives = "" }
WordHunterWoW_QuestEN[59076] = { title = "The Minions of Mayhem", description = "To all downtrodden and unappreciated hard workers of the Shadowlands: the time has come to rise up. Rise up and stick it to the fangs and the wings and the bonemen! Stick it to the brokers and the bossmons! I says we go into business for ourselves!\n\nCome to our secret meeting at the Ledge of Destiny.\n\nTo all not-downtrodden warlords, Maw Walkers, and morally flexible powerful denizens: We are currently hiring muscle. If interested, please attend. \n\nDon't tell the fuzz.", objectives = "" }
WordHunterWoW_QuestEN[59077] = { title = "The Plan", description = "So now that you solved all them problems with the Shadowlands its time for us minions to get a go of it. The gates are open, and now it ain't a big secret how the other realms do their thing.\n\nSee, I found these downtrodden minions workin' hard in their own realms and think we all got a bumb deal. I for one am tired of being the labor of the fangs. \n\nI have an enterprisin' plan for us to go into business for ourselves. Thing is, we need some muscle. Want in?", objectives = "" }
WordHunterWoW_QuestEN[59078] = { title = "The Hook", description = "Your part of the plan is as goes:\n\nWalk into bank, and point the lads at their targets. If things get mawed up then be ready to fight our way free.\n\nHelp us out and you'll get a cut.", objectives = "" }
WordHunterWoW_QuestEN[59079] = { title = "Portal to Paradise", description = "Right.\n\nNow, let's see if I can get this shiny hoistin'. It ain't like we stole someone who could tell us how to use it. \n\nBest stand back, just in case.", objectives = "" }
WordHunterWoW_QuestEN[59080] = { title = "Demons!", description = "", objectives = "" }
WordHunterWoW_QuestEN[59081] = { title = "Scum Scrape", description = "", objectives = "" }
WordHunterWoW_QuestEN[59082] = { title = "Next Realm!", description = "Keep them felfeeders off me long enough to work this amulet.", objectives = "" }
WordHunterWoW_QuestEN[59083] = { title = "Sticky Getaway", description = "", objectives = "" }
WordHunterWoW_QuestEN[59084] = { title = "Bybeen Dreadweaver", description = "", objectives = "" }
WordHunterWoW_QuestEN[59085] = { title = "Third Time is a Charm", description = "", objectives = "" }
WordHunterWoW_QuestEN[59086] = { title = "Manor of Minions", description = "", objectives = "" }
WordHunterWoW_QuestEN[59087] = { title = "That Darn Fox!", description = "You! You there!\n\nI, Clarion Song, need your assistance. Yes, yes, give yourself a moment to bask in my glory.\n\n<Clarion Song gives you a moment.>\n\nDone? Good. I need you to catch a troublesome vulpin kit. He is positively barbaric! Running amok, causing havoc, ruining my beauty rest! He's using a concealing charm to make himself invisible, but I know it's him!\n\nMake yourself useful and catch that kit!", objectives = "" }
WordHunterWoW_QuestEN[59120] = { title = "Renny the Vulpin", description = "<The small vulpin kit runs up to you with a cheerful bounce and an air of mischief.\n\nYou, it seems, are interesting. Interesting enough that this child of Lord Renard of the Court of Winter has decided to tag along with you.\n\nWhat could possibly go wrong?>", objectives = "" }
WordHunterWoW_QuestEN[59126] = { title = "Supply Chain", description = "My friend! I could sure use your expertise right now.\n\nOne of our wagon convoys was attacked nearby! It was transporting critical supplies... and new goods for me to sell! \n\nIt's important--no--vital, that we recover as much of that equipment as possible.\n\nSo, you ready to go? Let's head out and salvage what we can!", objectives = "" }
WordHunterWoW_QuestEN[59130] = { title = "The House of Plagues", description = "The House of Plagues was the first to fall in this conflict. We believed its demise was the result of a careless accident. If only we had known the truth sooner...\n\nBut perhaps not all their knowledge was lost. Before you arrived, our scouts reported signs of movement near the wreckage of their necropolis.\n\nIf any survivors remain, we'd be wise to add them to our ranks. But approach with caution. The toxic fallout may have left them mad... or worse.", objectives = "" }
WordHunterWoW_QuestEN[59147] = { title = "The Hand of Purification", description = "Nikolon was not alone.\n\n<Eridia stares grimly out over the temple grounds.>\n\nLong have I toiled over the aspirants in my care. Long have I tended to this temple under my Paragon. To know that so many have fallen, alone, is a blow.\n\nBut this... wanton destruction! It will not stand.\n\nYou will be my hand, {name}. Go forth. End them. All of them.\n\nMy duty demands that I tend to those that remain. I will find you near the bridge when the way is clear.", objectives = "" }
WordHunterWoW_QuestEN[59171] = { title = "Prey Upon Them", description = "My mission cannot progress without a supply of anima. \n\nFortunately, the necromancers nearby have been kind enough to gather some into their maldracite crystals.\n\nYou will relieve them of those crystals. They may be reluctant to part with them, but I trust you can be... persuasive.", objectives = "" }
WordHunterWoW_QuestEN[59172] = { title = "War is Deception", description = "You have proven a useful ally, {name}.\n\nMephiles undoubtedly possesses a wealth of information for us. However, the House of Rituals is unforgiving when it comes to betrayal. He will not talk.\n\nNot that it matters. The House of Eyes has ways to... extract a prisoner's knowledge without the use of words.\n\nPlace the charged crystals around me. They will facilitate the interrogation.", objectives = "" }
WordHunterWoW_QuestEN[59175] = { title = "The Eternal Revenge", description = "<On the shelves there are hundreds of other phylacteries of varying shapes and sizes.\n\nMany bear names - this one specifically has a etching with the name Mor'Bitan.\n\nLady Vashj would be interested in this phylactery.>", objectives = "" }
WordHunterWoW_QuestEN[59179] = { title = "Daughter of the Night Warrior", description = "In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance.\n\nAnd... Ardenweald's destruction.\n\nThese visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm.\n\nShandris Feathermoon, Tyrande's daughter, is touched by dreams as well.\n\nEven now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.", objectives = "" }
WordHunterWoW_QuestEN[59181] = { title = "Into the Maw", description = "I have not seen Tyrande since she departed for Icecrown... but I see her in my dreams. She stalks a nightmarish landscape, brimming with the might of the Night Warrior.\n\nSuch power is too much for any mortal to bear for long. I shudder to think of the toll it has taken on my minn'do.\n\nHighlord Fordragon has told me of the Maw. If you truly have braved its horrors before, then I ask that you guide me through them as well.\n\nWe must find Tyrande and convince her to let go of the Night Warrior's rage.", objectives = "" }
WordHunterWoW_QuestEN[59185] = { title = "Entangling Web", description = "It would seem we have a means of luring Mor'Bitan to us. But what good is a web if the prey can run free?\n\nFor these rituals to work, the liches require a magical conduit. They draw runes with finely ground maldracite to channel anima.\n\nI have no doubt Mor'Bitan's necromancers have ground maldracite in the area. If we gather enough, we can draw a rune of binding to trap our target.\n\nWork with haste, {name}.", objectives = "" }
WordHunterWoW_QuestEN[59188] = { title = "Vaunted Vengeance", description = "So you are from my baroness's home world? It must be a special one to breed such powerful individuals.\n\nThe necromancers here have already begun preparation for Mor'Bitan's ritual. We should capitalize on their progress. \n\nThree necromancers act as the ritual's architects. Should we acquire their drafts, we could modify them to suit our purposes.\n\nCollect the plans... and feel free to savor your victims' torment.", objectives = "" }
WordHunterWoW_QuestEN[59189] = { title = "The Recovery of Tyrande Whisperwind", description = "The Night Warrior's power is tearing Tyrande apart. Such rage... it is consuming her.\n\n<Shandris is silent a moment.>\n\nAnd yet, my mother speaks true. We cannot leave the souls of my people to suffer.\n\nWe shall follow Tyrande into Torghast. We must find a way to save the spirits of the kaldorei.\n\nAnd in the process, pray that we can save my minn'do as well.", objectives = "" }
WordHunterWoW_QuestEN[59190] = { title = "Seek Your Mark", description = "I see why Draka sent you in her stead--you accomplish what she could not.\n\nWe have all the pieces. Now, we must simply put them together.\n\nThe steps to the ritual are simple: place our fractured crystals in formation around the obelisk.\n\nThen comes the sigil--*our* sigil. Use the maldracite powder to draw a binding glyph at the obelisk's base.\n\nWhen you are through, return to me.", objectives = "" }
WordHunterWoW_QuestEN[59196] = { title = "Go in Service", description = "We cannot waste any more time. We must get an audience with the Archon, before this next attack happens!\n\nWe need to find a way to get you to Elysian Hold... and quickly!\n\nHero's Rest is a place of respite for the aspirants of Bastion. You can see it floating above from across the fields.\n\nMeet me there when you can. I have a plan.", objectives = "" }
WordHunterWoW_QuestEN[59197] = { title = "Steward at Work", description = "Stewards are useful for many reasons.\n\nThey keep Bastion tidy, fix anything broken, and offer unrivaled companionship and support.\n\nYour new steward assistant should be able to repair the beacon. Then you can summon the Polemarch to Hero's Rest.", objectives = "" }
WordHunterWoW_QuestEN[59198] = { title = "On Swift Wings", description = "Our revered Archon has decided to grace you with an audience.\n\nIt is your duty to present your discoveries to her, then follow her wise judgment.\n\nShe holds audience in Elysian Hold, part of the sprawling Spires of Ascension, the home of the Ascended.\n\nWe shall carry you there, for it is a place for those who can fly.", objectives = "" }
WordHunterWoW_QuestEN[59199] = { title = "Kyrestia, the Firstborne", description = "I will escort you to hold audience with the Archon.\n\nI beseech you to present your information succinctly and directly.\n\nOur wise Archon will hear you and make a decision on the best course of action.", objectives = "" }
WordHunterWoW_QuestEN[59200] = { title = "The Wards of Bastion", description = "Each temple of Bastion is protected by a ward here in Elysian Hold. As long as the wards hold, no malevolent force can launch an assault.\n\nIt is concerning that the Forsworn were able to attack Purity in such force...\n\nYour orders are to examine the wards. As long as they hold, Bastion stands strong.", objectives = "" }
WordHunterWoW_QuestEN[59202] = { title = "Among the Chosen", description = "Only one rune remains...\n\nWe should return to the House of the Chosen and report to Margrave Krexus. He will want to know of our progress.", objectives = "" }
WordHunterWoW_QuestEN[59203] = { title = "Leave Me a Loan", description = "I run a myriad of businesses here. Betting rings, performance enhancers... whatever the customer is willing to purchase. \n\nHowever, a few of those customers are late with their payments. And a customer who does not pay is a customer without value.\n\nPlease ask them to surrender what they owe. I trust you know what to do if they refuse.", objectives = "" }
WordHunterWoW_QuestEN[59206] = { title = "Words of the Primus", description = "Even in his absence, the wisdom of the Primus rings true. This message must have been put here to await one who proved worthy of hearing it.\n\n<Draka peers at you.>\n\nYou came to Maldraxxus to learn why Bastion was invaded. Now you know that there is treachery in our ranks. And that there are noble souls here who will set things right.\n\nTell your allies in Oribos all you have witnessed. See that the warning of the Primus reaches the Eternal Ones.\n\nIt would be an honor to fight by your side again, {name}.", objectives = "" }
WordHunterWoW_QuestEN[59207] = { title = "Unshackled Knowledge", description = "These Forsworn are looting the artifacts contained in Kalliope's Rest. What is worse is they have captured many of the shrine's scholars.\n\nI fear they will interrogate these aspirants for knowledge about the artifacts held within the inner chamber of the shrine.\n\nMost escaped with me, but Lano, Eratus, and Tyrana have not returned yet.", objectives = "" }
WordHunterWoW_QuestEN[59209] = { title = "Rebel Reinforcements", description = "<General Draven looks around.>\n\nWe require additional reinforcements.\n\nI know of two here that are fiercely loyal to the true purpose of Revendreth. The Fearstalker left them here to be consumed by the anima drought due to their allegiance.\n\nThey are both fully capable of assisting us in our mission.\n\nTake this anima stake and infuse them. Direct them to me, I will explain the situation.", objectives = "" }
WordHunterWoW_QuestEN[59210] = { title = "Tainted Cores", description = "This lich seeks a reward for his assault on the House of Eyes. But the power he craves will be his downfall.\n\nWe will use our knowledge of his secret ritual to lure him out of the House of Rituals. \n\nTake these crystals, {name}. Charge them with anima reclaimed from Mor'Bitan's slain minions.\n\nBut fracture them first, so that they shatter as the ritual nears completion... but not before Mor'Bitan believes that it has begun.\n\nThat is when we will strike.", objectives = "" }
WordHunterWoW_QuestEN[59223] = { title = "By Any Other Name", description = "Excellent work, my apprentice! Our laboratory is back in working order!\n\nNow, there is one final ingredient we require to complete our potion for Margrave Stradama.\n\nYou will need to run along to the greenhouse. I've cultivated a sprig of dreadshade that should be ready to harvest.\n\nI will prepare the other reagents while you're away. Be safe, apprentice!", objectives = "" }
WordHunterWoW_QuestEN[59225] = { title = "[DNT] Azerite Reward Test Quest - BJI", description = "[DNT] This quest should award Azerite Armor and Azerite if you have a HoA, and armor stripped of powers and no azerite if you do not have a heart of azeroth yet.", objectives = "" }
WordHunterWoW_QuestEN[59231] = { title = "Fathomless Power", description = "Forgive me, apprentice... I felt a bit woozy for a moment! But you've done it! You've crafted the potion!\n\nI'm so proud of you. What joy your work brought to our margrave!\n\nWhat manner of teacher would I be were I to ask for your help and not offer my own in return? If you have research you must conduct, you have my full support!\n\nLet us venture to your laboratory, then. I wait with bated breath to behold your future achievements!", objectives = "" }
WordHunterWoW_QuestEN[59232] = { title = "A Lesson in Humility", description = "Thank you for your service in deposing the Accuser and elevating Lord Chamberlain in her place.\n\nThe Accuser's unprompted betrayal has rendered her both undeserving and unfit to serve on the Court of Harvesters.\n\nNow, please, observe what happens to traitors in Revendreth.", objectives = "" }
WordHunterWoW_QuestEN[59233] = { title = "The Prince's New Crown", description = "The crown is ready. I will entrust you to deliver it to Renathal.\n\nMake haste, {name}. This power will surely attract assailants if word gets out.\n\nYou may use the mirror to return. Know that I will be dispatching others to destroy it after your arrival. \n\nSafe travels, Maw Walker.", objectives = "" }
WordHunterWoW_QuestEN[59242] = { title = "Their New Home", description = "It pains me to leave my mother behind... but the souls of my people must be brought to safety.\n\nI heard the attendants in Oribos speaking of a place called Ardenweald. A realm of ancient forests where the spirits of nature slumber.\n\nThis is a land you know well, is it not? I would see its wonders with my own eyes.\n\nPerhaps the spirits there will know how to save my minn'do from the Night Warrior's power.", objectives = "" }
WordHunterWoW_QuestEN[59246] = { title = "Daughter of the Night Warrior", description = "In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance.\n\nAnd... Ardenweald's destruction.\n\nThese visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm.\n\nShandris Feathermoon, Tyrande's daughter, is touched by dreams as well.\n\nEven now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.", objectives = "" }
WordHunterWoW_QuestEN[59254] = { title = "Enhanced Combat Tactics", description = "Alaria says that the quilboar kidnapped other members of her expedition.\n\nChances are we'll have to brave the quilboar's den. That's no small feat. They are far more aggressive and intelligent than the murlocs you faced earlier.\n\nI need to make sure I'm not sending you to your death. We're going to have one last sparring session.", objectives = "" }
WordHunterWoW_QuestEN[59256] = { title = "The Fearstalker", description = "The trap has been set and the Fearstalker has walked right in.\n\nJust as I expected, her pride has blinded her to the obvious. Have that vial I gave you earlier ready. It may prove useful in the fight ahead.\n\nWhen you are ready, we can spring the trap.", objectives = "" }
WordHunterWoW_QuestEN[59258] = { title = "Home of the Tirnenn", description = "The Horned Hunter is no longer here. But I do know where he went.\n\nHe tracked his prey to the west of here, in the Elder Stand. These woods in particular have grown dangerous as of late, and we are currently beset by invading devourers.\n\nThey have overrun the roads between here and the Stand. I shall accompany you across the bridge, and see that you are delivered to the Horned Hunter.", objectives = "" }
WordHunterWoW_QuestEN[59262] = { title = "Broken Wings", description = "You help me? Really? Wow!\n\nLook at me. What am I?\n\nI have beak. Feathers. Scaly toes. I am bird, yes? \n\nBut birds have wings. And I have arms. Why I not have wings? \n\nI broken. I can not fly.\n\nLarion nearby, flies so gracefully. I must study her wings up close! \n\nYou help me?", objectives = "" }
WordHunterWoW_QuestEN[59263] = { title = "Feathers of Flight", description = "Now, let us see this next to my arm...\n\nLook! There many long feathers along the edges of the Larion's wing!\n\nAnd none on mine. This is why I can not fly!\n\nHmm. It will take lots of flight feathers to give me wings. \n\nYou help?", objectives = "" }
WordHunterWoW_QuestEN[59265] = { title = "Prying Eyes", description = "The Constructs would repurpose the carcass of our necropolis. But we will need its parts for our own ends.\n\nLet us deliver a warning to these scavengers.\n\nSlay the Constructs amid our wreckage. Pluck the eyes from their skulls. Such is our signature.\n\nThey will know to fear the darkness once more.", objectives = "" }
WordHunterWoW_QuestEN[59293] = { title = "Special Formula", description = "You may think I'm naturally gassy, but it actually takes a lot of work to build it all up. This is all the result of a nice coating of Pox Nodules.\n\nHelp me refresh my coating.\n\nJust get me near the absorbing pox and I'll pull the nodules right off his slimy skin.", objectives = "" }
WordHunterWoW_QuestEN[59311] = { title = "How to Catch a Glimmerfly", description = "Yes! Proper tools collected. Now to catch glimmerflies!\n\nAnima drought more severe in northern pools. Many Starving Glimmerflies, most eager to drink from our animyllis blooms.\n\nPlace blooms, then while glimmerflies are drinking attach to filaments! Then return to me.", objectives = "" }
WordHunterWoW_QuestEN[59314] = { title = "Sinfall", description = "I knew you could be counted on. Revendreth's revival relies on forging pacts with those outside of our realm. \n\nThe Prince never had any doubt that you would agree to join our cause. He summoned the Court of Harvesters in anticipation of your arrival. \n\nRenathal awaits you within Sinfall, where you will be presented to the court.", objectives = "" }
WordHunterWoW_QuestEN[59315] = { title = "The Court of Harvesters", description = "Partnerships such as ours will be key to Revendreth's revival. \n\nAs Harvesters, we have the ability to extend our powers to mortals, though the decision must be unanimous. To that extent, the court has gathered and is awaiting your arrival.\n\nLet's not keep them waiting.", objectives = "" }
WordHunterWoW_QuestEN[59316] = { title = "Binding Power", description = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly.\n\nYou will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense.\n\nOnce complete, your connection will transcend physical space and make you stronger in more than mere brawn.", objectives = "" }
WordHunterWoW_QuestEN[59317] = { title = "Strengthening the Bond", description = "Do you feel it, too? Our connection is stronger than I imagined could be possible. \n\nI have been told that the bond will continue to grow over time, though we do have the ability to accelerate the process. \n\nSinfall needs our strength. Perhaps it is best we engage in this method now.", objectives = "" }
WordHunterWoW_QuestEN[59319] = { title = "Advancing Our Efforts", description = "A venthyr's primary responsibility is ensuring that souls are unburdened of their pride, but they must see to other matters as well. \n\nWe must act beyond the bounds of Revendreth to ensure that the souls of the Shadowlands keep to their fate.\n\nAllow me to demonstrate with a simple task for your companion here. This will be the first of many strikes.", objectives = "" }
WordHunterWoW_QuestEN[59321] = { title = "Sacred Covenant", description = "Our covenant is more than just pacts and promises. We have immense power, too. And that power we shall bestow upon you in a sacred ritual.\n\nOnce complete, you will be able to call upon our gifts with ease.", objectives = "" }
WordHunterWoW_QuestEN[59322] = { title = "Shared Souls", description = "The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another.\n\nDoing so has no known drawbacks, but offers many advantages for both parties involved. \n\nThe Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[59323] = { title = "Anima Awakening", description = "This ritual will bestow upon you our gift. \n\nWe will stir the anima within your soul, awakening a power that has only been known to Harvesters.   \n\nIt has never been performed on a mortal before, but I have been assured that it won't hurt a bit.", objectives = "" }
WordHunterWoW_QuestEN[59325] = { title = "A Stalwart Ally", description = "We have our work cut out for us, Maw Walker. The Harvesters will not relinquish their power without a fight. \n\nYou will need stalwart allies at your side. Ones that know how battles are fought within the Shadowlands. \n\nLet me be your guide. Together, we will see Revendreth return to its true purpose.", objectives = "" }
WordHunterWoW_QuestEN[59327] = { title = "In the Ruin of Rebellion", description = "Well, here we are -- Sinfall.\n\nLast I saw, the Master was dragging Prince Renathal and his most loyal followers here in a prison convoy. However, this is a forbidden place, wrapped in rumors and mystery. I heard it was once the workshop of Denathrius, where he performed dark experiments.\n\nIntriguing to be sure, but we are here to find Renathal. Search below, but proceed with caution. I will send word for the Accuser to make her way here with what allies she can muster.", objectives = "" }
WordHunterWoW_QuestEN[59339] = { title = "Enhanced Combat Tactics", description = "Alaria says that the quilboar kidnapped the rest of the expedition... including my son.\n\nChances are we'll have to brave the quilboar's den. That's no small feat. They are far more aggressive and intelligent than the murlocs you faced earlier.\n\nI need to make sure I'm not sending you to your death. We're going to have one last sparring session.", objectives = "" }
WordHunterWoW_QuestEN[59342] = { title = "Taming the Wilds", description = "As a hunter, you need a trustworthy beast at your side... or else these quilboar will slaughter you.\n\nWhen you're ready, I'll teach you how to tame such a beast. Then you must find one to be your loyal companion.", objectives = "" }
WordHunterWoW_QuestEN[59343] = { title = "Kindred Spirits", description = "I have come to the realization that you and I are meant to be the most kindred of spirits. \n\nYour enduring nature has enraptured me, and I'm afraid I cannot bear to imagine an afterlife without your beguiling presence. \n\nLet us bind our souls, and forever carry each other in both heart and mind.", objectives = "" }
WordHunterWoW_QuestEN[59347] = { title = "A Monk's Focus", description = "You fought well against the harpies, but we all need to become stronger to face what lies ahead.\n\nThe first step is to find a nice place to meditate and focus yourself.\n\nA monk is only as strong as they are focused.\n\nCome. I know of such a place.", objectives = "" }
WordHunterWoW_QuestEN[59348] = { title = "More Wings!", description = "Idea! Maybe I am too heavy. Maybe need more wings!\n\nGlimmerflies have lovely wings. With correct bait and strong rope, perhaps we can catch.\n\nPlease bring Animyllis Blooms. Their nectar is delicious for glimmerflies, and makes them drowsy!", objectives = "" }
WordHunterWoW_QuestEN[59349] = { title = "One Last Spar", description = "Let us have a quick sparring session before we return to camp, {name}.\n\nI want to see how this island has pushed you to grow.", objectives = "" }
WordHunterWoW_QuestEN[59350] = { title = "A Druid's Form", description = "Thank you for rescuing me, {name}. Allow me to aid you in your druidic studies.\n\nTo escape from the pit, I took on the form of a stag. I may know of a way you can learn to do the same.\n\nCome with me. There is an ancient druid stone nearby. Let us use it to commune with the wilds.", objectives = "" }
WordHunterWoW_QuestEN[59351] = { title = "Strings and Things", description = "Glimmerflies are creatures of anima. Though they look delicate, they are quite strong!\n\nFilaments from etherwym tails are sturdy. They should help hold onto glimmerflies. \n\nCollect for me!", objectives = "" }
WordHunterWoW_QuestEN[59352] = { title = "A Mage's Knowledge", description = "Ye got some good spells fer a novice mage. Ye might even be as good as I am one day!\n\nBut ye don't know Polymorph! How could ye not know that?\n\nPolymorph's one of a mage's most useful spells. I can teach it tae ye, if ye can find me spellbook.\n\nLast I saw, the ogres threw me book in the lake. The LAKE!\n\nGo get me book, and I'll show ye how tae cast Polymorph.", objectives = "" }
WordHunterWoW_QuestEN[59354] = { title = "The Best Way to Use Sheep", description = "I'm not gonna send ye off without showin' ye how tae properly use this spell.\n\nYe wanna cast Polymorph if ye get yerself into a situation when two foes are fightin' ye at once. \n\nCole and I will spar with ye a bit tae make sure ye know what tae do.", objectives = "" }
WordHunterWoW_QuestEN[59355] = { title = "A Hunter's Trap", description = "By now, most hunters would have been trained in the art of trapping. Allow me to get you up to speed.\n\nWe'll start with a freezing trap. In order to make one, you'll have to forage materials from your surroundings.\n\nMeredy can provide you with a mote of ice. Scavenge the area for the rest of what is required.\n\nAnd don't delay. You will need that freezing trap to deal with a problem that has cropped up within the camp.", objectives = "" }
WordHunterWoW_QuestEN[59356] = { title = "Hunting the Stalker", description = "Now that you have your trap, there's a problem we need to deal with.\n\nA wild beast has been stalking our camp. It's already stolen some of our food. We have little enough as it is.\n\nYou and I will work together. Set your freezing trap and lure out whatever this creature is.\n\nOnce it is caught, I will determine if the beast can be tamed... or if it needs to be put down.", objectives = "" }
WordHunterWoW_QuestEN[59426] = { title = "Your Personal Assistant", description = "Here in Hero's Rest, we have a beacon that is the fastest way to draw the Polemarch's attention.\n\nIt has been quite some time since we have used it, and I am afraid that it has fallen into disrepair.\n\nI authorize you to receive a steward companion during your stay here in Bastion.\n\nI will call for some to convene here. You may select one to aid you.", objectives = "" }
WordHunterWoW_QuestEN[59427] = { title = "We Need More Power", description = "Laurent's plan is a bit ambitious. \n\nMirrors are most reliable when used to traverse short distances. Traveling to the sanctuary will require a great deal of power, more than he or I have. \n\nThe shrouded have stores of anima in their compound. With enough of it, the mirror should be stable enough to get us where we need to go.", objectives = "" }
WordHunterWoW_QuestEN[59430] = { title = "A Plague on Your House", description = "Though the physical House of Plagues is lost, the knowledge contained within was not. There are survivors here that continue to research and develop new horrifying weapons. \n\nIn time we will restore the house and rise to even greater power, unleashing creations and plagues never before seen upon our enemies!\n\nPerhaps you can help? Speak with survivors and see if any of them can use your aid.", objectives = "" }
WordHunterWoW_QuestEN[59520] = { title = "Plaguefall: Knee Deep In It", description = "There are many in the House of Plagues who survived its destruction only to later fall victim to the plagues released in the explosion. Margrave Stradama herself was driven mad from a mixture of twelve different airborne poxes!\n\nThese dangers still remain and spread out from the ruins, infecting new victims daily.\n\nI need you to travel into the ruins and recover samples from the victims there.", objectives = "" }
WordHunterWoW_QuestEN[59554] = { title = "A Fine Journey", description = "Aspirants new and ancient, take note! The heralded Agthia's Repose calls.\n\nMake the ceremonial journey and learn about the ancient fallen Paragon who saved this very realm!\n\nFind the Repose just a short ride southwest of Hero's Rest.", objectives = "" }
WordHunterWoW_QuestEN[59555] = { title = "Enemy at the Door", description = "The remaining houses of Maldraxxus have joined forces against us. Their armies besiege the Seat of the Primus, and our defenses cannot hold forever.\n\nOur reserves have met the enemy in battle. I need you to break the siege.\n\nReport to Heirmir and Marileth. They will give you the means to rain destruction on our foes.", objectives = "" }
WordHunterWoW_QuestEN[59556] = { title = "Welcome To Our House", description = "Your ties to the other covenants had me doubting you would return. I see now that was foolish of me.\n\nOutsider or not, you have stood bravely beside the armies of Maldraxxus. I am confident the Primus would have welcomed you into our ranks with pride.\n\nOne day, he might return as well. But we cannot afford to wait. \n\nIn the Primus's absence, I will name you a Necrolord of Maldraxxus.", objectives = "" }
WordHunterWoW_QuestEN[59583] = { title = "Welcome to Stormwind", description = "Now that we are back in Stormwind, I need to deliver my mission report to King Wrynn.\n\nIn the meantime, I've asked Lindie to accompany you around the city. There's a lot to see and do in Stormwind, so feel free to explore at your leisure.\n\nI'll send for you once I've delivered my report to the king.", objectives = "" }
WordHunterWoW_QuestEN[59586] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Dalgrun Steelpine to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[59587] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Frazzle Frostfingers to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[59588] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Juisheng Halfclaw to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[59589] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Ezul'aan to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[59590] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Patrice Lancaster to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[59591] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Veruca Darkstream to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[59592] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Mulric Boldrock to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[59593] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Laphandrus Voidheart to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[59594] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Kualiang Thunderfist to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[59596] = { title = "Collective Soul", description = "Souls in Maldraxxus are bound together in war. We draw strength and wisdom from those around us.\n\nShould you fall in battle, part of you would remain with your fellow soldiers. Just as they would remain with you. \n\nPlague Deviser Marileth has volunteered to teach you the process of soulbinding. From what I have seen, yours will be a powerful bond.", objectives = "" }
WordHunterWoW_QuestEN[59597] = { title = "Come On, We're Simpatico!", description = "Soulbinding is a wondrous process! I invite you to bind with me to learn how it works, but in time you might bind with others. \n\nI have known many soulbinds, but the foremost of them all was Margrave Stradama! Her knowledge, talent and kindness became part of who I am. Now and forever, it is a bond we share.\n\nI only hope to be so useful to you, my apprentice! Bound together, I shall grant you all I can and aid you even when we are apart.", objectives = "" }
WordHunterWoW_QuestEN[59598] = { title = "Good for the Soul", description = "Two souls are better than one! We can achieve far greater things together than we can if we were alone.\n\nHowever, it is not just the two of us against all threats. There are many more that will aid us in the coming battles.\n\nLet's speak with Merick to learn more on the subject. Don't be shy--I can introduce you!", objectives = "" }
WordHunterWoW_QuestEN[59603] = { title = "In Shadowlands Service", description = "As Maldraxxi, we are responsible for ensuring the security of the Shadowlands. \n\nWhen enemies emerge, we are the ones who face them!\n\nThe threats to the Shadowlands are far more than any one of us can handle. That's where I come in.\n\nI will be your eyes on the field. Allow me to demonstrate with a simple task for Marileth, so that you may both reap the benefits of my services.", objectives = "" }
WordHunterWoW_QuestEN[59609] = { title = "No Rest For the Dead", description = "Excellent work, my apprentice! You have completed your training and are now a true Necrolord.\n\nThat also means you've taken on additional responsibilities. Such is the burden of genius!\n\nI believe Baroness Draka wanted to have a word with you.", objectives = "" }
WordHunterWoW_QuestEN[59615] = { title = "Every Dog Has Its Day", description = "Maw Walker, when I heard you were building constructs and a home for souls still loyal to Maldraxxus, I began my search for you!\n\nI am loyal and have always wanted a construct form, but the Margrave was unwilling to build one that suited my natural inclinations.  \n\nI lived my whole life with the curse, it's all I know, and it's all I still want.\n\nWould you build a construct for me?", objectives = "" }
WordHunterWoW_QuestEN[59616] = { title = "Army of One", description = "Mevix will lead the attack, but you will finish it. There are no reinforcements, no cavalry.\n\nOnly you and your runeblade.\n\nShow me the might you wield, outsider. Lay siege to the House of Constructs and bring them to ruin!", objectives = "" }
WordHunterWoW_QuestEN[59621] = { title = "Breaking a Few Eggs", description = "As you can see, we have a gorm problem.\n\nI'm not sure what has them so riled up. They've been getting bigger, more hostile. It must be due to the anima drought. If nothing stops them, they'll eat everything!\n\nTheir egg production is out of control. We can't let their population grow any larger. Please, go in to their nests and destroy as many of their eggs as you can find.", objectives = "" }
WordHunterWoW_QuestEN[59622] = { title = "Tending to the Tenders", description = "The eggs are a problem, but so are the gorm that take care of them.\n\nThe egg-tenders are the leaders of the hive when no matriarch is present. If left unchecked, they will simply produce more eggs and we will be right back where we started. Or worse, one of them could turn into a queen. \n\nThey are simply too large and hostile for us to properly contain. I see no other recourse than to put them down.", objectives = "" }
WordHunterWoW_QuestEN[59623] = { title = "What a Buzzkill", description = "What do you say? Fancy one more hunt?\n\nOne of those little flying pests has grown into a very large flying pest. Large, pristine gorm parts are hard to find in the best of times, and a smith always appreciates a challenge.\n\n<Cavina's voice drops as he leans in towards you.> Besides, I'm worried about the safety of my family and the rest of us in the grove.\n\nBring me the stinger from that big fella and I'll make it worth your while.\n\nDo we have a deal?", objectives = "" }
WordHunterWoW_QuestEN[59625] = { title = "The Only Cure", description = "Maldraxxus is on the path to reclaiming its rightful role as defender of the Shadowlands. But the treasonous attack on Bastion remains a stain on our honor.\n\nWe had thought Gharmal's forces routed, but we've received word from the Paragon of Courage that reinforcements have begun arriving at her temple.\n\nThis threat must be eliminated.\n\nI have volunteered to spearhead this operation. Your support would be an asset, {name}.", objectives = "" }
WordHunterWoW_QuestEN[59641] = { title = "The Nation of Kul Tiras", description = "Kul Tiras is the greatest naval power on Azeroth, and a former member of the Alliance. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was killed at Theramore.\n\nMany have said that Jaina believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father on that day. Perhaps she feels it is time to put the past to rest.\n\nLoathe as I am to put Jaina at risk... Kul Tiras must rejoin the Alliance.\n\nLight be with you.", objectives = "" }
WordHunterWoW_QuestEN[59644] = { title = "Blinded By The Light", description = "{name}, Sire Denathrius must be stopped. The anima he is stealing from the Shadowlands is weakening the bonds that seal the Jailer within the Maw. That must not happen.\n\nTime is short so we must strike quickly. I would like for you to head up to the surface, into that accursed Light, and align as many mirrors as you can find to the focusing mirror atop the portcullis.\n\nWe will shine a light on Castle Nathria so bright no venthyr will wish to step forth from that fortress to challenge us.", objectives = "" }
WordHunterWoW_QuestEN[59645] = { title = "Death Rains", description = "With its repeated invasions here, the House of Constructs continues to sully the honor of Maldraxxus.\n\nWe cannot salvage that honor until justice is done. May we mete it so thoroughly that none will ever attempt this desecration again.\n\nEliminate these traitors with me, {name}. Leave none standing.", objectives = "" }
WordHunterWoW_QuestEN[59648] = { title = "Peace by Piece", description = "These Maldraxxi fiends have reoccupied my temple. They have entrenched this resurgence with shields powered by necromancy.\n\nMy disciples--the ones who were not captured and executed by your treacherous compatriots--report the core of a necrotic bulwark to the south. We cannot counter their forces until the shield is brought down.\n\nSee it done. I will not tolerate your presence otherwise.", objectives = "" }
WordHunterWoW_QuestEN[59650] = { title = "No Hesitation, No Surrender", description = "I cannot fathom where the constructs acquired these reinforcements, but we are once again outnumbered. I seethe at the thought of my fallen disciples.\n\nYou will make this right.\n\nThe renegades have established a foothold in the northern region of the temple. Their necrotic magic has granted them a shield, defending them from ranged assault. Disable it.\n\nLet nothing impede you. This is the way of Courage.", objectives = "" }
WordHunterWoW_QuestEN[59653] = { title = "Don't Cross Courage", description = "We have rendered the enemy holdouts defenseless. My disciples will begin preparations to purge the corruption that your errant kind have left on our home.\n\nBut more still remain in the inner sanctum of the temple. Their defenses prevent us from flying in en masse, but I can secure a foothold myself. We will cross the breach and annihilate them.", objectives = "" }
WordHunterWoW_QuestEN[59656] = { title = "Well, Tell the Lady", description = "<Thorodir breathes a deep sigh of relief.>\n\nThat's that, I'd say. The Banks are largely safe now, thanks to you. We can handle the rest of the cleanup on our own now.\n\nThe Lady of the Falls will want to hear of your success here. Why not go tell her the good news?", objectives = "" }
WordHunterWoW_QuestEN[59659] = { title = "Aerial Absolution", description = "My kyrian would have attempted to retaliate by now, but these vile interlopers are a devious sort.\n\nTheir necromancers pollute the air, tainting it with foul power that corrodes our very wings.\n\nI cannot advance an assault until they are eradicated. Deal with these befoulers, and I will deliver retribution to the rest.", objectives = "" }
WordHunterWoW_QuestEN[59660] = { title = "A New Court", description = "My dear {name}, I have heard a delightful rumor that you are considering hosting a new court in Sinfall.\n\nIf that is true, you simply must permit me to recommend staff to help you host a perfect court.\n\n<Theotar pulls long parchments out of his pockets.>\n\nI have been developing ranked lists for every court staff position since the moment I stepped foot in Sinfall.\n\nI do not wish to be a braggart, but courts are kind of my specialty.", objectives = "" }
WordHunterWoW_QuestEN[59661] = { title = "Ember Court Rehearsal", description = "Look, {name}. Venthyr have been throwing fancy courts for themselves ever since they were created.\n\nIt won't always be easy to impress them with our own court.\n\nDon't worry, I've got a plan.\n\nI've scheduled a rehearsal court for us to learn the ropes during a practice run.\n\nYou, me, Renathal, and a few socialites from the covenant who are eager to help us succeed.\n\nRelax. It'll be fun!", objectives = "" }
WordHunterWoW_QuestEN[59674] = { title = "A Friendly Rivalry", description = "Ah, a fresh soul! Your perspective may prove useful to us.\n\nNemea and I have opposing viewpoints. She lauds her larion, creatures native to Bastion whom she raises and trains as her companions.\n\nHowever, I find that phalynx are the superior beings. They are efficient, obedient, and easy to work with.\n\nPlease, come learn both of our ways. Perhaps you can decide which of our ways of life is superior.", objectives = "" }
WordHunterWoW_QuestEN[59676] = { title = "Harvester of Desire", description = "So, here's the sketch: we muck you up to look like one of the servants. This stuff is protected by anti-theft so if 'em clothes think they are being stolen they teleport back here, you an' all.\n\nYou \"should\" be able to reach the Countess with your message. Just smile, nod, do as you're told, don't talk to anyone, and don't make eye contact with anything that's got wings. They'll know you shouldn't be there.", objectives = "" }
WordHunterWoW_QuestEN[59678] = { title = "Sustain, In Vain", description = "These turncoats have kept busy. They've opened more portals around the area, allowing themselves to replenish their numbers with little trouble.\n\nEven with her might, the Paragon cannot eliminate an endless army. Let us destroy these portals. Without reinforcements to sustain this contingent, it will surely fall.", objectives = "" }
WordHunterWoW_QuestEN[59698] = { title = "Wipe the Slate Clean", description = "At last, the skies belong to us once more... and in those skies, the storm of our vengeance brews.\n\nCome, you who claim to be true Maldraxxi. You wish to right the wrongs of those you once called allies?\n\nRain your justice upon them! Show no quarter!", objectives = "" }
WordHunterWoW_QuestEN[59700] = { title = "The Last Labor", description = "The evil that threatens Bastion crumbles beneath us. But if we allow this cruel baroness to evade justice, we have not won this day.\n\nShe cowers in the necropolis above, casting her shadow on this once sacred temple.\n\nWe will pull the dagger from our backs. This wound will heal.", objectives = "" }
WordHunterWoW_QuestEN[59701] = { title = "Common Ground", description = "Now that we have a stronghold from which to operate, we need to begin the next stage of my plan to wrest control of Revendreth from the Master.\n\nWe must convince the Court of Harvesters to convene. We must not have them come here, though. It would be suicide.\n\nGo to my old fortress, Darkwall Tower, and place these banners at the four most distant points of the tower. This will ensure the power of the Harvesters and the Master will not be able to interfere with a neutral meeting.", objectives = "" }
WordHunterWoW_QuestEN[59706] = { title = "Invitation for the Countess", description = "The Countess, Harvester of Desire.\n\nHer wits are sharper than most swords. While I have never seen her carry a weapon, you must assume she is never unprotected.\n\nHer mansion mirrors my own, on the Northeastern side of Castle Nathria. Her dominion was that of the Castle Ward, and it is her authority that keeps the nobles in line.\n\nShe will appreciate a secret message. I will send a dredger ahead with a plan to infiltrate her party. Meet him on the Bridge of Temptation. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[59707] = { title = "Invitation for the Tithelord", description = "The Tithelord is a bully and a coward, just like every Harvester of Envy before him.\n\nHe is still a force beyond our current reckoning. I have sent Nadjia and Temel to Pridefall Hamlet in the south to ascertain the best, most non-lethal way to reach the Tithelord.\n\nMeet them there and use caution. The Tithelord would kill you in less than the blink of an eye if he thought it would gain him more power or authority.", objectives = "" }
WordHunterWoW_QuestEN[59708] = { title = "Invitation for the Stonewright", description = "The Medallion of Wrath is in the hands of the Stonewright. She is ancient, powerful, and responsible for creating the Stone Legion.\n\nShe is not someone to be subtle with. It is a very dangerous thing to ask, but would you meet with General Draven at the Dominance Gate? \n\nIf we are to see the Stonewright attend, she must know the severity of our request, which means both you and Draven walking right in the front door.", objectives = "" }
WordHunterWoW_QuestEN[59709] = { title = "Afterlife Goes On", description = "A new dawn shines on Bastion. I had my reservations, but you have proven that honor yet remains in Maldraxxus.\n\nTake my hand once more. I will return you to the temple's entrance.\n\nLet all Maldraxxi know of our victory. And for the sake of peace, ensure that this never happens again.", objectives = "" }
WordHunterWoW_QuestEN[59710] = { title = "A Curious Invitation", description = "Psst. You there. Yeah, you.\n\nYou that Maw Walker them fangs been going on about? Huh. I figured you'd be bigger.\n\nAnyway, the Taskmaster wants to ahhh ... \"extend his compliments and an invitation to visit his workings.\" That's a fancy word for a bunch of rocks me and my mates are diggin' up.\n\nIf you're keen an' all that, pop down to Feeder's Thicket and meet with the fang's courier, Araak. He'll get you sorted right out.", objectives = "" }
WordHunterWoW_QuestEN[59711] = { title = "Harvester of Envy", description = "Thank you for meeting us at a minimum safe distance from the Caretaker's Manor. There are enough people around here that may still find the idea of me in a cage to be worth the trouble.\n\nIt is too dangerous for you or I to speak to the Tithelord. He is too impulsive and eager to please Denathrius. I recommend we send Temel. \n\nThe stone fiend is a common messenger for Revendreth and few aside from a handful of observers will bat an eye at his arrival. Just shove him when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[59712] = { title = "The Lay of the Land", description = "So, yeah, not sure why he wants you. Based on a long time working for him, I'm gonna say he wants to use you to do something unsavory to further his interests. But, I'm biased. I could tell you so many stories.\n\nLet's go check on my friend, Nadjia.", objectives = "" }
WordHunterWoW_QuestEN[59713] = { title = "Active Ingredients", description = "Matyas will be difficult to handle until we can take my sinstone from him. We need something to knock him out. \n\nWill you fetch a few ingredients for me, mortal? I have a cunning plan.", objectives = "" }
WordHunterWoW_QuestEN[59714] = { title = "A Fine Vintage", description = "We will need something special to use as the base of our mixture. To get him to drink it down he will have to believe you've brought him a gift. \n\nHe fancies himself quite the connoisseur. Some ancient and stuffy vintage will tempt him.\n\nCheck the old cellar near the ruins. It once held supplies. Perhaps a bottle still lingers in the depths. Araak and I will work out the other details.", objectives = "" }
WordHunterWoW_QuestEN[59715] = { title = "Message for Matyas", description = "Alright. Everything is prepared. When you are ready, ask Courier Araak to summon Taskmaster Matyas as though you have just arrived.\n\nI am sure a gift of a favorite drink will tempt him and the poison we've concocted will incapacitate him long enough to take my sinstone from him.\n\nOur plan will work flawlessly!", objectives = "" }
WordHunterWoW_QuestEN[59716] = { title = "Comfortably Numb", description = "A mortal in Revendreth. It's rumored that you can traverse the Maw? Astonishing. I have so many questions.\n\nBut, I must restrain my curiosity. I have a ... shall we say ... proposition for you that I feel would be advantageous for us both. If it is true that you are able to freely travel these lands then you have access to certain information I cannot reach. \n\nYou see how you could be useful to me? Come, let us discuss the matter further.", objectives = "" }
WordHunterWoW_QuestEN[59719] = { title = "The Court", description = "Well, we have quorum. You have done all you can do for us at this stage, Maw Walker.\n\nIt falls to me, now, to convince these ancient fools to forsake the greatest patron in all of their reality and throw their lot in with me, a failed rebel with a \"new\" plan.\n\nLet us see if I can still sway a crowd, as it were. Wish me luck.", objectives = "" }
WordHunterWoW_QuestEN[59720] = { title = "Harvester of Wrath", description = "We walk in the winged shadows of my brothers and sisters in arms, Stoneborn I have trained since they were first carved from stone.\n\nThis is an ancient rite. If we cross this bridge on foot, defeating any who would dare stop us, we may have an audience with the mother of the stoneborn. However, know that our safe return is not guaranteed, so try not to offend her.\n\nI do not look forward to this.", objectives = "" }
WordHunterWoW_QuestEN[59721] = { title = "Becoming the Hunt", description = "<Reldorn grins at you.>\n\nHe knew you'd be back! The Horned Hunter went on ahead to prepare the hunting ground. He said you should join him as soon as you can. \n\nNow that you have the materials for the trap, you just need to reach him...\n\nIt's dangerous territory to traverse, but I've been devising a glamour that should help you avoid the attention of the roaming beasts. Maybe if it's useful, you could put in a good word for...\n\nAhem. Anyway, we should focus on your quarry. Good hunting, friend.", objectives = "" }
WordHunterWoW_QuestEN[59722] = { title = "Grand Theft Necropolis", description = "The necropolis is safe and secure, but we can only maintain a portal to the Seat of the Primus for a short time.\n\nKhaliiq will return with you and work on establishing a permanent portal connection.", objectives = "" }
WordHunterWoW_QuestEN[59724] = { title = "The Field of Honor", description = "Thanks to you, {name}, I am free of Matyas's control for the first time in ... well, a very long time. \n\nNow, together, we will seek my vengeance. \n\nI've laid a solemn duty upon you by naming you as my second for this duel. I know not the code in your homelands but in mine, it is your task to secure the field. Matyas and his followers are garrisoned at Witherfall Ruin nearby. Unless I miss my guess, that's where he will have run.\n\nI will prepare for the battle and join you soon.", objectives = "" }
WordHunterWoW_QuestEN[59725] = { title = "Archivist on the Edge", description = "If the curse isn't removed, Qadarin will waste away until nothing is left! \n\nWe used to bind and seal curses just like this all the time, but we haven't had to deal with one in ages. \n\nGo to Archivist Dreyden at the Grove of Memory. He will know which curse this is and can give you its scroll. \n\nBring it back so we can figure out what we need in order to cast a counter-curse.\n\nHurry, {name}!", objectives = "" }
WordHunterWoW_QuestEN[59726] = { title = "It's a Trap", description = "At last, I will have my vengeance!\n\nI am certain Matyas will flee again if he sees me first so you will need to confront him on my behalf, friend. Then, while he's distracted, I will engage him.\n\nAt that point, your obligation as my second is a formality. You must assure Matyas does not dishonor the duel and cheat. When he inevitably does, I expect you'll help me defeat him.\n\nHe's just through the portcullis there.", objectives = "" }
WordHunterWoW_QuestEN[59731] = { title = "An Expected Guest", description = "While we await word from Huln, another matter of importance has arisen.\n\nBwonsamdi has returned to Ardenweald. Lord Herne believes he is here to request an audience with the Winter Queen.\n\nThe loa of death, however, pursues a different purpose. One that I have glimpsed in my dreams.\n\nMeet with Bwonsamdi. Discover what fate has in store for the both of you.", objectives = "" }
WordHunterWoW_QuestEN[59732] = { title = "Something Extra for the Winter Queen", description = "Ya did good wit' how ya handled Mueh'zala. Me be wantin' ta return da favor. We be friends, after all... riiiight?\n\nDat nasty loa be at me mercy now. Him been mutterin' about some tings he stole from ya Winter Queen. \n\nCome along ta me Necropolis. Ya can see what Ol' Bwonsamdi be talkin' about for yaself.\n\nYa gonna come back with someting nice for her majesty... reeeeeal nice.", objectives = "" }
WordHunterWoW_QuestEN[59739] = { title = "The Problem with Containing a Death Loa", description = "Me know Mueh'zala still be hidin' someting. Ol' Bwonsamdi gonna find out what dat be.\n\nBut dis old loa's presence be drawin' all da undead in Nazmir ta me doorstep!\n\nMe be needin' some time ta get Mueh'zala talkin'. \n\nDere be a troll, Zel'han, leadin' da undead. Kill him and show Mueh'zala him broken armor.\n\nDat should end any hope he be havin' of escapin'.", objectives = "" }
WordHunterWoW_QuestEN[59740] = { title = "Repair and Restore", description = "You've already attuned several mirrors without incident. I do believe it's time you try your hand at repairing them instead.\n\nIt's quite easy once you've found the fragments, but there are a few things of note to keep in mind. \n\nRepaired mirrors are fragile and unpredictable. They often break with a single use, and it's never a guarantee that using one will translocate you somewhere safe. \n\nHere's a few shards to get you started. \n\nRestore the mirror to working order and see where it leads.", objectives = "" }
WordHunterWoW_QuestEN[59741] = { title = "Dark Mojo for a Dark Loa", description = "How many times must de Necropolis come under attack? I suppose no one ever said worshipping Bwonsamdi would be easy...\n\nBwonsamdi seeks to force Mueh'zala into revealing his secrets, and I must do my part to help.\n\nDe undead swarming de Necropolis are animated by Mueh'zala's dark mojo. \n\nBwonsamdi needs some of dat mojo to finish his ritual. Strike down de undead and claim it.", objectives = "" }
WordHunterWoW_QuestEN[59742] = { title = "Delaying the Other Side", description = "Many of Bwonsamdi's worshippers did not make it inside when de undead began swarming de Necropolis.\n\nWe need a few more of dem to complete Bwonsamdi's ritual to uncover Mueh'zala's plans.\n\nTake dis powder and throw it on de worshippers who are stuck outside. It should dispel de dark magic dat afflicts dem.\n\nAs for de ones who are already dead... dey will serve Bwonsamdi beyond de grave. Dat is all we could ever ask for.", objectives = "" }
WordHunterWoW_QuestEN[59747] = { title = "A Lost Soul", description = "Many of us struggled to free ourselves when Gharmal imprisoned our souls here, but none more than Bacilia.\n\nShe was a great champion, but the confinement drove her mad and darkness consumed her soul. Though we tried to reason with her over the course of eons, it is clear that there is no coming back for her.\n\nPlease end her misery.", objectives = "" }
WordHunterWoW_QuestEN[59748] = { title = "No Peace In Death", description = "{name}. I have a favor to ask, if I may.\n\nThis realm... The sense of honor and purpose that guides its denizens calls to me. \n\nMy life was defined by such values. Maldraxxus, for a time, shared them with me... But I returned from the Maw to a land rife with treachery.\n\nI'd like to speak with the Paragon about Bastion.", objectives = "" }
WordHunterWoW_QuestEN[59749] = { title = "One Little Whisper", description = "Here be da deal, {name}. To get  Mueh'zala talkin', we gotta feed him a teeny bit a da life essence of everybody in dis room.\n\nWhy ya be lookin' at me like dat? When has ol' Bwonsamdi ever let ya down?\n\nMe gonna use da mojo ya got to pull da truth outta him while he be feedin'.\n\nOh, uh, just two more tings. First, I need ya to be ringin' an invitation to a special... friend.\n\nDen I be giving ya more of me mojo powder. Use it during da ritual if any o' me followers be gettin' too weak.", objectives = "" }
WordHunterWoW_QuestEN[59750] = { title = "How to Get a Head", description = "An eager rookie who wants to be champion of the arena? People love a story like yours, but the first step is to get you noticed. \n\nHere's the plan. Marcel Mullby needs bloodtusk skulls, but it takes a real fighter to get those!\n\nYou go kill some bloodtusks, use my knife to collect their heads, and deliver them to Mullby. That should get you recognition.", objectives = "" }
WordHunterWoW_QuestEN[59751] = { title = "Through the Shattered Sky", description = "When Sylvanas shattered the Helm of Domination, she was touched by the power it released.\n\nI can sense the echoes of that power, and I know where she has gone.\n\nIf you wish to rescue your leaders, the shattered helm can open a path. It cannot bring you back, however. That you must do on your own.\n\nThe risk is great, {name}, but there is no other way. We will begin the ritual at once.", objectives = "" }
WordHunterWoW_QuestEN[59752] = { title = "A Fractured Blade", description = "The chaotic energies of this place have scattered the Ebon Blade. \n\nI don't think Azeroth's blessings will reach you here, {class}. We will need allies if we are to survive this place.\n\nWe should find them quickly, before they are overcome.", objectives = "" }
WordHunterWoW_QuestEN[59753] = { title = "Ruiner's End", description = "One of the... larger fiends... has several of our knights engaged...\n\nHurry to their aid... lest we lose more of our dwindling forces.\n\nGo... it is too late for me...", objectives = "" }
WordHunterWoW_QuestEN[59754] = { title = "On Blackened Wings", description = "It's a relief to see friendly faces again. But we have little time for pleasantries.\n\nThrall is wounded, and we are being hunted by the denizens of this realm. We must seek shelter at once.\n\nCome, I believe I know of a place.", objectives = "" }
WordHunterWoW_QuestEN[59755] = { title = "A Flight from Darkness", description = "There's a cave not far from here. If we hurry, we can seek refuge.\n\nThose fiends will give chase if they spot us. Be prepared for a fight!", objectives = "" }
WordHunterWoW_QuestEN[59756] = { title = "A Moment's Respite", description = "Anduin insisted that our allies would come for us. I confess I had begun to doubt him.\n\nI'm sure you have many questions. I'll do what I can to provide answers, but I'm afraid even after... \n\nWhat has it been... weeks? Longer? Time loses all meaning in a place of such darkness.\n\nForgive me. Let me tell you what little I can.", objectives = "" }
WordHunterWoW_QuestEN[59757] = { title = "Field Seance", description = "If these souls have information we need, we will take it from them.\n\nEven after being shattered by the Banshee, the helm fragment given to you by Bolvar holds the power of Domination. With it, we should be able to take control of the spirits long enough to find out what they know.\n\nThey will need to be sufficiently weakened before we can break them. I'm confident you're more than capable of that task.", objectives = "" }
WordHunterWoW_QuestEN[59758] = { title = "Speaking to the Dead", description = "Look over to the ridge. There lies our quarry!\n\nNo telling how many souls are writhing together within that amalgam. With any luck, one of them might be coherent enough to give us answers.", objectives = "" }
WordHunterWoW_QuestEN[59759] = { title = "The Lion's Cage", description = "Anduin is being kept in a place the shades call the Tremaculum. It's not far, but the way is perilous.\n\nI have tried more than once to free him from his captors, but the forces holding him are too great for me to handle alone.\n\nI'm counting on your presence to tip the scales.", objectives = "" }
WordHunterWoW_QuestEN[59760] = { title = "The Afflictor's Key", description = "Sylvanas thinks us broken. She believes she has already won.\n\nWe will show her how mistaken she is.\n\nFirst, I will need your help. The bonds that hold me are impossibly strong. We will need the key to free me of them.\n\nMy... imprisonment here has been overseen by a creature they call the Afflictor. The key is likely in its possession.", objectives = "" }
WordHunterWoW_QuestEN[59761] = { title = "An Undeserved Fate", description = "I have seen many souls brought here during my detention. The Jailer seems to want to break them, to twist them into his service... or worse.\n\nNo soul deserves such a fate, {name}.\n\nThe Mawsworn here hold the keys to their chains. Free as many as you can and we'll get them away from here.", objectives = "" }
WordHunterWoW_QuestEN[59762] = { title = "By and Down the River", description = "Our next step is clear. We must travel to Zovaal's Cauldron--a frightful place I've heard spoken of in fanatical whispers. It's a forge of sorts that lies across the River of Souls.\n\nI have only been there a handful of times, but I have seen Baine held captive by the soldiers there. If fortune favors us, he'll still be nearby.\n\nOnce he's safe, we can see about finding this waystone the shade spoke of.", objectives = "" }
WordHunterWoW_QuestEN[59765] = { title = "Wounds Beyond Flesh", description = "Even as Baine's flesh mends, his spirit draws closer to death. I have seen dark magic like this before... among the Shadowmoon clan.\n\nThe Jailer's minions must have inflicted a similar malady upon Baine. \n\nThe only cure for the Shadowmoon's curse was to find the object they used to poison the spirit and shatter it.\n\nThe sorcerers of this realm wield ornamental daggers. That might be what we're looking for.\n\nWe must find the one that they used on Baine--quickly!", objectives = "" }
WordHunterWoW_QuestEN[59766] = { title = "A Good Axe", description = "I was a damned fool for throwing my axe at that sea hag. We can't afford to lose focus.\n\nThe battle ahead won't be easy. I'll need another weapon to help us fight to the waystone.\n\nLooks like these soldiers have plenty of armaments. Let's keep an eye out for one I can use.", objectives = "" }
WordHunterWoW_QuestEN[59767] = { title = "The Path to Salvation", description = "We must move quickly if we wish to find the waystone. The soul mentioned it overlooks the Cauldron, which would put it somewhere upon the ridge on the other side.\n\nUnfortunately, this area is swarming with enemy forces. We'd best avoid engaging them, lest we draw the Jailer's attention.\n\nI can shield us from sight, but we all have to stay together.", objectives = "" }
WordHunterWoW_QuestEN[59770] = { title = "Stand as One", description = "<Anduin examines the obelisk intently.>\n\nI've never seen markings like these before. I've studied titan artifacts, but this appears to be made by a different hand. \n\nHmm. It doesn't respond to me. I think Jaina's right. The waystone is reacting to your presence.\n\nPerhaps you'll have better luck activating it.\n\nStay on your guard. The Jailer's forces paid this no mind when it was dormant, but there's no telling what they'll do if that changes.", objectives = "" }
WordHunterWoW_QuestEN[59772] = { title = "Research Ruination", description = "The Cult of the Damned continue their work within the halls of Aldur'thar. \n\nInfiltrate their chambers and destroy their research. It may not stop them, but it will buy us valuable time.", objectives = "" }
WordHunterWoW_QuestEN[59773] = { title = "Seek the Ascended", description = "When you arrive in Bastion, seek out one of the kyrian. Explain that you require an audience with the Archon. Like the Arbiter, she is one of the Eternal Ones who rule over the Shadowlands.\n\nIf anyone can guide you to the truth, it is the Archon. Perhaps she will even know a way to end this anima drought.\n\nOnce you find the answers you seek, you are welcome to return to Oribos.\n\nPurpose guide your path, mortal.", objectives = "" }
WordHunterWoW_QuestEN[59774] = { title = "Welcome to Eternity", description = "Forgive my reaction. You see, the way from Oribos has been closed for quite some time. We did not know if it would ever open again.\n\nI welcome you, noble soul, to Bastion. Your deeds in life have earned you a most glorious fate! You are to become a kyrian, a winged bearer of the dead.\n\nMy name is Kleia. It would be an honor to introduce you to our beautiful realm. There is much you must learn before your journey can begin.\n\nGather yourself. When you are ready, we will venture on.", objectives = "" }
WordHunterWoW_QuestEN[59776] = { title = "From the Mouths of Madness", description = "I cannot express my gratitude enough for your help, champion. \n\nWe mustn't linger, however. The Jailer's forces will soon be alerted to the disturbance here.\n\nLet us leave this place at once!", objectives = "" }
WordHunterWoW_QuestEN[59781] = { title = "The Last Guy", description = "You're not the first newcomer wanting to become famous. There've been a lot like you around! \n\nThe last few wanted to prove themselves by killing a giant bloodtusk... none of them ever returned! You want to get recognition?\n\nGo find all those missing newcomers and kill the bloodtusk yourself.", objectives = "" }
WordHunterWoW_QuestEN[59782] = { title = "The Deathspeaker's Devout", description = "Though Deathspeaker Kharos has long since been slain, the cultists in the nearby mountains continue his nefarious work.\n\nClearly emboldened by the Scourge's resurgence and the rift in the sky, they once again kidnap our crusaders and perform their abhorrent alchemical experiments.\n\nGo forth and purge those fanatics from their camp.", objectives = "" }
WordHunterWoW_QuestEN[59783] = { title = "Cultist Captors", description = "Those damned cultists are relentless!\n\nThey caught us off guard and managed to drag a few of our crusaders back to their camp.\n\nLight only knows what they're doing to them up there...\n\nWord is you're quite capable of holding your own. Our numbers are stretched thin enough as it is... if you could rescue the captives, we'd be in your debt.\n\nYou can find the cultists lurking up in their mountain camp.", objectives = "" }
WordHunterWoW_QuestEN[59800] = { title = "Team Spirit", description = "Even if we're competing against each other, we're all Maldraxxi. That means we cheer on everyone, regardless of which side they're on.\n\nEnter the arena and douse the challengers with the contents of this flask. It may give them the edge they need to survive combat!", objectives = "" }
WordHunterWoW_QuestEN[59801] = { title = "Take the Power", description = "Wait! Before you enter, I would ask something of you.\n\nWhile we have not had a wildseed in some time, we did keep stores of anima. It served us well in staving off the gorm.\n\nWhatever has happened to my village, I do not want this power to remain in their hands. It will better serve Ardenweald in other groves.\n\nKeep an eye out for any anima within the village. We will put it to better use elsewhere.", objectives = "" }
WordHunterWoW_QuestEN[59802] = { title = "The Crumbling Village", description = "This journal belonged to Lewor, the leader of our grove. It says he found something to use against the gorm, but what if it caused all this?\n\nThere is only one way to be sure. Come with me to the village. Or what remains of it.", objectives = "" }
WordHunterWoW_QuestEN[59805] = { title = "Maw Manifested", description = "Ya heard it from Mueh'zala himself... tanks to ol' Bwonsamdi. Dere be an ancient spirit trapped in da Maw. Me bettin' da Winter Queen gonna want it back.\n\nGood ting ya been goin' down dere yaself, hm? Should be nice an' easy for ya.\n\nMe gonna clean up da rest of da undead here. Meet ol' Bwonsamdi in Ardenweald when ya get back.", objectives = "" }
WordHunterWoW_QuestEN[59809] = { title = "On De Other Side", description = "Ay dere, {name}... It be your ol' friend, Bwonsamdi!\n\nI hear ya be workin' for da Winter Queen. Seems ya be makin' quite a name for yaself!\n\nArdenweald be in grave danger, but da Queen... well, she be too proud to deal with ol' Bwonsamdi.\n\nYa wanna save da forest, mon? Come visit me on da Other Side.\n\nI gonna be waitin' for ya...", objectives = "" }
WordHunterWoW_QuestEN[59810] = { title = "[DNT]Just A Small Request", description = "Morbi eget nibh eu nisl sollicitudin ultricies. Aliquam iaculis est quis aliquet auctor.\n\nAenean lobortis finibus justo eget vehicula. Fusce ut magna dolor. Donec vehicula a erat finibus volutpat. Nulla auctor sagittis vulputate. Vestibulum laoreet neque ut enim malesuada posuere.\n\nAenean sed tortor quam. In egestas non arcu vitae consequat. Cras augue ipsum, imperdiet nec dui id, ullamcorper ultrices nisi. Praesent accumsan leo sed accumsan lobortis.", objectives = "" }
WordHunterWoW_QuestEN[59811] = { title = "Taking Inventory", description = "Dark forces be at work, {class}. \n\nArdenweald be where loa go ta be reborn after dey die on Azeroth. But some of da loa who be sleepin' in Ardenweald have gone missin'!\n\nGotta be someone powerful behind it, takin' dem from right under da Winter Queen...\n\nOl' Bwonsamdi can't be havin' loa vanishin' from Ardenweald. Dat could be me someday! No, no... we gonna put a stop to dis!\n\nGo back ta Ardenweald and search for da missin' loa.", objectives = "" }
WordHunterWoW_QuestEN[59812] = { title = "Following the Trail", description = "I got a bad feelin' about dis, mon.\n\nWildseeds don't just go missing... especially da kind wit' powerful loa in dem! Even da bad eggs like Hakkar and Dambala be protected by da Winter Queen. Someone... or someting... must be stealin' dem!\n\nBut why? Dey weren't even ready ta be reborn...\n\nSearch da area and see if ya can pick up da trail. Missing loa be bad for business... and Bwonsamdi be in enough trouble wit' da boss already!", objectives = "" }
WordHunterWoW_QuestEN[59813] = { title = "Minions of Mueh'zala", description = "Dese all be followers of Mueh'zala! Me shoulda known he be da one behind it all.\n\nMueh'zala be da loa of death from long ago. It be him who raised up Ol' Bwonsamdi, him who made me a loa.\n\nDat be before his worshippers started turnin' away from him. He always been a greedy one... but dis...\n\nMueh'zala be goin' too far dis time! We gotta stop him, or he gonna take all da loa in Ardenweald!", objectives = "" }
WordHunterWoW_QuestEN[59814] = { title = "[DNT] Words of Mueh'zala", description = "", objectives = "" }
WordHunterWoW_QuestEN[59815] = { title = "Stolen Loa", description = "Hakkar and Dambala be somewhere in da grove.\n\nWe need ta hurry and find out what Mueh'zala be up to. Dem two loa been mighty powerful on Azeroth... powerful and evil. Who knows what Mueh'zala be plannin' for dem!\n\nSearch da Spirit Glen. Find da missing loa and see what Mueh'zala be meanin' ta do!", objectives = "" }
WordHunterWoW_QuestEN[59816] = { title = "[DNT] Bwonsamdi's Plan", description = "", objectives = "" }
WordHunterWoW_QuestEN[59817] = { title = "Winter Be Comin'", description = "Da boss be puttin' together an army of terrible loa. Hakkar and Dambala may only be da beginnin'. How da boss get so strong? I not be seein' him use power like dis before...\n\nDa Winter Queen not be fond of ol' Bwonsamdi, but we gonna need her help to stop Mueh'zala.\n\nYa be friendly wit' da Queen, no? If she be willin' to rally her forces, we might be able to stop Mueh'zala before it be too late.\n\nHead to da Heart of da Forest and speak wit' da Queen. She be our only hope now.", objectives = "" }
WordHunterWoW_QuestEN[59818] = { title = "Gathering The Hunt", description = "Loath as I am to aid Bwonsamdi, Mueh'zala must be made to answer for his crimes.\n\nWe will eradicate his worshippers and drive them from the forest before they cause more harm.\n\nRally the groves and muster the Wild Hunt. Ardenweald has need of its protectors.\n\nMake haste, huntsman.", objectives = "" }
WordHunterWoW_QuestEN[59819] = { title = "Cleansing the Forest", description = "The Winter Queen has commanded us to drive Mueh'zala's forces out of Ardenweald.\n\nThis won't be an easy battle. The death loa's army is strong, and several of our hunters have been gravely injured.\n\nCan we count on you to turn the tide in our favor, {name}?\n\nAid our fallen allies and vanquish Mueh'zala's minions!", objectives = "" }
WordHunterWoW_QuestEN[59821] = { title = "Report to the Queen", description = "Mueh'zala's forces are routed, and it's only a matter of time before the Wild Hunt completely purges them from Ardenweald.\n\nBut something tells me that the struggle between Bwonsamdi and Mueh'zala is far from over. That creepy little mask has gone silent...\n\nYou should hurry back to the Heart of the Forest and report to the Winter Queen. She will decide what we do next.", objectives = "" }
WordHunterWoW_QuestEN[59822] = { title = "Tracking a Wild God", description = "Dis be a dark place, {name}. We gotta track down da spirit who be trapped here.\n\nMe tink me can pick up its trail... but dat be all dis ol' shadow hunter can do.\n\nIf me be tryin' ta fight wit' ya, da threads dat be tyin' me ta Azeroth might break. Den I gonna be stuck here, too.\n\nC'mon. We best be moving.", objectives = "" }
WordHunterWoW_QuestEN[59824] = { title = "Loa Rescue", description = "We be here for Ashamane, but me sensin' loa bein' tortured up ahead. Three of dem, if me be right.\n\nMe don't know who dey be, but dey don't belong in da Maw.\n\nWe need ta be bringin' dem back ta Ardenweald, too!", objectives = "" }
WordHunterWoW_QuestEN[59826] = { title = "Bet On Yourself", description = "Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. \n\nThe entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it.\n\nI've brought in a special challenger just to prove the point. Face Mistress Dyrax in the Theater of Pain and prove us wrong... or prove us right.\n\nWe will be betting, so don't disappoint.", objectives = "" }
WordHunterWoW_QuestEN[59827] = { title = "Bet On Yourself", description = "Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. \n\nThe entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it.\n\nI've brought in a special challenger just to prove the point. Face Devmorta in the Theater of Pain and prove us wrong... or prove us right.\n\nWe will be betting, so don't disappoint.", objectives = "" }
WordHunterWoW_QuestEN[59828] = { title = "Bet On Yourself", description = "Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. \n\nThe entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it.\n\nI've brought in a special challenger just to prove the point. Face Ti'or in the Theater of Pain and prove us wrong... or prove us right.\n\nWe will be betting, so don't disappoint.", objectives = "" }
WordHunterWoW_QuestEN[59837] = { title = "Working for the Living", description = "I see you are wondering where we acquire all of the challengers we supply to this arena.\n\nWe scour countless realms in search of opponents to provide the Maldraxxi with firsthand combat experience. \n\nCurrently, I am in the process of procuring a new combatant--and with it, a lucrative betting opportunity. \n\nWould you make use of our portal and assist Zo'umlo in capturing Khogov the Expunger? You will be appropriately compensated, of course.", objectives = "" }
WordHunterWoW_QuestEN[59838] = { title = "Scourge War Machines", description = "The Scourge's war machines make it exceedingly difficult for us to gain ground. They must be our top priority.\n\nThough they are well protected, we must destroy them if we are to clear a path for our ground forces and grant them an opportunity to strike.\n\nPlant these charges underneath the war machines and then clear the area.", objectives = "" }
WordHunterWoW_QuestEN[59839] = { title = "WARNING: This is Only a Test!", description = "Where some see a problem, I see an opportunity. What this Scourge fiasco calls for is a creative solution!\n\nBehold--my \"secret weapon\"!\n\nControlled by none other than my Carefully Constructed Control Device, or C.C.C.D. for short!\n\nHmm, that name might need a little work.\n\nYou're the first to see it, so that means you'll be the first to test it. But don't worry, I'm pretty sure it's safe.\n\nGood luck!", objectives = "" }
WordHunterWoW_QuestEN[59840] = { title = "Divine Gratitude", description = "Many thanks for restoring my power and vigor.\n\nMy path will now lead me back to my people, but it is only right that you are rewarded for your efforts.", objectives = "" }
WordHunterWoW_QuestEN[59846] = { title = "Finders-Keepers, Sinners-Weepers", description = "Oh hello, mortal. You have a real knack for arriving at the most opportune times. I wonder what Taskmaster Matyas wants with you. Curious.\n\nAs for me, again Matyas has used my sinstone against me. I was already enraged that he caged me and I assure you that this latest attack will not go unanswered. Yet, while he has my sinstone I am unable to act against him directly. So we must remedy that.\n\nYou question the laborers and I will read this journal while I regain my strength.", objectives = "" }
WordHunterWoW_QuestEN[59847] = { title = "Defending the Rampart", description = "The Scourge are assaulting our outpost! We must defend it at all costs!\n\nSlay as many of the fiends as you can!", objectives = "" }
WordHunterWoW_QuestEN[59851] = { title = "Frozen Solid", description = "The breath of a frost wyrm can freeze even its largest foes in an instant. Our forces, unfortunately, have experienced this firsthand.\n\nTheir advance toward the citadel has come to a halt. I fear we may lose our foothold unless we act quickly.\n\nTake this potion and use it to free our forces from their frigid bonds. Light be with you.", objectives = "" }
WordHunterWoW_QuestEN[59856] = { title = "Rezan, Loa of Kings", description = "Rezan be a powerful loa, one of great importance ta da Zandalari.\n\nWe need ta rescue him... but dis creature be projectin' a barrier of death. Notin' be gettin' in.\n\nUnless... I be usin' me own anima ta shield ya from its magic.\n\nYa gotta act fast and kill da monster dat be drainin' Rezan. Me anima not gonna last forever.\n\nSay da word when ya ready ta go.", objectives = "" }
WordHunterWoW_QuestEN[59862] = { title = "A Savior for Lost Souls", description = "The forest sighs in greeting, Maw Walker.\n\nYour arrival was written in the stars, and awaited by the boughs. Now our work begins. \n\nLet us proceed.\n\nFollow this path into the grove.\n\nThese are but the first steps on our journey together.", objectives = "" }
WordHunterWoW_QuestEN[59863] = { title = "Combat Nullifier 07-X", description = "While everyone is busy fending off our enemies with swords and magic, how about we try something different.\n\nBehold, my latest invention--the Combat Nullifier 07-X!\n\nWith this device, no enemy is truly your enemy any longer!\n\nNow, I haven't quite worked out the exact energy modulator calculations, but I am certain it works. Mostly.\n\nFor now, we'll need to \"borrow\" some energy from our enemies in order to operate it.\n\nGo ahead. Charge it up and give it a whirl!", objectives = "" }
WordHunterWoW_QuestEN[59865] = { title = "Glimmerflight", description = "This so exciting!\n\nCome, another test is in order. I can hardly wait!", objectives = "" }
WordHunterWoW_QuestEN[59866] = { title = "Parting Ways", description = "Me don't know what fate be comin' for ol' Vol'jin... but it be waitin' for me in Ardenweald.\n\nAshamane, Hir'eek, Shadra... dey belong dere, too.\n\nWe best be gettin' outta here. Me had enough of da Maw for an eternity.", objectives = "" }
WordHunterWoW_QuestEN[59867] = { title = "WANTED: Appraiser Vix", description = "For failure to pay debts upon lost wagers, theft of arena property, and for the slaughter of an authorized debt collector. All necessary violence is hereby sanctioned when confronting Vix.\n\nSpecial warning to be on the lookout for numerous associates who have demonstrated a violent attitude toward outsiders.\n\nElimination of this felon is of the highest priority.", objectives = "" }
WordHunterWoW_QuestEN[59868] = { title = "Offer of Freedom", description = "Just as I was, some of the Briarbane venthyr you encounter will have been compelled to serve Matyas. They likely will not want to fight you, but will have no choice. Once they are injured, they may be willing to pause to see if one of the sinstones you recovered earlier is theirs.\n\nFree those you can. The use of a sinstone to compel others isn't fair.", objectives = "" }
WordHunterWoW_QuestEN[59870] = { title = "[OLD NOT USED]", description = "", objectives = "" }
WordHunterWoW_QuestEN[59871] = { title = "Catalyze This", description = "The grove grows in power, and so shall the spirits it shelters.\n\nYou have nurtured a spirit to rebirth on your own. Now you must learn to make use of catalysts.\n\nWhen planted near a wildseed, catalysts grant the slumbering spirit strength beyond what it knew in life. Strength that it retains when reborn.\n\nCatalysts are special and rare, though I have one here for you to use. Others can be found across the Shadowlands.\n\nFor now, plant the catalyst and witness the potential it holds.", objectives = "" }
WordHunterWoW_QuestEN[59872] = { title = "How to Save a God", description = "Many mortal souls suffer within the Maw. But so too do many spirits of Nature.\n\nAnima alone cannot heal wounds inflicted by the Jailer. Spirits plucked from his grasp must be planted anew and tended with care.\n\nThese wildseeds are unlike any other. This grove, unlike any other. Within them lies dormant hope, a chance for even the weakest spirit to be reborn.\n\nOne such as this. Lay this spirit to rest within a wildseed. Let its rebirth begin.", objectives = "" }
WordHunterWoW_QuestEN[59873] = { title = "Greeting a God", description = "Soon, the moment of the spirit's rebirth will be nigh. A fate all but extinguished by the Maw, rekindled by grove and caretaker.\n\nTime will be the spirit's salve. Once enough of it has passed, lay your hands upon the wildseed and awaken them.", objectives = "" }
WordHunterWoW_QuestEN[59874] = { title = "The Maw", description = "{name}, your arrival has set Maldraxxus ablaze. If you have any honor, you will do as I ask.\n\nI believe I know where our answers may lie. The baron preceding Draka was lost to the Maw. It is said you have entered that dark abyss... and returned.\n\nIf the baron survived, he may know our next course of action.\n\nYou came here from Oribos. Return there, and see if you can find a way back to the Maw.", objectives = "" }
WordHunterWoW_QuestEN[59876] = { title = "Field Reports", description = "The Scourge can strike anytime, anywhere.\n\nTo counter their unpredictability, the Argent Crusade has secured key locations along the southern road heading east. However, I have yet to receive any reports from our scouts in the field.\n\nWith the erratic nature of these attacks, I fear the worst.\n\nTravel the road and take stock of our outposts. I'll be expecting a full report when you return.\n\nLight be with you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[59877] = { title = "A Message from Icecrown", description = "We received word from our forces in Northrend. Justicar Trueheart requests our immediate assistance.\n\nAs you are an experienced {class}, I ask that you answer the call.\n\nThe urgency of this summons cannot be ignored, even if it means braving the terrors of Icecrown itself.\n\nI know you fear for the safety of everyone here. I will continue to coordinate our efforts and call in additional reinforcements.\n\nLight be with you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[59878] = { title = "Too Many Whelps", description = "We cannot hope to hold this ground if frostwyrms strafe the skies above us.\n\nCultists have been raising whelps from the dead nearby. The more of them we eliminate, the fewer monstrosities to breath deadly ice upon our forces.\n\nPut an end to their efforts.", objectives = "" }
WordHunterWoW_QuestEN[59879] = { title = "This Thing of Ours", description = "Au'narim is the top broker here. She keeps this place supplied with exotic creatures for us to fight in the arena. \n\nShe's noticed your efforts and wants to meet you!\n\nThis is important. A broker's backing could lead to an invitation to compete!", objectives = "" }
WordHunterWoW_QuestEN[59882] = { title = "Sure Bet", description = "You appear to have great profit potential.\n\nThere are many interested parties willing to bet upon your performance in the Theater of Pain.\n\nGo now, Louison will arrange your appearance.", objectives = "" }
WordHunterWoW_QuestEN[59894] = { title = "The Golden Dawn", description = "The machinations of war commence. Gharmal's crimes are now evident to all of the Shadowlands.\n\nBastion demands vengeance, and we shall share it with them. Only our combined forces will defeat the Constructs once and for all.\n\nMeet Draka at the overlook. Your presence there will help solidify an agreement.", objectives = "" }
WordHunterWoW_QuestEN[59897] = { title = "Seeking the Baron", description = "Take this amulet. One like it is carried by each of the Four Horsemen.\n\nThe amulets are imbued with a power that links them to one another. That connection should help you locate Darion Mograine.\n\nNo doubt Darion has witnessed countless horrors in the Maw. Perhaps he has caught sight of the missing baron.\n\nLet us hope he can lead you to our Azerothian allies as well.", objectives = "" }
WordHunterWoW_QuestEN[59903] = { title = "Split Blob Test", description = "", objectives = "" }
WordHunterWoW_QuestEN[59907] = { title = "Mawsworn Menace", description = "Our knights are strong, but they don't stand much chance scattered against such an opponent.\n\nWe need to thin the ranks of our foe. The Ebon Blade won't do us any good if they are cut down.", objectives = "" }
WordHunterWoW_QuestEN[59910] = { title = "Fight and Flight", description = "Mograine and Emeni will lead the assault on the western gate. \n\nYou and Xandria will advance from the east. Secure the area and slay all who oppose you. \n\nOnce we have them surrounded, we can strike the final blow against Gharmal.", objectives = "" }
WordHunterWoW_QuestEN[59912] = { title = "[OLD NOT USED]", description = "Now that you have seen the basics it is time for us to expand your understanding.\n\nI hope your little mind will be able to hold this information.\n\nYou seem capable so far, but you are so small. I'll be intrigued to see if you are bigger on the inside.\n\nFirst. You need to learn more about the catalysts. There should be a small number growing in this very grove. Fetch me some and I can explain what they are.", objectives = "" }
WordHunterWoW_QuestEN[59914] = { title = "Fear to Tread", description = "It appears we've escaped our enemies' notice for the moment. We should take the opportunity to scout the nearby area for signs of our allies.\n\nWe will draw less attention alone. The Ebon Blade will hold back, awaiting my signal.\n\nCome, let us see what awaits us in this hellscape.", objectives = "" }
WordHunterWoW_QuestEN[59915] = { title = "Soul in Hand", description = "My instincts were correct. Whatever dark magic binds these souls together also keeps them more or less coherent.\n\nIt will take time, but we will find out what this thing knows. My interrogation will require use of the helm, but rest assured I will return it to your care.\n\nLet's bring our prize to the Lord Admiral.", objectives = "" }
WordHunterWoW_QuestEN[59916] = { title = "The Butchers of Bastion", description = "Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these monstrosities?!\n\nNo! The butchers of Bastion made clear their hearts that day!\n\nThey deserve only the eternal darkness that awaits them. Ensure that they meet it!", objectives = "" }
WordHunterWoW_QuestEN[59917] = { title = "Kill Them, Of Course", description = "These mindless monstrosities hail from the farthest reaches of the Shadowlands. The anima drought has fueled their relentless hunger, driving them to seek new sources.\n\nTheir presence here is inconvenient, to put it mildly.\n\nThey tear at the land searching for any anima they can find. We must thin their numbers and buy time to safeguard the knowledge locked within the Sepulcher.\n\nExactly the sort of work you're accustomed to, yes?", objectives = "" }
WordHunterWoW_QuestEN[59919] = { title = "An Earned Bond", description = "There is one more thing you should do, Maw Walker.\n\nIn rebuilding the Crest of Ascension you have earned more than just the trust of your fellow kyrian. It would seem our Forgelite Prime, Mikanikos, has rather enjoyed your time together and would like to soulbind with you.\n\nGiven his predilection towards, well, himself, I am as surprised as you are. You must have truly impressed him.", objectives = "" }
WordHunterWoW_QuestEN[59920] = { title = "Light the Forge, Forgelite", description = "I think we have the materials I will need to light the forge, at long last.\n\nI am afraid the place is in a state of disrepair. Between failed attempts at working without anima and simple neglect, I cannot hope to work the forge as it currently stands.\n\nI would very much appreciate your help to get the place in order while I coax the forge to life once more.", objectives = "" }
WordHunterWoW_QuestEN[59921] = { title = "All I Ever Will Be", description = "This is the site of an ancient battle won by the previous Paragon of Courage. She sacrificed herself to serve the Shadowlands. I only hope my own end will prove as exemplary.\n\nMany of my disciples meditate upon the scrolls here. With them, we remember the foundation of our courage.\n\nAccompany Alexandros as he reflects on his shrines. Aid him in understanding where the source of his courage lies.\n\nHe will learn that this afterlife is not the one suited for him.", objectives = "" }
WordHunterWoW_QuestEN[59922] = { title = "Do Not Forget", description = "The Arbiter's judgment was, as always, infallible.\n\nThough Alexandros's devotion to the Light is undeniable, it is the memory of his loved ones that truly fuels his strength. He was meant for Maldraxxus, not Bastion.\n\nNonetheless, our reclamation of the temple stands. My vengeance is not yet complete, but now I know that some of the Maldraxxi can still be trusted.\n\nGo now. Return to your leader with news of our victory today.\n\nAnd tomorrow, we shall purge our foes once and for all.", objectives = "" }
WordHunterWoW_QuestEN[59925] = { title = "[OLD NOT USED]", description = "Let's see how much more we can push into that little brain of yours.", objectives = "" }
WordHunterWoW_QuestEN[59926] = { title = "Warming Up", description = "We're nearing the island where the Horde's last expedition was lost. \n\nYou need to be prepared for what's out there. Warm up on these combat dummies.", objectives = "" }
WordHunterWoW_QuestEN[59927] = { title = "Stand Your Ground", description = "Lok-tar! Nothing quite like a good fight in the rain. \n\nWe will spar together and take the measure of your strength!", objectives = "" }
WordHunterWoW_QuestEN[59928] = { title = "Brace for Impact", description = "Well fought, {name}. You bring strength and honor to the Horde!\n\nNow we just--wait...\n\nDo you hear that?", objectives = "" }
WordHunterWoW_QuestEN[59929] = { title = "Murloc Mania", description = "The shore is littered with shipwrecks. This must be where the lost expedition crashed.\n\nWe'll need more supplies to help the injured recover. The nearby murlocs stole most of what washed up.\n\nSlay those murlocs to get back what belongs to the Horde.", objectives = "" }
WordHunterWoW_QuestEN[59930] = { title = "Emergency First Aid", description = "We must treat our wounded before we can begin for the missing expedition.\n\nTake this first aid kit and tend to the survivors. I'll handle the others nearby.", objectives = "" }
WordHunterWoW_QuestEN[59931] = { title = "Finding the Lost Expedition", description = "Breka Grimaxe went north to look for survivors. Join her to see what she's found.\n\nI'm going to go up ahead to see if I can find anyone else. We'll meet again further within the island.", objectives = "" }
WordHunterWoW_QuestEN[59932] = { title = "Cooking Meat", description = "This is Won'sa, a shaman who was with the expedition.\n\nShe is dying of starvation. A death unfit for the Horde!\n\nSlay some of the nearby wildlife for their meat and cook it over the fire.\n\nWon'sa can tell us what happened to the missing expedition after she eats.", objectives = "" }
WordHunterWoW_QuestEN[59933] = { title = "Enhanced Combat Tactics", description = "Won'sa said the quilboar have kidnapped the missing expedition.\n\nThe quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs.\n\nI won't see you die by their hands. We're going to spar one last time.\n\nWhen we are done, you will cleave a path straight through the quilboar!", objectives = "" }
WordHunterWoW_QuestEN[59934] = { title = "Enhanced Combat Tactics", description = "Won'sa said the quilboar have kidnapped the missing expedition... including my daughter.\n\nThe quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs.\n\nI won't see you die by their hands. We're going to spar one last time.\n\nWhen we are done, you will cleave a path straight through the quilboar!", objectives = "" }
WordHunterWoW_QuestEN[59935] = { title = "Northbound", description = "Da quilboar kidnapped da rest of da expedition and took dem north.\n\nDey said dey gonna use da expedition for some sorta sacrifice! \n\nYa gotta head north as fast as ya can ta stop dem!", objectives = "" }
WordHunterWoW_QuestEN[59937] = { title = "Taming the Wilds", description = "A hunter like yourself needs a good pet by your side. Did you not bring one with you?\n\nHmm. I suppose I shall have to compensate for your lack of training.\n\nListen closely and learn quickly. I will teach you how to tame a beast and make it your pet.\n\nYou will need one if you are to fight the quilboar.", objectives = "" }
WordHunterWoW_QuestEN[59938] = { title = "Down with the Quilboar", description = "I have discovered that the quilboar are performing a shadow ritual on a survivor from the missing expedition.\n\nThe ritual is being performed by the tribe's leader, Geolord Grek'og. \n\nSlay Grek'og and save the survivor.\n\nShow this brute that the Horde is not to be trifled with.", objectives = "" }
WordHunterWoW_QuestEN[59939] = { title = "Forbidden Quilboar Shadow Magic", description = "Quilboar are savage and violent. I did not think they knew how to use shadow magic.\n\nObviously, we cannot allow them to continue their rituals. And certainly not on members of the Horde.\n\nSlay the quilboar in the den. They must learn the fatal error of their ways.", objectives = "" }
WordHunterWoW_QuestEN[59940] = { title = "The Choppy Booster Mk. 5", description = "You're in luck, 'cause I'm the ONE goblin who can help you find the rest of the expedition!\n\nFeast your eyes on this fancy device here. Stole it off a gnome, improved on it, and made it my own!\n\nI call it the Choppy Booster Mk. 5. Use it to find Shuja and the others.", objectives = "" }
WordHunterWoW_QuestEN[59941] = { title = "Re-sizing the Situation", description = "I call this gadget \"the Re-Sizer.\" It's what I used to unshrink the Choppy Booster Mk. 5.\n\nLook, I'm gonna be honest. I got, at best, a passing understandin' of how this thing works.\n\nThat means I'm gonna be pushing a lot of buttons to see what happens.\n\nI'm sure we'll figure out how to upsize one of these boars. Then we'll use it to trample those undead goons!\n\nYou hold the Re-Sizer while I fiddle with it. Then just press the button and, uh... hope for the best?", objectives = "" }
WordHunterWoW_QuestEN[59942] = { title = "The Re-Deather", description = "I got the perfect plan. You're gonna ride the Choppy Booster Mk. 5 and BLAST those walkin' cadavers from the sky!\n\nI hereby dub the Re-Sizer the \"Re-Deather.\" We're gonna show them where the undead belong!\n\nEr, except for OUR undead. They're totally fine.\n\nAnyway, hop on the Choppy Booster Mk. 5 and I'll pilot it.\n\nOnce we save Wrathion, we'll blast our way to all the other survivors!", objectives = "" }
WordHunterWoW_QuestEN[59943] = { title = "The Harpy Problem", description = "The ogres are planning to sacrifice the rest of the expedition to fuel this ritual to control Kalecgos, leader of the blue dragonflight.\n\nIt seems one of the survivors was taken to the hills north of here. Bo scouted ahead to investigate.\n\nCome, we'll see what he has found.", objectives = "" }
WordHunterWoW_QuestEN[59944] = { title = "The Rescue of Herbert Gloomburst", description = "The harpies plan to sacrifice the expedition's mage, a Forsaken by the name of Herbert Gloomburst.\n\nHerbert's ethics are... questionable, but he always strives to serve the Horde. We'll need his magic to stop the ogres.\n\nLet's move.", objectives = "" }
WordHunterWoW_QuestEN[59945] = { title = "Harpy Culling", description = "The harpies seem to be in league with the ogres. Many of them are gathering to attack our camp.\n\nWe must thin their numbers and thwart their attempts to eliminate us.\n\nPerhaps they will learn it is best to leave the Horde be.", objectives = "" }
WordHunterWoW_QuestEN[59946] = { title = "Purge the Totems", description = "The harpies have placed vile totems throughout the area to attain more power.\n\nWe must destroy those totems in order to debilitate our foes.\n\nTake this torch and burn any totems you see. It is wise to weaken one's enemy before the fight even begins.", objectives = "" }
WordHunterWoW_QuestEN[59947] = { title = "Message to Base", description = "Let us return to camp with Herbert in tow.\n\nWe're one step closer towards thwarting the ogres and their plans.", objectives = "" }
WordHunterWoW_QuestEN[59948] = { title = "Westward Bound", description = "Thrall wants us to search west of here for the site of the next ritual.\n\nWe could use your help. I've already died once. It's not an experience I'd care to repeat.", objectives = "" }
WordHunterWoW_QuestEN[59949] = { title = "Who Lurks in the Pit", description = "There's a whole lot of shadow energy coming from this pit. I'm guessing a ritual is being performed down there. And that means a sacrifice.\n\nDo you hear that? I've got the best hearing around, ever since I got this new ear sewn onto me.\n\nIt sounds like there are some more of our soldiers trapped down there. Probably all webbed up.\n\nWon'sa and I will... stay up here and help anyone who gets out.\n\nYou should jump in and rescue anyone who is left down there!", objectives = "" }
WordHunterWoW_QuestEN[59950] = { title = "Stocking Up on Supplies", description = "Provisioner Jin'hake managed to recover some other supplies from the shipwreck.\n\nTake a look at what he has before heading out.", objectives = "" }
WordHunterWoW_QuestEN[59951] = { title = "A Druid's Form", description = "Thank you for rescuing me, {name}. Allow me to aid you in your druidic studies.\n\nTo escape from the pit, I took on the form of a stag. I may know of a way you can learn to do the same.\n\nCome with me. There is an ancient druid stone nearby. Let us use it to commune with the wilds.", objectives = "" }
WordHunterWoW_QuestEN[59952] = { title = "A Hunter's Trap", description = "If you want to be called a true hunter, you'll need to learn the art of trapping.\n\nFortunately, I happen to be an expert in it.\n\nFirst, you will need to gather supplies from the surrounding area so you can fashion a proper freezing trap.\n\nHerbert can supply you with a mote of ice. Scavenge the area for other materials.\n\nYou will need the trap to handle another issue that has recently arisen.", objectives = "" }
WordHunterWoW_QuestEN[59953] = { title = "Hunting the Stalker", description = "Now that you have your trap, we can move onto the true problem at hand.\n\nA strange creature not native to this island has been stalking our camp.\n\nI think we should capture it and see how it can help us.\n\nSet the freezing trap within these ruins to lure it out. We'll see just what we are dealing with.", objectives = "" }
WordHunterWoW_QuestEN[59954] = { title = "A Mage's Knowledge", description = "You've got some good spells for a novice mage. There are a few things holding you back, though.\n\nFor instance, it's absolutely clear to me you don't know Polymorph.\n\nIf you did, you would've been using it on the harpies that were attacking us!\n\nLet's fix that. My spellbook has details on how to cast it... but my captors threw it into the nearby lake. \n\nGrab it for me, would you? Oh, and don't look through the book beforehand.\n\nYou will almost certainly regret it if you do.", objectives = "" }
WordHunterWoW_QuestEN[59955] = { title = "The Best Way to Use Sheep", description = "I can't send you off without making sure you can cast Polymorph correctly.\n\nWhy, if you messed it up you may transform someone into something completely different!\n\nI want to make sure I'm around to take notes if that happens.\n\nLet's see... ah, Throg will do nicely! I can spot a prime test subject from a mile away.\n\nShall we begin?", objectives = "" }
WordHunterWoW_QuestEN[59956] = { title = "A Monk's Focus", description = "You fought well against the harpies, but you'll need even more skill to best the challenges ahead.\n\nWe must meditate and focus if we are to gain more strength.\n\nCome. I know of a place we can go.", objectives = "" }
WordHunterWoW_QuestEN[59957] = { title = "One Last Spar", description = "Let's have a quick sparring session before returning to camp.\n\nI can sense new power rising from within you. I want to see it in action!", objectives = "" }
WordHunterWoW_QuestEN[59958] = { title = "A Paladin's Service", description = "While you were destroying that army of the undead, the ghost of a paladin approached me... and asked for you!\n\nThey floated over to the ruins nearby.\n\nYou should see what this ghost wants. I do not know much about the Light... but I know not to ignore a ghost.", objectives = "" }
WordHunterWoW_QuestEN[59959] = { title = "The Brand Holds the Key", description = "<Darion is unresponsive. The cage is locked, and doesn't appear easily broken.\n\nPerhaps the holder of the key is this \"Brand\" he mentioned.>", objectives = "" }
WordHunterWoW_QuestEN[59960] = { title = "A Cooling Trail", description = "<The amulet burns hot in your hand. The magic that runs through it tugs slightly at your grip.\n\nPerhaps the enchantment spoken of by Bolvar can now be used to find Mograine.>", objectives = "" }
WordHunterWoW_QuestEN[59961] = { title = "A Priest's End", description = "You're a trained priest, right {name}? I have a grim request for you.\n\nI passed by some injured members of the first expedition. I did what I could... but they were too far gone.\n\nCan you perform a ritual to lay them to rest? \n\nTheir spirits deserve to rest with honor.", objectives = "" }
WordHunterWoW_QuestEN[59962] = { title = "Hope Never Dies", description = "So, mortal, you are here looking for someone. Well it just so happens that, clever as I am, it's quite possible I know where they are.\n\nAllow me to propose a trade. That amulet you carry... it holds an interesting power.\n\nYou give me the amulet, and I will help you find this Maldraxxi baron.\n\nAnd then you will leave. I don't mean to be rude, but I really prefer to keep a low profile.\n\nAllow me to speed things along.", objectives = "" }
WordHunterWoW_QuestEN[59965] = { title = "Resurrecting the Recruits", description = "Ya gotta cast Resurrection on dese recruits ta be savin' dem.\n\nDa necrotic magic of dis place be tuggin' at deir souls.\n\nQuickly, now!", objectives = "" }
WordHunterWoW_QuestEN[59966] = { title = "Delving Deeper", description = "It's quite a thrill to have a mortal for a business partner! The amulet really is intriguing.\n\nWhat's that? Oh yes, that baron you're searching for...\n\nWell it so happens that I learned of a Maldraxxi warlord being held in the lower courtyard of Perdition Hold. As you might guess by the name, it's not the most charming of places.\n\nI would prefer to avoid the attention of the Jailer's forces. Fortunately, I have just the thing.\n\nGive the word, and I will conceal us from the Mawsworn.", objectives = "" }
WordHunterWoW_QuestEN[59967] = { title = "A Rogue's End", description = "Shuja mentioned a rogue from the first expedition. Goes by Drizza Sidestabber.\n\nDrizza was last seen heading northwest... towards a large bear's den.\n\nNone of us can sneak around like you. See if you can find Drizza and bring her back here.", objectives = "" }
WordHunterWoW_QuestEN[59968] = { title = "The Deadliest of Poisons", description = "You've got the poison. Now you gotta to take out that ogre. Goon's name is Gutgruk the Tough.\n\nHe usually patrols around the citadel. I betcha it's lookin' for your expedition right now!\n\nPoison your blades, then take that monster down. Show him he ain't so tough!", objectives = "" }
WordHunterWoW_QuestEN[59969] = { title = "A Shaman's Duty", description = "Greetings, young one. Your compatriots cannot see me. Only you, for you have been trained in the ways of a shaman.\n\nThe necrotic energies of this island have ensnared my pack. I need your aid to free them.\n\nGather veil blossoms from surrounding area. Burn them on the campfire and breath deep of their smoke.\n\nThen you will be able to see my packmates and release them from their bonds.", objectives = "" }
WordHunterWoW_QuestEN[59970] = { title = "A Warlock's Bargain", description = "While scouting the area, I saw an open portal near the bridge up the hill. That does not bode well for any of us.\n\nIt seemed like another warlock tried to seal the portal, but failed.\n\nI know you dabble in such... affairs. Perhaps you could put your knowledge to good use and close that portal.", objectives = "" }
WordHunterWoW_QuestEN[59971] = { title = "A Warrior's End", description = "Hail, {name}! You've grown stronger since we sparred on the boat. You may one day become a warrior of great renown!\n\nSpeaking of which...\n\nI encountered a ghost on the bridge to the north that demands to meet a true warrior.\n\nPerhaps you can see what it wants.\n\nIt did not seem hostile. It might even be willing to help us.", objectives = "" }
WordHunterWoW_QuestEN[59972] = { title = "Hjalmar's Final Execution", description = "You now wield my most powerful skill, young warrior. \n\nNow use it to finish me! These ogres trapped my spirit here long ago for daring to defy them.\n\nOnly through a glorious death will I finally be allowed to rest. \n\nIt is the only way I will see my brothers and sisters in the afterlife.", objectives = "" }
WordHunterWoW_QuestEN[59973] = { title = "A Bond Beyond Death", description = "Since crossing into the Shadowlands, I've been so focused on our mission that I never even considered the souls of my family being here somewhere.\n\nWhatever this realm called Maldraxxus is, I hope it is worthy of my father's service!\n\nWe must free him, {name}. There is... much I need to say to him.", objectives = "" }
WordHunterWoW_QuestEN[59974] = { title = "A Soul Saved", description = "Vyraz... all this time...\n\nThis cannot stand, {name}. We must avenge Krexus and cut him down!\n\nHe must have sent you to the Maw expecting that you would never return. He underestimated you. A fatal mistake.\n\nGo with Mograine and claim Vyraz's head. I will warn our forces at the Seat of the Primus.", objectives = "" }
WordHunterWoW_QuestEN[59975] = { title = "To Darkmaul Citadel", description = "The last remaining survivor is being held within the ogre's citadel.\n\nCrenna and Herbert have a plan to get us inside.\n\nA small group of us will gather up north. You're coming with us.\n\nIf we fail here, the ogres will gain control of Kalecgos and his powerful blue dragon magic.", objectives = "" }
WordHunterWoW_QuestEN[59978] = { title = "Right Beneath Their Eyes", description = "We need to get into Darkmaul Citadel, rescue the last survivor, and stop Gor'groth.\n\nHerbert and Crenna are going to cast a spell to make you look an ogre... and then you're going to take us in as your \"prisoners.\"\n\nSpeak with Herbert when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[59979] = { title = "Like Ogres to the Slaughter", description = "This is worse than I thought. The ogres were counting on us to stage a rescue attempt.\n\nIt seems that they plan to attack our camp while they near completion of the ritual.\n\nWe can't let that happen. Crush the ogres! Show them the strength of the Horde!", objectives = "" }
WordHunterWoW_QuestEN[59980] = { title = "Catapult Destruction", description = "As we snuck in here I noticed the ogres erecting catapults to destroy our camp.\n\nCork must have anticipated this and gave me several explosives to use, \"just in case\".\n\nTake these explosives and blow up those catapults!\n\nAlso don't shake them too hard.", objectives = "" }
WordHunterWoW_QuestEN[59981] = { title = "Controlling their Stones", description = "Warlord Thunderwalker won't last much longer. Soon, his life essence will be completely drained. \n\nGor'groth mentioned that they are keeping him captive through the use of ward stones.\n\nI want you to recover these ward stones and bring them here so we can release Thunderwalker.", objectives = "" }
WordHunterWoW_QuestEN[59984] = { title = "Dungeon: Darkmaul Citadel", description = "Gor'groth seeks to use shadow magic to gain control of Kalecgos, the aspect of the Blue Dragonflight.\n\nHe's collected enough life essence to attempt to finish the ritual. I do not know what will happen, but we cannot let him complete it!\n\nGor'groth will not stop until he is slain!\n\nYou must storm the citadel and slay Gor'groth before he can complete his ritual!\n\nI would charge in beside you, were I not still recovering from his dark magic.", objectives = "" }
WordHunterWoW_QuestEN[59985] = { title = "An End to Beginnings", description = "You've done well here, {name}. Kalecgos and Wrathion are planning to continue on to the Dragon Isles.\n\nI must return to Orgrimmar. This shadow magic is concerning... and requires that I look into it more.\n\nTalk with Kalecgos. He'll get you to the Dragon Isles and inform you about what's going on there.", objectives = "" }
WordHunterWoW_QuestEN[59986] = { title = "Wide Worlds of Catalysts", description = "Catalysts come in different forms, for now we shall introduce you to two of them.\n\nSpeed catalysts can speed up the restoration process. This can obviously be helpful for managing how many souls we can recover.\n\nQuality catalysts improve the quality of the material goods that a spirit might offer upon their restoration. \n\nReturn to me when you have found an example of each. I will be eager to see whether your small little eyes are sharp enough to spot them.", objectives = "" }
WordHunterWoW_QuestEN[59994] = { title = "Trust Fall", description = "Let us ponder the meaning of the Archivist's last words: \"Victory only belongs to those brave enough to fall.\"\n\nHmm. It could be reference to the Volume of Victory. That is the most well-known of all the writings said to be kept in this tower.\n\nThat book is priceless, {name}. I mean that almost literally. We must do whatever is necessary to find it!\n\nBut, uh... What do you suppose \"brave enough to fall\" refers to?", objectives = "" }
WordHunterWoW_QuestEN[59999] = { title = "Rebirth of the Grove", description = "Though not yet withered, the conservatory wilts amidst the drought. This grove is not what it once was.\n\nAs warden, I bear the twin burdens of guilt and shame. Fate saw to this grove's decay and my failure to prevent it.\n\nBut fate has also seen to hope in its renewal. Hope in you.\n\nI beseech you, mortal, to seek out Zayhad in the Heart of the Forest and restore what has been lost.\n\nFor as the wounded spirits must be reborn, so too must this grove.", objectives = "" }
WordHunterWoW_QuestEN[60001] = { title = "[NYI] The Sword in the Stone", description = "Mortal! \n\nKnow this: only one who is deemed worthy may draw me from this stone.\n\nHowever, since you are clearly not that, and I really am bored, I want you to go find some dredgers to break the stone apart so you can carry me with you.\n\nGet to it.", objectives = "" }
WordHunterWoW_QuestEN[60003] = { title = "A Valiant Effort", description = "It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale.\n\nWhile we managed to escort many to safety, there are some who were wounded in the chaos.\n\nSearch the training grounds for any survivors from the onslaught.\n\nWe need all the help we can get.", objectives = "" }
WordHunterWoW_QuestEN[60004] = { title = "A Valiant Effort", description = "It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale.\n\nWhile we managed to escort many to safety, there are some who were wounded in the chaos.\n\nSearch the training grounds for any survivors from the onslaught.\n\nWe need all the help we can get.", objectives = "" }
WordHunterWoW_QuestEN[60005] = { title = "Imminent Danger", description = "The Temple of Courage must not fall!\n\nAll kyrian learn to fight in its hallowed halls. Not only to protect Bastion, but to ensure their own safety when retrieving souls from across the veil. \n\nTravel there at once. Seek out Thanikos, the Paragon of Courage's loyal hand.", objectives = "" }
WordHunterWoW_QuestEN[60006] = { title = "Now or Never", description = "In a fair fight our warriors could stand against countless swarms of these Maldraxxi.\n\nThis was no fair fight, outsider.\n\nThey came without warning. Without cause. We were caught unprepared.\n\nThey must not be allowed to encroach any further. This stops here.", objectives = "" }
WordHunterWoW_QuestEN[60007] = { title = "Stay Scrappy", description = "I can rebuild this colossus's core systems, but a few things are beyond repair. Thankfully there were enough centurions present here that I believe we can improvise.\n\nReplacements are in order!\n\nI require an Anima Conflux to charge its systems, some Eternity Plating to protect its core, and an Archonic Resonator to make it go boom!\n\nI'll take care of the rest. Quickly, now!", objectives = "" }
WordHunterWoW_QuestEN[60008] = { title = "Rip and Tear", description = "We will show these Maldraxxi insurgents the price for their betrayal.\n\nThe northern grounds have been taken by the House of Constructs, home to Maldraxxus' most resilient warriors.\n\nThey have earned no mercy this day, and we will give them none. We will carve through them side by side until this sacred ground is cleansed.", objectives = "" }
WordHunterWoW_QuestEN[60009] = { title = "Fight Another Day", description = "Some of our brethren are still alive in there!\n\nWhile many were lost in the initial assault, they seem keen on taking any survivors prisoner. I know not what they intend, but given their mastery of corpses we must assume the worst.\n\nSome have already been taken to their necropolis above, but others remain in cages on the ground. Free all you can.", objectives = "" }
WordHunterWoW_QuestEN[60013] = { title = "Leave it to Mnemis", description = "I have deduced by the urgency in your collective voices that you wish to leave.\n\nI will expedite your exit. There is a transport pad in the antechamber. I will ensure that the chamber is sealed once again on your exit.\n\nPlease accompany me.", objectives = "" }
WordHunterWoW_QuestEN[60014] = { title = "Shadowlands 60 E", description = "", objectives = "" }
WordHunterWoW_QuestEN[60015] = { title = "Shadowlands 60 E", description = "", objectives = "" }
WordHunterWoW_QuestEN[60020] = { title = "An Opportunistic Strike", description = "I'm impressed you made it this far. But don't get too full of yourself.\n\nMost of the fodder you plowed your way through were amateurs at best. Only one combatant will leave this arena a champion.\n\nEach of the five... uh, three houses has fighters in the field. Most merely seek to test their own limits or earn a bit of favor. Only a few have a real chance at claiming victory.\n\nSeek out those challengers if you wish to claim true glory this day.", objectives = "" }
WordHunterWoW_QuestEN[60021] = { title = "Champion the Cause", description = "Now you're starting to show potential! I'm guessing your name was well known on whatever mortal world you hail from.\n\nBut don't rest on your laurels. The harder you fight, the harder others will strive to strike you down. That's the Maldraxxi way!\n\nNothing wins the favor of the crowd like taking down a former champion. Two are in attendance today, attempting to recapture their past glories.\n\nSlaughter them!", objectives = "" }
WordHunterWoW_QuestEN[60025] = { title = "Shadowlands (60) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[60035] = { title = "Shadowlands (60) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[60040] = { title = "Shadowlands (60) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[60041] = { title = "Build-A-Bomination", description = "We need to get to work, every soul here needs a body.\n\nWe have the parts to build a body for Chordy. Chordy is a great scavenger, rebuilding him could allow us to find more construct parts easier.\n\nWould you help me to rebuild him?", objectives = "" }
WordHunterWoW_QuestEN[60042] = { title = "May I Take Your Order?", description = "Chordy is just the first success, there will be many more!\n\nAs free souls show up here, speak with them and take their requests for new construct bodies. We'll soon have lots of new constructs to work on!", objectives = "" }
WordHunterWoW_QuestEN[60043] = { title = "Justice from Above", description = "Our forces above cannot fully descend upon this area while the Margrave's crystals cover the sky in destructive blasts.\n\nThe Margrave's foul butchers work even now to extract the remaining anima from the kyrian they abducted in their assault on Bastion. We must advance at once.\n\nI shall imbue you with the flames of courage so that you may mark the crystals. Once marked, I will destroy them from afar.", objectives = "" }
WordHunterWoW_QuestEN[60044] = { title = "Charging The Blade", description = "We can't advance with those juggernauts bombarding our position! I led a strike against the nearest one, but conventional weapons do nothing against their imbued hides.\n\nThankfully, I have an idea.\n\nYour runeblade can't deal with them as it stands, but if you could purge Gharmal's empowered masses and absorb their essence into the blade...", objectives = "" }
WordHunterWoW_QuestEN[60048] = { title = "Stitching Time", description = "With the proper resources we can build a force of construct warriors greater than anything ever seen in the Shadowlands.\n\nVisit Arkadia Moa and see if you can secure the resources we need.", objectives = "" }
WordHunterWoW_QuestEN[60049] = { title = "At Your Service", description = "I suppose I should commend you. You certainly exceeded my expectations.\n\nRathan can be sentimental, but he is right. This place can be our new home, and here we can construct new bodies for the souls you freed.\n\nInform Baroness Draka that she has earned the allegiance of Princess Emeni and the constructs of Butchers Block! We stand ready for whenever she has need of our strength.", objectives = "" }
WordHunterWoW_QuestEN[60050] = { title = "Trouble on the Western Front", description = "The Ashbringer and your fellow Maldraxxi need reinforcements at the western gate. They are barely holding on!\n\nXandria and my kin will reinforce our position here and push forward towards Gharmal. We must make haste to Mograine--without both flanks, we cannot hope to achieve victory.", objectives = "" }
WordHunterWoW_QuestEN[60051] = { title = "A Master of Their Craft", description = "If we wish to get a travel network up and running, we'll need a master mirror maker in our employ. \n\nI've heard rumors that one such tradesman has landed himself in the Ember Ward. I am sure it won't take much cajoling to convince him to join our ranks. \n\nHead back into the Ember Ward and find this master mirror maker.", objectives = "" }
WordHunterWoW_QuestEN[60052] = { title = "Double Tap", description = "The House of Rituals occupies the southern half of the temple. Unlike the constructs, their key advantage in battle is their endless army of risen fighters.\n\nThankfully, the Archonic Resonator we recovered will take care of it.\n\nAs we carve our way through their forces, blast their corpses with the resonator. Its energy will sunder their souls, preventing them from being raised to fight again.", objectives = "" }
WordHunterWoW_QuestEN[60053] = { title = "Clear as Crystal", description = "This Anima Conflux is completely drained of anima! Just a heavy hunk of metal!\n\nNot your fault, of course. Not at all. But we need to charge it!\n\nThe Maldraxxi have extractors. Big green crystals, can't miss them. They're using it to drain anima from fallen kyrian. Very bad!\n\nWe can use them to charge the conflux, then our colossus here will be functional again!", objectives = "" }
WordHunterWoW_QuestEN[60054] = { title = "The Final Countdown", description = "If the necromancer's brood descends upon us fully before the colossus is charged, we will perish. There is no question.\n\nWe must keep his attention until Mikanikos's work is complete.\n\nHe believes that the day is already won -- that we are pawns to be toyed with. We can use his hubris to our advantage to buy precious seconds.\n\nMay it be enough.", objectives = "" }
WordHunterWoW_QuestEN[60055] = { title = "A Time for Courage", description = "I know not what awaits us across the chasm, outsider. By the Archon's grace I hope that my Paragon yet lives, but I fear the worst.\n\nWe will face this great unknown together, as we have the rest of Maldraxxus's horrors. To be kyrian is to follow the path, no matter how dire the circumstances.\n\nWhatever happens, know that you have earned my undying respect this day.", objectives = "" }
WordHunterWoW_QuestEN[60056] = { title = "Follow the Path", description = "Maldraxxus must answer for their crimes against Bastion. There shall be justice!\n\nLet us go to Oribos and speak with the Tal-Inara, the Honored Voice. We will tell her what has transpired this day. Tell her that the kyrian will not stand idle against this aggression.\n\nArtemede will inform the Archon. My brothers and sisters will surely prepare for war.\n\nThat must not come to pass.", objectives = "" }
WordHunterWoW_QuestEN[60057] = { title = "Necrotic Wake: A Paragon's Plight", description = "Xandria, the mighty Paragon of Courage, is the finest warrior among all the ascended. But even she may be overwhelmed by the strongest of Maldraxxus' forces.\n\nYour fate is intertwined with hers, now. You must gather your allies and plunge into the Necrotic Wake to ensure both Amarth and Nalthor do not make it back to the safety of their realm.\n\nMay the Archon guide your blade into their hearts.", objectives = "" }
WordHunterWoW_QuestEN[60060] = { title = "Mirror Attunement: Pridefall Hamlet", description = "Work has been completed on a mirror that will allow travel between Sinfall and Pridefall Hamlet. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", objectives = "" }
WordHunterWoW_QuestEN[60061] = { title = "Tough as Silk", description = "We are the heart of silk production in Ardenweald, but we can't do our work! \n\nOur grove has been completely taken over by spriggans and these strange shapeshifting... things.\n\nThe silkstriders who spin the silk are very delicate creatures. They need peace and calm, and a little music to keep them happy! But with all these monsters all over the place, they're super stressed out.\n\nPlease, can you get in there and eliminate these hooligans, and see if you can help get us up and running again?", objectives = "" }
WordHunterWoW_QuestEN[60062] = { title = "The Shattered Harp", description = "<The harp lies broken, with pieces missing.\n\nPerhaps you can find more pieces, and get someone to repair it.>", objectives = "" }
WordHunterWoW_QuestEN[60063] = { title = "A Song for Silkstriders", description = "There, the harp is fixed. I am too injured to take it to the silkstriders, but you are strong. You can help them.\n\nOur precious silkstriders are all across the cliffs. When you find one, play the harp for them, and they will give you fresh silk. Make sure that there is nothing nearby to stress them out first though!\n\nIf you find yourself in need of a way to move about swiftly, just take a Silk Shooter there, next to me. Aim it where you want to go, and it will shoot silk to pull you there!", objectives = "" }
WordHunterWoW_QuestEN[60064] = { title = "Save Ol' Gertie", description = "We have to find Ol' Gertie! She is the broodmother of the silkstriders, and is our most reliable producer. We cannot lose her.\n\nBut I cannot get to her and see if she is all right. She is usually at the top of the cliffs, at the highest point. Can you get up there, and make sure that she is safe?\n\nIf she is not... then may justice fall swift and hard on the perpetrator.", objectives = "" }
WordHunterWoW_QuestEN[60065] = { title = "Thread of Hope", description = "<Gertie Jr. looks up at you with hope. Perhaps you can help get her to safety.>", objectives = "" }
WordHunterWoW_QuestEN[60066] = { title = "Silk for Ardenweald", description = "It's clear that we may not be able to consistently supply Ardenweald with silk. But there is something that will help.\n\nTake Gertie Jr. and the silk you collected from the other silkstriders back to the Heart of the Forest. There, she will be safe, and perhaps grow up into a silkstrider as grand and beautiful as her mother!", objectives = "" }
WordHunterWoW_QuestEN[60067] = { title = "Pursuit of Justice", description = "Draka stands ready to unleash the power of the necropolis upon Gharmal. We need only buy her time to focus its weaponry.\n\nWhat we do now, we do for all of us. Bastion and Maldraxxus have both lost much to these fiends.\n\nGharmal will not be defeated easily... but united, our forces will finally bring them to justice!", objectives = "" }
WordHunterWoW_QuestEN[60092] = { title = "Skoldus Hall", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "" }
WordHunterWoW_QuestEN[60096] = { title = "Wrath of the Lich King: To Northrend!", description = "The Lich King stirs in the north.\n\nAn undead army follows his command, marching across Northrend and spreading blight wherever they tread.\n\nWe need you to stop them, {name}.", objectives = "" }
WordHunterWoW_QuestEN[60097] = { title = "Wrath of the Lich King: To Northrend!", description = "The Lich King stirs in the north.\n\nAn undead army follows his command, marching across Northrend and spreading blight wherever they tread.\n\nWe need you to stop them, {name}.", objectives = "" }
WordHunterWoW_QuestEN[60098] = { title = "The End is Now", description = "Our forces have control of the House of Constructs, thanks to your intervention.\n\nNow, all that remains is to vanquish their treacherous leader--Margrave Gharmal.\n\nThis battle has been long in the making, {name}. I am at your side without hesitation.\n\nLet us confront this monster. We will join Xandria to see Gharmal slain.", objectives = "" }
WordHunterWoW_QuestEN[60099] = { title = "Fracture Chambers", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "" }
WordHunterWoW_QuestEN[60100] = { title = "The Soulforges", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "" }
WordHunterWoW_QuestEN[60101] = { title = "Deadsoul Interstitia", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "" }
WordHunterWoW_QuestEN[60102] = { title = "Kakophonus", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "" }
WordHunterWoW_QuestEN[60103] = { title = "The Miscreation Wing", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "" }
WordHunterWoW_QuestEN[60104] = { title = "Darkness' Domain", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "" }
WordHunterWoW_QuestEN[60105] = { title = "Sineater Belfry", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "" }
WordHunterWoW_QuestEN[60106] = { title = "The Upper Reaches", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "" }
WordHunterWoW_QuestEN[60107] = { title = "The Winding Halls", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "" }
WordHunterWoW_QuestEN[60108] = { title = "Drust and Ashes", description = "The Drust encroach upon the Grove of Awakening, {name}!\n\nWe must fly in defense of Ardenweald!", objectives = "" }
WordHunterWoW_QuestEN[60110] = { title = "Never Had a Friend Like Me", description = "I feel like you could use a little help, Maw Walker. There is knowledge I have which could make you more useful to the Necrolords.\n\nSo just this once... I will teach you something and you won't even have to lose a limb.\n\nSoulbind with me and we'll see if you can learn anything.", objectives = "" }
WordHunterWoW_QuestEN[60111] = { title = "Forging A Friendship", description = "When you first arrived I was uncertain of your potential. The Primus demands such perfection in his work... and you are far from perfect.\n\nI see now that you bring new knowledge and ideas to our house. Your actions make us stronger. The Primus would be proud of you and wish for us all to learn from you. \n\nI am ready now to know your ways.\n\nLet me soulbind with you now, so we can grow stronger together.", objectives = "" }
WordHunterWoW_QuestEN[60112] = { title = "Cut to the Bone", description = "I fear if our presence is known, so too is the presence of our comrades.\n\nWe must develop a contingency. With the foundry on such high alert, we cannot sneak about undetected.\n\nUnless, of course, you were to provide a distraction. Perhaps thinning their numbers would suffice.", objectives = "" }
WordHunterWoW_QuestEN[60113] = { title = "An Urgent Request", description = "Champion,\n\nA matter of great urgency has arisen--one that requires your immediate attention.\n\nDue to the sensitive nature of recent events, I must withhold further details until we meet.\n\nWe have much to discuss. King Greymane and I await your arrival at Lion's Rest.", objectives = "" }
WordHunterWoW_QuestEN[60114] = { title = "Aerial Advantage", description = "Gharmal's rocs dominate the skies above, striking at our forces as we advance. We cannot move the necropolis into position until they are cleared out!\n\nI would slaughter them myself, but the cowards remain out of reach, and I am not constructed for flight.\n\nYou, however, seem slight enough of build. Take my riding hook and latch onto a roc. \n\nOnce you are atop of one, beat it to a pulp. Worry about the landing later.", objectives = "" }
WordHunterWoW_QuestEN[60115] = { title = "An Urgent Request", description = "Champion,\n\nA matter of great urgency has arisen--one that requires your immediate attention.\n\nDue to the sensitive nature of recent events, I must withhold further details until we can speak in person.\n\nThere is much to discuss. Regent Lord Lor'themar Theron awaits your arrival in Orgrimmar.", objectives = "" }
WordHunterWoW_QuestEN[60116] = { title = "Cause for Distraction", description = "The very heart of the Alliance is under attack.\n\nThe undead Scourge is swarming in numbers not seen since the return of Arthas Menethil. Amidst the chaos, something... terrible has happened.\n\nWhat I am about to share with you has not yet been revealed to our allies. They will be told in due time, but I needed to speak to you directly before word gets out.\n\nAllow me to explain.", objectives = "" }
WordHunterWoW_QuestEN[60117] = { title = "Return of the Crusade", description = "The Scourge's unbound hunger has been unleashed. It's only a matter of time before those monsters swarm our streets.\n\nWe need expertise in dealing with this menace. The death knights of the Ebon Blade have stepped forward to aid us, but even they can't do this alone.\n\nThe Argent Crusade has answered the call. I need you to work with them to keep our people safe, {name}.\n\nI have sent word of your arrival to their commander. He awaits you at their camp just inside the city gates.", objectives = "" }
WordHunterWoW_QuestEN[60120] = { title = "Burning Crusade: To Outland!", description = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the draenei. Adventurers of the Alliance are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion.\n\nTravel to the Blasted Lands, and pass through the Dark Portal.", objectives = "" }
WordHunterWoW_QuestEN[60123] = { title = "Burning Crusade: To Outland!", description = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the orcs. Adventurers of the Horde are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion.\n\nTravel to the Blasted Lands, and pass through the Dark Portal.", objectives = "" }
WordHunterWoW_QuestEN[60124] = { title = "A Fascinating Byproduct", description = "When the Mawsworn extract anima from a soul within The Maw, a fascinating byproduct is formed: stygia.\n\nFrom stygia the Mawsworn form weapons, armor, and even the land beneath you. It is useful in its raw form, of course, but occasionally I need a purer form for my research.\n\nThey produce this concentrated stygia within The Tremaculum. You and I could perform trade, yes?", objectives = "" }
WordHunterWoW_QuestEN[60125] = { title = "Mists of Pandaria: To Pandaria!", description = "Please come to Stormwind Keep immediately for a briefing with King Varian Wrynn.\n\nWe have received word of a conflict in the seas to the south, and we need the help of an experienced {class} to assist in the investigation.", objectives = "" }
WordHunterWoW_QuestEN[60126] = { title = "Mists of Pandaria: To Pandaria!", description = "You are hereby ordered to present yourself at Grommash Hold immediately.\n\nWe have received word of a new, resource-rich continent in the south, and we intend to send you and a small contingent of soldiers to claim it for the Horde.", objectives = "" }
WordHunterWoW_QuestEN[60127] = { title = "Missing Stone Fiend", description = "You or I could wield these sinstones directly, but I much prefer to use stone fiends for such tasks.\n\nExceptional results, no personal risk.\n\nUnfortunately, my stone fiend did not return from its last errand.\n\nSpeak with Cryptkeeper Kassir in the archives above. He is loyal to the Accuser and will loan us his stone fiend.", objectives = "" }
WordHunterWoW_QuestEN[60128] = { title = "Ready to Serve", description = "Do not mind Temel. His zeal for heralding sins is powerful, but he is still a stone fiend. He will obey.\n\nGive Archivist Fane my regards.", objectives = "" }
WordHunterWoW_QuestEN[60129] = { title = "Stranger in an Even Stranger Land", description = "<You arrive alone at the precipice of a strange city, knowing the leaders of Azeroth remain trapped in the Maw.\n\nWherever you are, it is clearly very, very far from home.\n\nIt appears your arrival has been noticed.>", objectives = "" }
WordHunterWoW_QuestEN[60132] = { title = "Constellan Writs and Stygia", description = "There is much to discover within the Maw, and much of it can be turned to future profit.\n\nInformation is an investment.\n\nThere are many objects that I find interesting in this place, and I am happy to barter with you should you find any.\n\nFind one and we shall open negotiations.", objectives = "" }
WordHunterWoW_QuestEN[60136] = { title = "Into Torghast", description = "The bond to your covenant is growing stronger, {name}. Good. The power lies within you to venture into Torghast and rescue our allies.\n\nYou saw Baine Bloodhoof while assisting the broker in the Maw. Perhaps this Ve'nari knows a way to breach the Jailer's tower and find the chieftain.\n\nWhen I peered into Torghast once before, you stood at my side. I believe that connection will allow me to see through your eyes as you navigate its torments.\n\nSeek out Ve'nari and request her aid, Maw Walker.", objectives = "" }
WordHunterWoW_QuestEN[60138] = { title = "Unlocking the Gates", description = "", objectives = "" }
WordHunterWoW_QuestEN[60139] = { title = "Torment Chamber: Jaina", description = "<Bolvar studies the objects you acquired from the brokers in Torghast.>\n\nI sense Lady Proudmoore's magic upon this debris. And these notes describe methods to contain her power.\n\n<The Highlord focuses on the items, peering into the darkness.>\n\nBy the Light! They are tormenting her with white-hot fires. Though her will is strong, there is only so much any mortal can endure.\n\nI will modify Ve'nari's Attuned Shard using the items you returned.\n\nYou must find her, {name}. Before it is too late.", objectives = "" }
WordHunterWoW_QuestEN[60145] = { title = "Third Talon Vartox", description = "This \"win the spirit of the people\" operation is noble and good. \n\nHowever, we must set our sights on cutting down our foe's tools. Third Talon Vartox, the leader of this incursion, also serves as the top stoneborn at the Tithelord's estate.\n\nIf we strike her down here, the Tithelord will be left exposed for our attack.", objectives = "" }
WordHunterWoW_QuestEN[60146] = { title = "Torment Chamber: Thrall", description = "Using the totem you recovered, I will alter the Attuned Shard to guide you to Thrall's location.\n\n<Bolvar hands you the crystalline object.>\n\nTake care. You know the torments Baine and Lady Proudmoore endured in that accursed place. Thrall's confinement will be no less harrowing.\n\nBeware. The deeper you journey into the Tower of the Damned, the closer you get to the Jailer himself.\n\nFree Thrall, {name}... before all hope is lost.", objectives = "" }
WordHunterWoW_QuestEN[60147] = { title = "Mirror Attunement: The Eternal Terrace", description = "Work has been completed on a mirror that will allow travel between Sinfall and The Eternal Terrace. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", objectives = "" }
WordHunterWoW_QuestEN[60148] = { title = "No Place for the Living", description = "A living mortal ... incredible!\n\nForgive my astonishment. I am Kah-Delen, an overseer of the Arbiter's attendants here in the Eternal City of Oribos.\n\nYou stand within the heart of the Shadowlands. While we are accustomed to receiving souls from all manner of worlds within the mortal realm, never before has one arrived that is quite so ... corporeal.\n\nAnswer honestly, mortal. Did you truly escape the Maw?", objectives = "" }
WordHunterWoW_QuestEN[60149] = { title = "Audience with the Arbiter", description = "I am Tal-Inara, Honored Voice of the Arbiter. I speak for she who is ever silent.\n\nThe Arbiter watches over Oribos. She blesses us with her wisdom. Every mortal soul that enters the Shadowlands passes before her for judgment.\n\nIn the merest fraction of a moment, she sees every glory, every folly, every joy, every regret. With this knowledge, she chooses an ideal afterlife for that soul.\n\nAt least, she did. Not long ago, catastrophe struck, and ...\n\nCome. Some things are better seen than explained.", objectives = "" }
WordHunterWoW_QuestEN[60150] = { title = "Tether to Home", description = "It is disappointing that you were unable to stir the Arbiter, but we must not give up hope.\n\nYour continued presence in the Shadowlands may help our cause. Perhaps your efforts would benefit from creating a tether to the mortal plane.\n\nThe map table in this chamber was put in place long ago by the First Ones, the wise architects of all you see.\n\nIf you have a memento from your homeworld, place it there. The table's magic can establish a connection.", objectives = "" }
WordHunterWoW_QuestEN[60151] = { title = "A Doorway Through the Veil", description = "The Helm fragment connected us while you were in the Maw. As if through a darkened pane of glass, I saw glimpses of what you endured. The terrors you faced.\n\nAt least the heroes of Azeroth yet live. They must be saved.\n\nBy affixing the Helm here, you gave us a tether to Azeroth that served to bring a few of us across the veil. But you, and other heroes who join us, require a stronger connection.\n\nOur acolytes can open portals back. No doubt these attendants will be particular about their placement.", objectives = "" }
WordHunterWoW_QuestEN[60152] = { title = "The Eternal City", description = "You should become familiar with the Eternal City and how best to navigate it.\n\nWe, the attendants, serve Oribos as its caretakers. \n\nEverything you see here is done in service to the Purpose. In this time of chaos and drought, we must adapt our perspective. It seems we are to serve the Purpose in a new way.\n\nYou mortals are not the only visitors here. Others have come as well.\n\nLike you, the brokers are not of Oribos. They are congenial and willing to aid you. Usually for a price.", objectives = "" }
WordHunterWoW_QuestEN[60153] = { title = "Into the Unknown", description = "Come to pay old Marasmius a visit? I have a special task for you.\n\nOne of my shoots has found a strange place, a place even I've never seen before.\n\nI'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for!\n\nWhat do you say, {name}? Up for an adventure?", objectives = "" }
WordHunterWoW_QuestEN[60154] = { title = "Understanding the Shadowlands", description = "As I sat upon the Frozen Throne all those years, {name}, I could peer into the Shadowlands. Brief glimpses, clouded and uncertain. Sights both wondrous and terrible.\n\nWe must work together to make sense of what has happened. To prevent the Maw from consuming all of reality.\n\nWhatever Sylvanas and the Jailer want, we must stop them. But we cannot do so alone.\n\nPerhaps Tal-Inara can put us on the path to find answers.", objectives = "" }
WordHunterWoW_QuestEN[60155] = { title = "To Open the Way", description = "", objectives = "" }
WordHunterWoW_QuestEN[60156] = { title = "The Path to Bastion", description = "Within the Arbiter's Chamber are gateways to the infinite realms of the Shadowlands. As each soul was judged, a gateway would be opened to the appropriate afterlife. \n\nBut since the... incident, all gateways have remained closed. Dormant.\n\nWe dare not use the Arbiter's sacred chamber for so mundane a purpose as travel. But here in the upper ring of the city, gateways can be configured for your needs.\n\nBefore us stands the means to activate a gateway. Together we can channel the anima to power it.", objectives = "" }
WordHunterWoW_QuestEN[60157] = { title = "Answers from the Ascended", description = "", objectives = "" }
WordHunterWoW_QuestEN[60158] = { title = "Rule 7: Betrayal is Inevitable", description = "Our arrangement has been quite lucrative. Reliable associates like yourself can be so hard to find.\n\nI believe I can entrust you with a task I would usually perform on my own.\n\nWhile working with the tracking runes you retrieved for me earlier, I detected a device of broker origin nearby. It must have been brought into the Maw by the captured expedition.\n\nPlease examine it and prepare it for transport back to the refuge. I will join you shortly.\n\nThis could be a valuable discovery.", objectives = "" }
WordHunterWoW_QuestEN[60159] = { title = "Mirror Attunement: Halls of Atonement", description = "Work has been completed on a mirror that will allow travel between Sinfall and the Halls of Atonement. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", objectives = "" }
WordHunterWoW_QuestEN[60160] = { title = "Mirror Attunement: The Banewood", description = "Work has been completed on a mirror that will allow travel between Sinfall and The Banewood. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", objectives = "" }
WordHunterWoW_QuestEN[60161] = { title = "Your Continued Existence", description = "Now that you possess Stygia, I recommend that you create a device that will allow for rapid relocation to my designated safe area.\n\nIt will greatly increase the liklihood of your continued existence within the Maw.\n\nIn proximity to myself lies a Book of Cyphers. You may use it without my permission, as the notion of personal possession is primarliy a social construct.", objectives = "" }
WordHunterWoW_QuestEN[60162] = { title = "The Art of Taming", description = "Quite the surprise to find this beast so hale and hearty. It seems to have taken a liking to you.\n\nIf you're ever going to be as great as one of the Dawntrackers, you must learn how to handle multiple pets.\n\nAllow me to show you how.", objectives = "" }
WordHunterWoW_QuestEN[60164] = { title = "Mirror Attunement: Dominance Keep", description = "Work has been completed on a mirror that will allow travel between Sinfall and Dominance Keep. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", objectives = "" }
WordHunterWoW_QuestEN[60165] = { title = "Mirror Attunement: Feeders' Thicket", description = "Work has been completed on a mirror that will allow travel between Sinfall and Feeders' Thicket. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", objectives = "" }
WordHunterWoW_QuestEN[60168] = { title = "The Art of Taming", description = "I'm quite surprised to find this beast still alive and kicking. It appears to like you.\n\nBefore we finish, you had better learn how to wrangle multiple pets.\n\nI'll give you one last lesson.", objectives = "" }
WordHunterWoW_QuestEN[60169] = { title = "Securing the Area", description = "The Scourge's attack was as sudden as it was unexpected. Truth be told, they caught us unawares.\n\nThrough swift action, we were able to rally our defenses... though not before the tournament grounds were overrun.\n\nWe must secure the area before we can mount a counteroffensive.\n\nVanquish these monsters in the name of the Light!", objectives = "" }
WordHunterWoW_QuestEN[60172] = { title = "This Quest is Temporary", description = "Dropping out of the sky is a key part of this playtest, so enjoy the ride.", objectives = "" }
WordHunterWoW_QuestEN[60174] = { title = "The Divine's Shield", description = "This island has foul necromancy here in addition to the shadow magic. The Light can only just reach this place.\n\nCall upon its Divine Shield to step through the barrier before us unharmed and destroy this vile altar.\n\nShow the darkness on this island that you are protected by the Light's embrace.", objectives = "" }
WordHunterWoW_QuestEN[60175] = { title = "A Taste of Tirna Noch", description = "I'm a simple mushroom with simple pleasures, {name}. And what's simpler than a nice, hearty meal?\n\nDon't look so surprised. I need to eat just like anyone else! How else do you think I grew so big? Nice, tasty compost, that's how!\n\nBack in my day, I had the pick of Ardenweald for where to feed. Now, not so much.\n\nI've had a hankering for some of the loam that used to be around Tirna Noch. I haven't had shoots out there in a long time. Could you bring me some?", objectives = "" }
WordHunterWoW_QuestEN[60176] = { title = "Bring Out Your Tithe", description = "Unfortunately the Lord Chamberlain's gift isn't sufficient to cover the entire tithe we're expected to provide the Tithelord, but it will make a good start.\n\nThe loss of the tithe convoy is a terrible blow to our village. Our little community is already suffering greatly from the drought and the need to meet the Tithelord's demands. Still we must all do our part.\n\nWe have little time to accomplish this task. Can you help? Get the tithe from villagers and scour the area for every forgotten drop.", objectives = "" }
WordHunterWoW_QuestEN[60177] = { title = "Reason for the Treason", description = "If you ask me, the attack on our convoy is suspicious. I told Mistress Mihaela that there must be a traitor in the village, but she isn't concerned. It's understandable. She's got to worry about gathering a new tithe.\n\nI've taken it upon myself to figure this out and I could use your help. I'm making discreet inquiries but I can't be seen speaking with the help. That's where you come in. You can be my assistant sleuth.", objectives = "" }
WordHunterWoW_QuestEN[60178] = { title = "And Then There Were None", description = "Ilka and Samu argued, you say? And you found a coded message indicating that the tithe was going to be sent out soon. Those are helpful clues that will allow me to put the puzzle together. \n\nIt's clear to me now who betrayed the village and what we need to do about it! You deliver invitations to a meeting to our suspects and I'll prepare to reveal the traitor.", objectives = "" }
WordHunterWoW_QuestEN[60179] = { title = "Memory of Honor", description = "<A tablet sits embedded in the ground near a broken armor display.\n\nThe runes on the epitaph conjure images of an ancient warrior in your mind. Clearly Maldraxxus honors the history of those who claimed great victories here.\n\nSimilar memorials seem to be spread throughout the trench. Perhaps they can offer more insight into the denizens of this realm.>", objectives = "" }
WordHunterWoW_QuestEN[60180] = { title = "A Paragon's Reflection", description = "<The Vault-Keeper examines you.>\n\nYou appear to carry a signature unique to one of the Paragons. If you know which Paragon, simply peer into their Soul Mirror to examine the memory of your choice.\n\nIf you require anything else, you need only speak.", objectives = "" }
WordHunterWoW_QuestEN[60181] = { title = "Trench Warfare", description = "These would-be recruits seek a way to prove themselves. Let us give them the chance.\n\nThe specter known as Malifis has grown in strength by consuming our anima reserves. In this time of drought, we cannot afford to lose any of our most precious resource. \n\nThis threat needs to be dealt with immediately.\n\nUse this horn to signal the scavengers we've recruited. Let us see how well they fight under our banner!", objectives = "" }
WordHunterWoW_QuestEN[60182] = { title = "Feasting Soul Eater", description = "", objectives = "" }
WordHunterWoW_QuestEN[60183] = { title = "After Them!", description = "We must move quickly! That anima will be key in fueling these citizens for the fight ahead.\n\nDeathfang is ready to ride.", objectives = "" }
WordHunterWoW_QuestEN[60184] = { title = "Dude, Where's My Necropolis?", description = "Maintaining the portal between our sanctum and the Zerekriss is a difficult task. With enough resources, we could make it permanent and become the unstoppable force my baroness wishes us to be.\n\nShe has asked much of you, as have I. But this work will make your name a legend among the Maldraxxi, as my baroness's has become.\n\nHelp to empower us, and you will be empowered in turn.", objectives = "" }
WordHunterWoW_QuestEN[60188] = { title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", objectives = "" }
WordHunterWoW_QuestEN[60189] = { title = "We Strike Now", description = "The time has come. The Wild Hunt has driven the Drust back to their stronghold at the edge of Ardenweald.\n\nTheir scouts report that Gorak Zhar herself is among them. This may be our only opportunity to fully purge the minions of Thros from this realm.\n\nLord Herne awaits your arrival at the battlefront. Go with haste, {name}.", objectives = "" }
WordHunterWoW_QuestEN[60190] = { title = "Assault on Darkreach", description = "The Drust have inflicted enormous loss on this forest and its denizens, {name}. It is time we put an end to their atrocities.\n\nWe will drive the Drust from their enclave and close their gateway into Ardenweald. With you as our vanguard, victory is assured.\n\nI will make my way into the heart of their camp. Find me once you have routed their forces.", objectives = "" }
WordHunterWoW_QuestEN[60191] = { title = "Ingra Drif", description = "Ingra Drif, the Drust captain, has been spotted inside Darkreach. This is our chance to destroy him for good.\n\nI know him and his cruelty all too well, {name}. Whatever you do to him, it's better than what he deserves.", objectives = "" }
WordHunterWoW_QuestEN[60192] = { title = "Their Last Line of Defense", description = "Those sneaky Drust are protecting Gorak Zhar with their evil magic!\n\nI can sense several foul runes that are scattered across Darkreach. If you destroy them, we can easily shatter the barrier around that nasty Gorak Zhar.\n\nHurry! I will meet you inside the enemy camp.", objectives = "" }
WordHunterWoW_QuestEN[60193] = { title = "Unmasked", description = "Thanks to your efforts, the shield that protects our prey has been made brittle as a dried leaf.\n\nOur hunt is all but complete. \n\nCome, let us put an end to the vile Gorak Zhar.", objectives = "" }
WordHunterWoW_QuestEN[60194] = { title = "The Call of the Hunt", description = "I fear Lord Herne will have further need of our aid before this night is over.\n\nCome, I'll put some wings on you. We'll have to fly if we want to keep up with him.", objectives = "" }
WordHunterWoW_QuestEN[60195] = { title = "Build One More", description = "All these souls deserve a new construct, and when rebuilt any of them will make a valuable addition to our forces.\n\nWe must start somewhere. \n\nYou should be able to find Malleable Flesh through out the Shadowlands. A few of the other parts may be harder to locate.\n\nCollect parts and use the Abominable Stitching Table to build another construct.", objectives = "" }
WordHunterWoW_QuestEN[60211] = { title = "Spore Losers", description = "", objectives = "" }
WordHunterWoW_QuestEN[60215] = { title = "Timely Gate Crashers", description = "Did you see that giant mechanical monstrosity just walking around in the dunes outside? How about the icky shadowy Sha of Anger? Or that big frost giant in the north? Yeah, they aren't native to this area. \n\nThey tell me the timeways are screwy around this time of year. They have asked me to organize a clean-up crew.\n\nWould you be up to the challenge? If you like this challenge, I have another for you as well.", objectives = "" }
WordHunterWoW_QuestEN[60217] = { title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", objectives = "" }
WordHunterWoW_QuestEN[60218] = { title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", objectives = "" }
