WordHunterWoW_QuestEN[60227] = { title = "TBD Soulguard Torch", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[60228] = { title = "Sinstone Delivery TBD", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[60229] = { title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", objectives = "" }
WordHunterWoW_QuestEN[60230] = { title = "More the Merrier", description = "News of our work here has spread, new souls have arrived seeking to join us!\n\nTake their requests for new construct bodies. We'll see if we can build them new constructs too!", objectives = "" }
WordHunterWoW_QuestEN[60237] = { title = "Old Stomping Grounds", description = "Once, long ago, I journeyed to Ardenweald to assist in putting down a threat now long forgotten.\n\nI remember that while there, I saw small creatures taking tiny clusters of anima--animacones, the fae called them--and buried them under the soil.\n\nIf those clusters are still there, we must gather them for ourselves!\n\nI should be able to unearth any of the animacones we encounter. Let's go hunt for them!", objectives = "" }
WordHunterWoW_QuestEN[60238] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[60239] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[60242] = { title = "Trading Favors: Necrotic Wake", description = "We of the brokers place value on things that may seem strange to an outsider like yourself. Objects that are unusual or one-of-a-kind are things we may find more valuable than others.\n\nSo let us make a deal, hm? Should you find yourself in possession of one such object, I will offer a trade for something you may find more valuable.\n\nI hear that the forces of Maldraxxus have made an attack on Bastion. Such things rarely happen without objects of power in tow, no?", objectives = "" }
WordHunterWoW_QuestEN[60243] = { title = "Trading Favors: Sanguine Depths", description = "The generals of Revendreth are outfitted with only the finest arms and armor, procured by Sire Denathrius in his unquenchable appetite for power. In terms of profitable trades and exchanges, he has been a shrewd partner in trade to us.\n\nIt would please me greatly to see the return of some relics that were traded in a way that benefited him far more than us. There are few things more insulting to my kind.", objectives = "" }
WordHunterWoW_QuestEN[60244] = { title = "Trading Favors: Halls of Atonement", description = "The mechanisms by which each land of the Shadowlands operates are quite intriguing. Yet, I have always held a particular fascination with the venthyr of Revendreth.\n\nHow they siphon souls of their sins, storing them in strange stones, and dredge up minions from the muck that surrounds them -- it is all quite novel.\n\nThey keep their secrets close at hand, however, and will not willingly part with information. I offer trades for any of their tomes you might come into possession of.", objectives = "" }
WordHunterWoW_QuestEN[60245] = { title = "Trading Favors: De Other Side", description = "Mueh'zala is an ancient and primitive creature that commands a place known as De Other Side. Little is known about this land, as we are not permitted to visit. We have sent many offers of trade, yet there has never been a reply. \n\nA pity, as the few that have escaped Mueh'zala's clutches claim his domain to be a place of many oddities.\n\nWe would never ask you to venture into such danger. There is, however, a standing offer of trade for things procured from Mueh'zala's grasp.", objectives = "" }
WordHunterWoW_QuestEN[60246] = { title = "Trading Favors: Tirna Scithe", description = "The gorm devour anything in their path when left unchecked. We have sold more than a few of them as both pets and weapons. You do not want to see what a world looks like when they are introduced to it and allowed to infest.\n\nOr perhaps, mhm, you do? For some, that is entertainment.\n\nIt is difficult for us to explore Ardenweald with things as they are at this time. A fat, healthy gorm larva would fetch a fine price on the markets. I trust my meaning is understood?", objectives = "" }
WordHunterWoW_QuestEN[60247] = { title = "Trading Favors: Theater of Pain", description = "Grandmaster Vole runs the arena in Maldraxxus, where the champions of each of the houses compete for glory. Naturally, prizes are often awarded to the victors. \n\nThose of our kind do not often participate in such battles. To find such a prize for sale by one of us would be quite unusual indeed.\n\nI trust I need say no more? Let us keep this transaction between us, and I will be happy to part with some valuable goods.", objectives = "" }
WordHunterWoW_QuestEN[60248] = { title = "Trading Favors: Plaguefall", description = "Is is such a shame what happened to poor Margrave Stradama. Just between us, she was once one of our most favored trading partners. When things get lost in Maldraxxus they tend to end up at the bottom of her blighted pools.\n\nYou would not, perhaps, be interested in continuing this relationship on her behalf? We would, of course, compensate you quite well.\n\nI am sure she has little use for these possessions in her current state.", objectives = "" }
WordHunterWoW_QuestEN[60249] = { title = "Trading Favors: Spires of Ascension", description = "The Kyrians of Bastion serve a unique role in the Shadowlands, ferrying mortal souls from their realms to ours. They are able to do so in great numbers, it would seem, in times of crisis or devastation.\n\nWe would like to know more about their travels to the realms beyond. \n\nSurely one of them has brought something back from another land? They are, after all, so very interested in memories.", objectives = "" }
WordHunterWoW_QuestEN[60250] = { title = "A Valuable Find: Theater of Pain", description = "The Theater of Pain in Maldraxxus is a brutal place, where only the strongest survive. \n\nWith the houses so fiercely in competition with one another, it is considered a great point of pride to house a champion with a winning record.\n\nAs such, the house lords often outfit their contenders with powerful arms, armor, and trinkets. Often these are storied items that have been passed down through many battles.\n\nI would very much like to see such an item.", objectives = "" }
WordHunterWoW_QuestEN[60251] = { title = "A Valuable Find: Plaguefall", description = "Life in Maldraxxus is one of constant warfare, the great houses in perpetual competition with one another. Every once in a great while, a house lord obtains an item or piece of knowledge of such rarity that it tips the scales in their favor.\n\nIt is possible, even probable, that this was the cause of the fate that befell the House of Plagues.\n\nI do not need to tell you how valuable such a rarity would be to us, do I?", objectives = "" }
WordHunterWoW_QuestEN[60252] = { title = "A Valuable Find: Spires of Ascension", description = "You have, no doubt, visited Bastion and seen what happens to souls that are accepted there. Their memories are extracted, viewed, and even stored in their great Temple of Wisdom.\n\nThis temple houses memories that may answer some of the greatest questions we have about our realm and the worlds beyond. It is a shame they are locked away.\n\nWe have heard that the fallen Paragon of Loyalty has interest in these memories. Any memory that would catch her attention would surely be worth trading for.", objectives = "" }
WordHunterWoW_QuestEN[60253] = { title = "A Valuable Find: Necrotic Wake", description = "Once in a rare while, we find ourselves in possession of an object of exceptionally cryptic origin. These objects allow us a brief glimpse into the realms beyond our comprehension. \n\nIt may seem to you that I speak in riddles, yet so much of this realm is shrouded in mystery, even to us.\n\nThere are others that have sought to unravel the history of this realm. Should you happen upon one of their works, I will offer you a trade of exceptional value.", objectives = "" }
WordHunterWoW_QuestEN[60254] = { title = "A Valuable Find: Tirna Scithe", description = "The gorm are indiscriminate in what they consume, so long as it does not contain anima. A gorm queen that has lived for many generations may have any number of indestructible artifacts lodged within her belly. For this reason, sifting through a queen's carcass is not unlike treasure hunting for us.\n\nOne of the largest queens is currently consuming Tirna Scithe. She surely is bloated with valuables. Should you come upon anything particularly unusual, know that we will compensate you in kind.", objectives = "" }
WordHunterWoW_QuestEN[60255] = { title = "A Valuable Find: De Other Side", description = "Mueh'zala has been around for many generations, how many exactly we cannot say. His domain is a land of mystery to us all. \n\nBut we are a people of probabilities and margins. A creature of that age, with such power, and the many ancient souls within his domain, has a great chance to be in possession of a relic of unfathomable rarity.\n\n<The light around Ta'lan's head flares brightly for a moment. He seems... excited?>\n\nSlay the foolish creature, bring me his secrets, I will reward you handsomely!", objectives = "" }
WordHunterWoW_QuestEN[60256] = { title = "A Valuable Find: Halls of Atonement", description = "The aristocracy of Revendreth trade in decadent and priceless shows of status with one another, but rarely with our kind.  Often they will travel with a piece or two affixed to their garb as a show of status.\n\nNow, many of their kind have sided with Sire Denathrius and against the denizens of the Shadowlands. They must, of course, be stopped. \n\nOf course.\n\nYet should you, in the process of doing so, relieve them of some of these possessions, know that I will trade generously.", objectives = "" }
WordHunterWoW_QuestEN[60257] = { title = "A Valuable Find: Sanguine Depths", description = "General Kaal has slain many foes, and in a bag at her side, she holds the skulls of those she considers her most precious kills. Not all of them, of course, have skulls --  it is a bag of eclectic contents.\n\nContained within, we have heard, is the head of one of our kind. We do not know to whom it might belong, for we do not often find ourselves running afoul of the venthyr.\n\nSuch a strange mystery must be solved. I will, of course, provide great compensation.", objectives = "" }
WordHunterWoW_QuestEN[60264] = { title = "Soul Survivor", description = "I knew when you helped me in the Etheric Vault, that you were a just and worthy leader.\n\nI have come here to offer you my help and services in your efforts to bring Maldraxxus back into balance.\n\nPlease, build a construct for me, and allow me to help you as you have helped me.", objectives = "" }
WordHunterWoW_QuestEN[60265] = { title = "Disrupting the Chain", description = "From the desk of the Tithelord:\n\nAll supply carriages must re-route to Stonevigil for collection assistance. Once complete, you may resume your regularly scheduled routes.", objectives = "" }
WordHunterWoW_QuestEN[60267] = { title = "Prison of the Forgotten", description = "<As you stare at the object you've found, you sense it may lead you to another part of this wretched tower.\n\nPerhaps Ve'nari may know more of its purpose.>", objectives = "" }
WordHunterWoW_QuestEN[60268] = { title = "Deep Within", description = "Who... who are you? Have you come to extract more of my memories?\n\nI'm afraid there aren't any useful ones left, save for the memories of my imprisonment.\n\nOr perhaps you're here for something else?", objectives = "" }
WordHunterWoW_QuestEN[60269] = { title = "Reawakening", description = "If you can retrieve my memories, I can help you. At least I believe I can.\n\nThen, perhaps, we can help each other.", objectives = "" }
WordHunterWoW_QuestEN[60270] = { title = "A Damned Pact", description = "Yes... I begin to remember. Power. Power with a purpose. That is what I can offer.\n\nRunes. Runes are the key. I've recalled some of them, but to infuse them into your equipment, I require my hands.\n\nWell, one hand would suffice. Both would be better.\n\nFind a way to free me from my bonds, mortal. Then I can offer the power you seek. After that, freedom... and perhaps the downfall of the one who bound me.", objectives = "" }
WordHunterWoW_QuestEN[60271] = { title = "A Grave Chance", description = "First you'll need a vessel to house anima and a way to expel it. I happen to possess such a device, which I'll be pleased to give to you.\n\nFor a price, of course.\n\nYou recall Zovaal's Cauldron, I trust? The denizens there were forged in unholy fire. Assuming their anima is of a similar nature, it should be able to melt even the metals of the tower.\n\nWith my device and their anima, I believe you can achieve your goal, Maw Walker.", objectives = "" }
WordHunterWoW_QuestEN[60272] = { title = "The Weak Link", description = "This ought to be enough to break the bonds that hold your newfound ally.\n\n<Ve'nari pauses for a moment.>\n\nBefore you do so, I offer a word of warning.\n\nNo creature imprisoned in that place should be trusted. Tread carefully, mortal. \n\nAfter all, it would be a shame to lose so valuable a business partner.", objectives = "" }
WordHunterWoW_QuestEN[60274] = { title = "Trading Favors", description = "Welcome, friend. \n\nI can see by your garb that you must have quite a storied history. Many unique relics befitting of one that has traveled the worlds and vanquished many foes.\n\nThere are those of us that find great value in such things, and would willingly part with our own valuables for a taste of what you may find. \n\nLet your curiosity guide you to the dark hallway across from the cookpots in the next room. Down there, you will find answers.", objectives = "" }
WordHunterWoW_QuestEN[60275] = { title = "WANTED: Enforcer Kristof", description = "WARNING!\n\nShrouded patrols have increased throughout the Ember Ward. By order of Enforcer Kristof, all who are found near the asylum will be forced to endure the Light. \n\nUse extreme caution when venturing beyond our sanctuary. Even the shadows are not safe so long as Kristof remains in power.  \n\nA reward awaits whoever is able to rid the ward of this tyrant. \n\n- Dispatcher Raluca", objectives = "" }
WordHunterWoW_QuestEN[60276] = { title = "WANTED: Summoner Marcelis", description = "Be advised:\n\nSummoner Marcelis and his cohorts are dabbling in dangerous magics. They are calling forth ashen elementals to ravage these Light-scorched lands. \n\nWe cannot let such acts continue. \n\nAny who can are urged to put an end to this madness. \n\n- Dispatcher Raluca", objectives = "" }
WordHunterWoW_QuestEN[60277] = { title = "WANTED: Aggregate of Doom", description = "Attention all workers: \n\nWe got ourselves a problem down in the thicket. \n\nA golem is trekking through the worksite, causing all sorts of trouble. \n\nGrab a rock and get to throwin'. The dredger that takes it out gets the rest of the day off. \n\n- Foreman Scug", objectives = "" }
WordHunterWoW_QuestEN[60278] = { title = "WANTED: Duke Anton", description = "Loyal Citizens of Revendreth: \n\nDuke Anton and his decrepit house are relics of noble venthyr society. \n\nHis attempts to tarnish my name are laughable at best. \n\nIt is time someone rid us of Duke Anton's presence for good.\n\nI shall offer double whatever pathetic sum he can muster. \n\nSincerely, \n\nLord Darion of House Redelav", objectives = "" }
WordHunterWoW_QuestEN[60279] = { title = "WANTED: The Pale Doom", description = "Notice to all: \n\nA lingering menace lurks in the Endmire, dangerously close to Darkhaven's border. \n\nIf alone in your travels, take care to avoid this monstrosity, lest it make you meet your true death.\n\nThose with a sense of adventure and a well-armed brigade might manage to slay this beast. If so, a reward will await you upon your return. \n\nSincerely, \n\nTaskmaster Gavril", objectives = "" }
WordHunterWoW_QuestEN[60280] = { title = "WANTED: Lord Darion", description = "To Whom it May Concern: \n\nLord Darion of House Redelav thinks that he can buy his place in society. \n\nHe flaunts his wealth, using it to win favor of other lords and ladies. Is there no price on decency? \n\nThis is not the way the noble houses of Revendreth should conduct themselves. \n\nI implore you to find Lord Darion and help him meet his true death. \n\nThe honor of House Briarbane rests in your capable hands.\n\nWarmest Regards, \n\nDuke Anton of House Briarbane", objectives = "" }
WordHunterWoW_QuestEN[60281] = { title = "Rule 4: Make A List", description = "I've discovered that one of the Jailer's inquisitors is attempting to devise a method to track my movements.\n\nClearly, that is a problem for me... and by extension, it is a problem for you.\n\nThe inquisitor has risen to the top of my list of potential threats. In the past, I would have had to deal with him myself. But now... I have a business partner.\n\nPut an end to him, yes? And if you can, determine exactly how he intended to track me.", objectives = "" }
WordHunterWoW_QuestEN[60283] = { title = "Specter Of War: Visectus", description = "We have conjured Visectus to lead our attack, but we need your help to prepare it properly.\n\nWe require more Anima-bound Wraps to strengthen the summons.", objectives = "" }
WordHunterWoW_QuestEN[60284] = { title = "Rule 5: Be Audacious", description = "You have proven yourself a useful associate, {class}. In thanks, I have crafted a cypher that will allow you to venture further into the Maw.\n\nBut... it is experimental in nature. You will have to test it in the field. And I have just the test in mind.\n\nCartel Ve has foolishly sent more agents into the Maw. They were captured and taken to Perdition Hold. I must know why.\n\nBreach the fortress and learn what has become of the captive brokers. Nothing is more valuable than knowledge of your enemy's plans.", objectives = "" }
WordHunterWoW_QuestEN[60285] = { title = "Rule 6: Concealment is Everything", description = "I have made a startling discovery, {name}. \n\nDo you recall how the captured agents of my cartel were taken to the Beastwarrens? \n\nThe Mawsworn seem to think they possess a means of tracking me. And now, strange new runes empower the Jailer's hounds.\n\nClearly, we cannot have that.\n\nThis new cypher will grant you solace from the screeching in the Beastwarrens. Brave its caverns and secure those runes for inspection.\n\nIf we are to counter their effects, I must know how they work.", objectives = "" }
WordHunterWoW_QuestEN[60286] = { title = "A Token of Our Admiration", description = "Ahh, the Maw Walker returns. No doubt prepared to rush into danger for the common good?\n\nI'll get to the point. You have made contact with a member of our cartel, Ve'nari. Her continued survival within the Maw is in spite of incalculable odds.\n\nWe wish to assure her that she has not escaped our regard. Would you be our messenger?", objectives = "" }
WordHunterWoW_QuestEN[60287] = { title = "Rule 1: Have an Escape Plan", description = "Many doomed souls suffer within the Maw. You must be careful if you do not wish to join them.\n\nYour Soulkeeper can hold a small number of souls until you return to your covenant. But that will be of little benefit if you do not survive this place yourself.\n\nThere is a substance, stygia, that is found on some creatures within the Maw. The stronger the soul, the more stygia they have.\n\nCollect some of it for me and I can fashion it into many things you will find quite useful.", objectives = "" }
WordHunterWoW_QuestEN[60289] = { title = "Rule 3: Trust is Earned", description = "Before you leave this cursed realm, there is one final task you must complete for me.\n\nThe Mawsworn regularly transfer souls to various blocks of Torghast from many different areas in the Maw.\n\nI happen to know of one such area. Place this beacon there so I may be informed when the next transfer happens.\n\nAnd if you are seen by the enemy... well, you are known for your prowess in combat, yes?", objectives = "" }
WordHunterWoW_QuestEN[60291] = { title = "Corpse Run", description = "There's work that needs doing 'round here. Mmmm hmmm.\n\nSpotted a big ol' carcass nearby. I aim to salvage it for parts. \n\nFigure you could come along, help me drag it to Rathan. He'd like that. Mmmm hmmm. \n\nReckon I could even carry you there and back. You don't look too big.\n\nReady to get going?", objectives = "" }
WordHunterWoW_QuestEN[60292] = { title = "Dangerous Discourse", description = "I found this scroll while you were cleansing the temple.\n\nThese are dire words, and I suspect it only gets worse. Collect more of these scrolls so I can determine just what these so-called Forsworn want.", objectives = "" }
WordHunterWoW_QuestEN[60296] = { title = "Pride or Unit", description = "You have made great strides with our pride. I hope you found value and fulfillment in working with the larion.\n\nThe time to meet with Pelodis has come. You must decide whose way of life is more rewarding, and which you would prefer to pursue.", objectives = "" }
WordHunterWoW_QuestEN[60313] = { title = "Dredhollow", description = "That was a narrow escape.\n\nBut I believe this presents an opportunity to finally turn the tide of this strife and defeat the Fearstalker. Meet me at Dredhollow: the abandoned hunting lodge of the Fearstalker.  \n\nWe must take separate paths. The Fearstalker will soon be after us again.", objectives = "" }
WordHunterWoW_QuestEN[60315] = { title = "WANTED: Gorgebeak", description = "Thief! Pilferer! Menace!\n\nThe insidious menace known as Gorgebeak threatens our harvest of ambrosi for tribute to our great Archon. She must be stopped!\n\nIf any are willing to take on this foul fowl, I have tracked her nest to the western edges of Firstborne's Bounty. Proof of her demise shall be amply rewarded.\n\n--Gerdus", objectives = "" }
WordHunterWoW_QuestEN[60316] = { title = "WANTED: Altered Sentinel", description = "Praetor broken! At Aspirant's Crucible. Attacking everybody!\n\nSomething wrong. Maybe changed?\n\nSimo not know how to fix. Tried everything!\n\nMust destroy!", objectives = "" }
WordHunterWoW_QuestEN[60338] = { title = "Journey to Ardenweald", description = "The warning you received from the Primus needs to reach the Winter Queen of Ardenweald, {name}. The Eternal Ones must stand together against the coming darkness.\n\nThe Winter Queen oversees the cycle between Death and Life. In her forest slumber ancient spirits of nature that must be reborn.\n\nI fear the anima drought will have taken an especially grim toll upon her realm. \n\nThe night fae can lead you to the Queen. Bring her this message, and she will know what needs to be done.", objectives = "" }
WordHunterWoW_QuestEN[60340] = { title = "Hands on Approach", description = "When I was imprisoned in the Etheric Vault, the anima scroungers would come to steal what little strength my soul still had. I swore I'd have revenge upon them should I ever escape.\n\nNow, with my blade hands... it's time for my revenge! \n\nI've seen anima scroungers near the House of Constructs. I want their leader dead and the anima they took from me recovered!", objectives = "" }
WordHunterWoW_QuestEN[60341] = { title = "First on the Agenda", description = "Let's make a deal, {name}. I'll seek out the Winter Queen on your behalf if you complete a few of my duties in my stead. The Queen isn't the only one who's been kept busy by the drought!\n\nFirst, you're going to help my fellow fae here with their spriggan problem. Boot their leader off that poor moth! Featherlight will tell you where to go after that. \n\nWe'll reunite in Tirna Vaal if you survive.\n\nOh, and I would stay on the path if I were you. Ardenweald can be dangerous for the unwary!", objectives = "" }
WordHunterWoW_QuestEN[60342] = { title = "Cut 'Em Down to Size", description = "Idle hands are a wasted opportunity. I need to keep my hands busy, or else these blades wouldn't be worth anything!\n\nI hear there's a devourer in Revendreth that's as tall as a house. Let's show the other constructs a thing or two by taking that monster out!", objectives = "" }
WordHunterWoW_QuestEN[60343] = { title = "Welcome to Orgrimmar", description = "The warchief will be waiting for our mission report from Exile's Reach. I must deliver it at once.\n\nFor now, Cork Fizzlepop will show you around the city. Orgrimmar has much to offer, so explore it as you see fit.\n\nI'll send for you once I've given my report to the warchief.", objectives = "" }
WordHunterWoW_QuestEN[60344] = { title = "Finding Your Way", description = "Orgrimmar's a big city. Way too big to explore on foot. Warlord Grimaxe has arranged for you to receive a mount to help you get around.\n\nShe said to speak with Rohaka at the stables... but I can't seem to remember the way there.\n\nDon't worry, {name}! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go.\n\nLet's ask a nearby guard for directions to the stable master. Then we can be on our way!", objectives = "" }
WordHunterWoW_QuestEN[60346] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Telotha Pinegrove to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[60347] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Tamanji to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[60348] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Feenix Arcshine to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[60349] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Huinli Wingpaw to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[60350] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Avaros Dawnglaive to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[60351] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Martin Goodchilde to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[60352] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Thega Graveblade to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[60353] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Hretar Riverspeaker to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[60355] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Kazak Darkscream to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[60357] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Gormok Ogrefist to learn more about specializations!", objectives = "" }
WordHunterWoW_QuestEN[60358] = { title = "Gildenite Grab", description = "Took our gildenite! Stole it! Stole it and took it away!\n\n<Sika's feathers ruffle.>\n\nNeed it, need it to make armor! Weapons!\n\nCan't make armor without gildenite!\n\n<Sika moves her arms as if explaining how armor is made.>\n\nYou understand? Yes? Why you still here?", objectives = "" }
WordHunterWoW_QuestEN[60359] = { title = "Home Is Where the Hearth Is", description = "I don't know about you, but I'm in the mood for some good ol' fashioned recreation!\n\nWhy don't we head over to The Wyvern's Tail and cool off with a few pints of Cobo Cola?\n\nWhile we're there, speak with Innkeeper Nufa to make The Wyvern's Tail your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn.\n\nNot only is it faster than a wyvern, but you'll save yourself some dough in the process!", objectives = "" }
WordHunterWoW_QuestEN[60360] = { title = "An Urgent Meeting", description = "I've been looking for you all over Orgrimmar, {name}.\n\nWarlord Grimaxe has delivered her mission report to the warchief. The Horde has need of you once again.\n\nI was ordered to find you and deliver the message without delay. It has been an honor to fight alongside you, {name}.\n\nLok-tar ogar!", objectives = "" }
WordHunterWoW_QuestEN[60361] = { title = "Battle for Azeroth: Mission Statement", description = "The warchief has requested to meet with you in person.\n\nLady Sylvanas was impressed with the prowess and courage you displayed during our mission to Exile's Reach. \n\nNow that you've arrived, I will make the introduction.", objectives = "" }
WordHunterWoW_QuestEN[60362] = { title = "Blank", description = "Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore.\n\nMany have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father.\n\nPerhaps she feels the time has come to atone for this.\n\nLoath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[60363] = { title = "Gildenite Grab", description = "Hshh... the golden ore, we need it.\n\nGolden ore of Bastion. Make their armor with it. \n\nWe need, many uses. Armors, weapons, trinkets and rings. Many uses.\n\nTravel to Bastion. The eyes have shown me stores of it, stolen and hidden throughout their lands.\n\nThey do not use it. We will. Go now.", objectives = "" }
WordHunterWoW_QuestEN[60364] = { title = "Gildenite Grab", description = "Our allies in Bastion are in possession of a special ore known as gildenite. A golden metal used for many things in their lands, it is also useful to us.\n\nOnce upon a time, we would have traded for it. Now, we have little to trade, and they have little to give.\n\nYet it is a necessary component to focus our magics, capable of harnessing magical energy and amplifying it.\n\nShould you come across any in your travels, liberate it, and return it to me. I shall use what we need, and share the remainder.", objectives = "" }
WordHunterWoW_QuestEN[60365] = { title = "Gildenite Grab", description = "The golden ore known as gildenite is found only in Bastion. Used to make many of their own armors, it is useful to us all. We harden our own armors and weapons with it, and it holds magical charge well.\n\nOur stores are nearly depleted, and we have little to trade, but our needs are great.\n\nLet us reflect. \n\nIn Bastion, there are those that have turned their backs on their own people.\n\nWe may relieve these deceivers of their gildenite without remorse.", objectives = "" }
WordHunterWoW_QuestEN[60366] = { title = "WANTED: Darkwing", description = "The Cloudfeather matriarch, Darkwing, has fallen to a great and terrible sickness. She has grown aggressive, dominating her children and driving them to violence.\n\nDarkwing must be slain if her flock is to ever return to the Archon's grace.\n\nPlease use the attached whistle to call her to her nest. I shall consider one of her crown feathers sufficient proof of the deed.\n\n--Eumelia, Stable Master", objectives = "" }
WordHunterWoW_QuestEN[60367] = { title = "Anima Crossing", description = "", objectives = "" }
WordHunterWoW_QuestEN[60369] = { title = "A Wealth of Wealdwood", description = "The shapers of our lands cultivate a very special form of wood we call wealdwood.\n\nIt contains the essence of Ardenweald, of the plants and animals that make up our soil and our air. It can be enchanted with powerful magics, and it will not burn.\n\nIt is the basis of our arms and armor, and in these dark days, it is a target of our enemies.\n\nThey steal and hoard it, out there in the wilds. \n\nFind them, and return our treasures to us.", objectives = "" }
WordHunterWoW_QuestEN[60370] = { title = "A Wealth of Wealdwood", description = "In Ardenweald, the shapers form boughs into a magical form of wood. Wealdwood, an enchanted substance used for many sorcerous purposes, is a key component in our rituals.\n\nWithout it, our magics pale in comparison to those of our enemies.\n\nYet in these times, Ardenweald is beset by many foes. They steal the supplies of the Night Fae and scurry off into the dark places.\n\nTravel to those places, and return to us once you have brought atonement to these vile creatures.", objectives = "" }
WordHunterWoW_QuestEN[60371] = { title = "A Wealth of Wealdwood", description = "The eyes have shown me supplies, in Ardenweald. Hidden in the boughs, hidden from us, but they cannot hide from the eyes.\n\nThey do not use it, not as we would. We must use it. It is ours to take.\n\nKshhhh... bring it to us, the shaped wood. Many uses, very magical. Holds magic as a pitcher holds slime, fills with it.\n\nNeed it for our sorcerers. Cannot win in battle without our magic. Must win, no other way.", objectives = "" }
WordHunterWoW_QuestEN[60372] = { title = "A Wealth of Wealdwood", description = "Ardenweald in trouble! We in trouble too! No Ardenweald, no wealdwood.\n\nWealdwood magical, help us make many thing.\n\nYou find some? Bring to Sika? Yes? Hoo?\n\nYes. \n\n<Sika writes your name on a scroll and underlines it twice, then shows it to you.>\n\nSee?", objectives = "" }
WordHunterWoW_QuestEN[60373] = { title = "A Source of Sorrowvine", description = "There is a dark, evil vine that grows in Revendreth, known as sorrowvine.\n\nThey say it feeds off of the anguish of the souls as they are broken.\n\nRegardless of its origins, it is used in many of our potions and spells. It contains a powerful magic, likely a product of its origin.\n\nRevendreth has little opportunity to trade with us these days. Should you find any of these vines, I will gladly accept them.", objectives = "" }
WordHunterWoW_QuestEN[60374] = { title = "Bonemetal Bonanza", description = "The denizens of Maldraxxus are used to a life of battle, and in doing so, find themselves in possession of so very many bones.\n\nThey form their armors out of a cultivated form of bone we call bonemetal. Harder than most metals, yet pliable, it can be forged into a variety of shapes without losing its strength.\n\nWe have many uses for it, both as a means of attachment, and when ground up, as a reagent.\n\nWe cannot ask them for resources now, but if you find any, I would use it.", objectives = "" }
WordHunterWoW_QuestEN[60375] = { title = "Bonemetal Bonanza", description = "Maldraxxus no longer answers our calls, and the houses are in disarray.\n\nYet we have need of them. Once, they supplied us with bonemetal, a strong yet malleable material useful for many armors.\n\nThere are those in Maldraxxus that hoard the material, seeking to profit from the chaos.\n\nThey must atone for these sins.", objectives = "" }
WordHunterWoW_QuestEN[60376] = { title = "Bonemetal Bonanza", description = "Ksh-ksh-ksh... you are needed.\n\nSo many betrayers in our lands, many deaths, much armor destroyed. \n\nNeed to rebuild.\n\nThe eyes have shown me stores of bonemetal, hoarded by our foes.\n\nBring them to me.", objectives = "" }
WordHunterWoW_QuestEN[60377] = { title = "Bonemetal Bonanza", description = "<Sika is studying a scroll.>\n\nNo bonemetal! Again, out of bonemetal!\n\n<Sika throws a pile of scrolls into the air.>\n\nHoo! Where you come from?\n\nOh, OH. Bonemetal! You get? Get from Maldraxxus. Help us out!\n\n<Sika points in the direction of Maldraxxus.>\n\nThat way!", objectives = "" }
WordHunterWoW_QuestEN[60378] = { title = "A Source of Sorrowvine", description = "Sorrowvine grows only here, in the lowlands of Revendreth. It has power contained within the leaves and seeds, perhaps a byproduct of the cleansing of sins.\n\nWe use it for many things, from potions to venoms. It is a versatile reagent.\n\nOur stores are low, and we have little ability to forage these days with the forces of our enemies bearing down on us.\n\nAs you travel our lands, should you come upon any, we would make good use of it.", objectives = "" }
WordHunterWoW_QuestEN[60379] = { title = "A Source of Sorrowvine", description = "Kshh... need you today. Stores of sorrowvine getting low, need it for our venoms.\n\nRevendreth does not answer our calls. The eyes show me conflict and strife in their lands.\n\nThis matters little to us.\n\nShh... travel there, find their vines, return to me.", objectives = "" }
WordHunterWoW_QuestEN[60380] = { title = "A Source of Sorrowvine", description = "Need sorrowvine! Please help!\n\nRevendreth not sending us supplies, not answering Sika! Can't make potions now. What we do?\n\n<Sika seems to have just remembered that you were there.>\n\nYou go! \n\n<Sika pushes you.> \n\nGo go!", objectives = "" }
WordHunterWoW_QuestEN[60381] = { title = "Aiding Ardenweald", description = "Today, we must turn our gaze inward. We are beset by foes here, in Ardenweald, from all sides.\n\nTravel our lands, weapon in hand, and bring hope and victory with you. Bring aid to those in need, and remind them that we are here for them, and Ardenweald will not fall.\n\nRemind them that our great purpose will be fulfilled, and we will not let the groves wither.\n\nYou, Maw Walker, will unite us today.", objectives = "" }
WordHunterWoW_QuestEN[60382] = { title = "Aiding Revendreth", description = "We do not turn out backs on our allies, even when we face darkness here in Ardenweald.\n\nIn Revendreth, they battle against the forces of Sire Denathrius, who has proven himself a false leader.\n\nWe cannot allow those that make Sinfall their home to lose hope.\n\nTravel to Revendreth and supply aid to them. Show them that we will not let them falter, that we are stronger together.", objectives = "" }
WordHunterWoW_QuestEN[60383] = { title = "Aiding Maldraxxus", description = "Maldraxxus defends us from forces that threaten the Shadowlands, or at least, they once did.\n\nNow they are plagued by infighting and an imbalance in power.\n\nWe have few allies there, but those that remain, we must maintain.\n\nGo there, give them aid, and help them reunite the houses such that the armies of the undying may defend us once more.\n\nWithout them, we are but one invasion from complete annihilation.", objectives = "" }
WordHunterWoW_QuestEN[60384] = { title = "Aiding Bastion", description = "The denizens of Bastion have long served the Shadowlands with faith and honor. Without them, souls would not arrive for us to nurture, and our lands would wither and die.\n\nWe cannot allow them to fall, for without Bastion, we are lost.\n\nTravel to the golden fields, weapon in hand, and provide aid to our besieged allies. We will show them that in these dark times, they are not alone.", objectives = "" }
WordHunterWoW_QuestEN[60385] = { title = "Training in Revendreth", description = "The dark lands of Revendreth, ruled over by the traitor Denathrius, pose a great risk to us, and a great opportunity for training.\n\nCome here, trainee! Today, you hunt with the Maw Walker. Should you return to me, we will celebrate, with a hunt.\n\nFor tomorrow, we hunt.", objectives = "" }
WordHunterWoW_QuestEN[60386] = { title = "Training in Maldraxxus", description = "The forces of Maldraxxus are some of the most highly trained and well-regimented in all of the Shadowlands. Once, they defended us all, now we must fend for ourselves.\n\nThere is little better place for our trainees to gain real combat and strategy experience than on their blood-soaked battlefields.\n\nTake this one with you on your travels today, so that they may see what real combat looks like.", objectives = "" }
WordHunterWoW_QuestEN[60387] = { title = "Training in Bastion", description = "Our hunters do not have the time for proper training, and so we must train them in the field.\n\nOur allies in Bastion are in desperate need of support, and I wish one of the trainees to accompany you in this endeavor.\n\nDo you hear that, trainee? Today, you accompany the Maw Walker!\n\nMaw Walker, do not go easy on this one.", objectives = "" }
WordHunterWoW_QuestEN[60388] = { title = "Training Our Forces", description = "Get up, trainee, you must get up!\n\nLook at this one! Needs much more training before we stand a fighting chance against our enemies. \n\nWe have precious little time to build combat prowess these days, with so many foes at our backs.\n\nTake this one with you today, show them the ways of battle, and keep them safe from overwhelming odds. It is the only way we will make enough progress.", objectives = "" }
WordHunterWoW_QuestEN[60389] = { title = "Aiding Ardenweald", description = "Ay there, ya got a moment?\n\nLotta things going on down in Ardenweald. Bad stuff, bugs and things. Look delicious, but probably give me ol' stomach a nasty one.\n\nWe're lookin' pretty solid here today, ya see? Probably could use a hand down there. Maybe they give us a hand in return, see? \n\nDo I gotta spell it out for you? Get on over there, ya big goof.", objectives = "" }
WordHunterWoW_QuestEN[60390] = { title = "Aiding Ardenweald", description = "We are attacked by enemies on all sides, Maw Walker. \n\nAnd Ardenweald faces a similar threat.\n\nIt is in our best strategic interests to forge lasting alliances with those outside of Maldraxxus. Though we may be under assault, we are still the strongest military might in the Shadowlands. Under our protection, they will thrive and grow, and in turn, provide us with aid in our times of need.\n\nTogether, we are strong. This is the doctrine of the phalanx, and it will be ours as well.", objectives = "" }
WordHunterWoW_QuestEN[60391] = { title = "Aiding Ardenweald", description = "Ardenweald has long been one of our closest companions in the shepherding and nurturing of souls. Now they are beset by many foes, and we will not allow them to fall!\n\nMake haste to their forested lands, and with the blessing of the Archon upon you, serve a glorious purpose. Stand with them in their time of need, a gilded shield, a reminder that they are not alone!\n\nBastion stands with them, and with us, they will never falter!", objectives = "" }
WordHunterWoW_QuestEN[60392] = { title = "Aiding Bastion", description = "In our own golden hills, evil abounds. We will not allow it to take root and fester!\n\nRaise your voice, Maw Walker, and shout to the foes of Bastion! We are coming for them!\n\nWith haste, now, seek out those in need of your might. Bring the sharpened blade of faith to bear against doubt and uncertainty. Crush despair with a gilded fist, and let it know the vengeance of the Archon!\n\nFor Bastion!", objectives = "" }
WordHunterWoW_QuestEN[60393] = { title = "Aiding Bastion", description = "The kyrians of Bastion serve a unique purpose in the Shadowlands, and without them we will be unable to replenish our forces. Should we wish to stand triumphant in Maldraxxus, we must extend some of our might to aid them.\n\nTravel to Bastion and provide support, so as to stabilize their situation. In doing so, we will secure the future of our armies and cut off the supply to our enemies.\n\nWar is not always fought on the battlefield, but often in the means of replenishment.", objectives = "" }
WordHunterWoW_QuestEN[60394] = { title = "Aiding Bastion", description = "If'n the kyrians of Bastion don't get souls to the Shadowlands, we got no one to join up, and no anima to gain in them sinstones. Be in a bad place, you know, now and in the future, if things ever bother to get better.\n\nWe got things figured out here today. Head on over to them golden hills of Bastion and give 'em a hand. Bet they pay us back some day. They're all about honor an' stuff.\n\n<Rendle wipes his nose loudly.>", objectives = "" }
WordHunterWoW_QuestEN[60395] = { title = "Aiding Maldraxxus", description = "In the fetid wastes of Maldraxxus, we yet find allies. Their sacred duty, to defend the Shadowlands, has not been forgotten by all.\n\nWe must take flight, now, to stand side by side with our bone-bound brethren. Shoulder to shoulder, hand in hand, we will push back those that would sow chaos and discord.\n\nA spear of gold and bone we will form! And thrust it into the heart of evil!\n\nGo now, Maw Walker, as the tip of the spear, to glorious battle!", objectives = "" }
WordHunterWoW_QuestEN[60396] = { title = "Aiding Maldraxxus", description = "The allies we have here in Maldraxxus may be few, but we cannot turn our backs on them. Every hand we pull out of darkness and into our fold, is a hand that can hold a weapon or wand.\n\nWalk our lands, find those seeking aid, and provide it. Crush our enemies, and show them that we are at once everywhere. Make them fear you.\n\nFear is the seed that breeds doubt, and doubt is the root that crumbles empires.", objectives = "" }
WordHunterWoW_QuestEN[60397] = { title = "Aiding Maldraxxus", description = "Once was a time that those bony lot in Maldraxxus were the defenders o' all of us here in the Shadowlands. Now they spend their time destroyin' what little they got left.\n\nAll's I know is that if things keep up like this, one big ol' swath of devourers could sweep in and wipe us all out.\n\nGet over there and help them good ones keep the peace, maybe they help us out some day, too.", objectives = "" }
WordHunterWoW_QuestEN[60398] = { title = "Aiding Revendreth", description = "Our allies in Revendreth are all that stem the tide of Denathrius's forces from overtaking the rest of the Shadowlands. \n\nOnce, we would be charged with righting this wrong, but our armies have dwindled with the actions of our rival houses.\n\nToday, you will be the messenger from Maldraxxus, carrying a message of justice in the name of the great cycle of which we all take part.\n\nIt is your Primus-given duty to aid Sinfall against those that seek to break the cycle.", objectives = "" }
WordHunterWoW_QuestEN[60399] = { title = "Aiding Revendreth", description = "Oi there, got somethin' for you to do today.\n\nLots of problems outside of Sinfall, there are. Big problems, little problems, all sorts of problems.\n\nWe're not gonna make much headway against Denathrius with his lot at our heels all the time, ay?\n\nGet out there an' get some muck on your boots.", objectives = "" }
WordHunterWoW_QuestEN[60400] = { title = "Aiding Revendreth", description = "Take flight to Revendreth, where those that are loyal to the Shadowlands are under siege from the forces of Sire Denathrius.\n\nWe cannot allow them to fall. Without the aid of Sinfall, the forces of Revendreth will grow unchecked, and their dark alliance with the Jailer will threaten us all.\n\nWe of Bastion will not allow this to happen! Raise your swords, ready your shields, take wing and bring the glory of Bastion to Revendreth!", objectives = "" }
WordHunterWoW_QuestEN[60401] = { title = "Training in Ardenweald", description = "I have another trainee for you to look after, they need some training on the battlefield. Take them out to, oh, let's say Ardenweald. \n\n<Sakaa waves her hand vaguely in the direction of Ardenweald.>\n\nPlenty of things to maim over there, maybe they learn a thing or two about wood.\n\n<Sakaa smirks.>", objectives = "" }
WordHunterWoW_QuestEN[60402] = { title = "Training in Ardenweald", description = "Look at this lot! Bones and gristle, all of them. Need some meat on their bones and some training in their heads.\n\nTake this trainee out and get them some real combat experience.\n\nArdenweald's a good spot, plenty of things to fight there. Learn some new tactics, get them used to the chaos of battle, all that stuff.", objectives = "" }
WordHunterWoW_QuestEN[60403] = { title = "Training in Ardenweald", description = "It is our great duty to take our aspiring warriors and train them in combat. \n\nToday, this is your trainee. Take them to Ardenweald, show them what it means to be in the glorious service of the Archon. Defend our allies, and bring faith to their lands.\n\nTeach them the ways of battle and honor.", objectives = "" }
WordHunterWoW_QuestEN[60404] = { title = "Training Our Forces", description = "What better place to stretch our wings than right here on our own fields?\n\nTake one of our trainees out with you today, show them the ways of combat in Bastion against the growing threats we face here.\n\nPart of their training will be courage when facing off against those they thought their brethren.\n\nIt has been known to break hearts and ranks before.", objectives = "" }
WordHunterWoW_QuestEN[60405] = { title = "Training in Bastion", description = "Useless minions, the lot of them. All of this fodder needs to get trained.\n\nHere, take this one with you today. Get them away from me, go to... Bastion. Yeah, Bastion, far away from me.\n\nPlenty of things to test them against, there. \n\nIf you get them killed, I don't want to hear it.", objectives = "" }
WordHunterWoW_QuestEN[60406] = { title = "Training in Bastion", description = "I have yet another minion, er, recruit that needs training.\n\nTake them on out to the fertile fields of Bastion. There is plenty to learn over there that they won't find around these parts, perhaps it will help them grow into a better soldier. \n\nMaybe you pick up some new tricks while you're out there, too.", objectives = "" }
WordHunterWoW_QuestEN[60407] = { title = "Training in Maldraxxus", description = "Our aspiring warriors must be trained in the thick of battle, in the harshest conditions, for wars do not happen lightly, and never will it give them pause for breath.\n\nTake this one to Maldraxxus--the heart of the armies of the Shadowlands resides there. It is a land in chaos and turmoil, filled with fallen champions and gladiators.\n\nThere, they will face true challenges, and return with great knowledge.", objectives = "" }
WordHunterWoW_QuestEN[60408] = { title = "Training Our Forces", description = "Our armies are nothing without some combat training, but every time we send them out, they come back as a pile of bones and meat.\n\nTake a trainee out and pit them against the forces of the other houses. Just don't get them killed, alright? Not all the way killed. A little killed is fine.", objectives = "" }
WordHunterWoW_QuestEN[60409] = { title = "Training in Maldraxxus", description = "Another trainee needs some looking after, if you don't mind.\n\nMaldraxxus is a place of constant battle, and probably the best place to take them. They've got to learn about war and strategy and, you know, all that.\n\nJust throw them in the arena or something. 'Sink or swim' is an effective training strategy.", objectives = "" }
WordHunterWoW_QuestEN[60410] = { title = "Training Our Forces", description = "I have yet more troops for you to train, and there are plenty of things to do right here in our domain. \n\nTake them out and give them a good, solid, and probably bloody taste of what we're up against.\n\nNow, if you get them killed? That's none of my business.\n\n<Sakaa sips a thick and sweet-smelling beverage.>", objectives = "" }
WordHunterWoW_QuestEN[60411] = { title = "Training in Revendreth", description = "Lousy, useless, bunch of bones. This army's less of an army than it is a bunch of dead meat walking.\n\nDo me a favor, take out this trainee and head over to Revendreth. Give them some good battle training against some of our enemies, a little taste of strategy and tactics and maybe getting hit in the face with a little magic.\n\nWon't do us any good unless we find a way to train them that doesn't end up in a bunch of dead minions.", objectives = "" }
WordHunterWoW_QuestEN[60412] = { title = "Training in Revendreth", description = "A trainee is in need of your guiding hand.\n\nTake them to Revendreth, where you will find the armies of Denathrius thirsting for our demise. Wade in to battle with them against our mighty foes.\n\nReturn victorious, as their shield and mentor, so that our armies will be bolstered this day.", objectives = "" }
WordHunterWoW_QuestEN[60414] = { title = "Rare Resources", description = "The Brokers are odd characters, but useful. They can find many things across the vast realms of the Shadowlands that we cannot. \n\nWe have relied upon them to bring us useful materials for many years, but these days, we have little to trade.\n\nThey value a currency of their own making, coins of brokerage, as a general means of trade.\n\nIf you find any in your travels, I would appreciate a handful, as it would allow me to procure some rare and necessary items.", objectives = "" }
WordHunterWoW_QuestEN[60415] = { title = "Rare Resources", description = "Hello! Yes! Hello.\n\nBrokers, you know them? \n\n<Sika does her best attempt at looking like a broker. It is not convincing.>\n\nTrade many things with us. Things we no get. Things we want.\n\nNeed coins. Clink clink!\n\n<Sika makes a circle with her finger feathers.>\n\nFind them everywhere, bring them to Sika!", objectives = "" }
WordHunterWoW_QuestEN[60416] = { title = "Rare Resources", description = "Kh-kh-kh... the brokers, they go to many places. Many places we cannot. The eyes cannot follow them.\n\nFind many secrets, they do. Bring us supplies, strange and rare.\n\nNeed things to trade. Need broker coins.\n\nThey trade with all. Find coins in all lands. Slay those that hold them, bring the coins to me. \n\nYou may eat their corpses, I will not judge. Just need coins.", objectives = "" }
WordHunterWoW_QuestEN[60417] = { title = "Rare Resources", description = "The brokers are an enigmatic group. We know little about them, save that they can travel to many lands in the Shadowlands that we cannot. How they do this, we are not sure.\n\nThey are willing partners in trade, though, and through them we have acquired many rare and valuable resources that cannot be found elsewhere.\n\nThey hold in high regard a currency of their own creation, you may find such coins in your travels. \n\nI will gladly take them off of your hands to bolster our supplies.", objectives = "" }
WordHunterWoW_QuestEN[60418] = { title = "A Call to Bastion", description = "Our allies in Bastion are absolutely necessary for the Shadowlands to function at all. They alone can bring us the souls we need to keep the cycle moving. \n\nIf they fall to darkness, it's only a matter of time before we, too, dwindle and fade.\n\nThey are beset by all manner of problems. We have to get over there and help them!", objectives = "" }
WordHunterWoW_QuestEN[60419] = { title = "Troubles at Home", description = "They say that all of the Shadowlands is a stage, and right now, I think we're in a tragedy! \n\nAll throughout Ardenweald, we are under attack. They seek our anima and the souls that we protect.\n\nIf the cycle stops here, so many great souls will be lost... forever.\n\nThere's no time to waste, we need your help! Defend Ardenweald!", objectives = "" }
WordHunterWoW_QuestEN[60420] = { title = "A Call to Maldraxxus", description = "I'm glad you're here! We've got some problems in Maldraxxus.\n\nThe forces of Maldraxxus are the defenders of the Shadowlands. They've always managed to balance one another out, like actors on a stage, never stealing too much of the spotlight. \n\nBut now, some of the houses have overthrown the balance, and seek to conquer the rest of us!\n\nOur allies there need our help! Aid them however you can.", objectives = "" }
WordHunterWoW_QuestEN[60421] = { title = "A Call to Revendreth", description = "Oh, I'm glad you're here, we've got a problem!\n\nOur friends in Revendreth are struggling under the rule of Sire Denathrius. He was always a cruel leader, and now he's thrown in his lot with the Jailer! \n\nIf Denathrius's control of Revendreth isn't broken, he'll come for us next...\n\nLet's do whatever we can to help them out!", objectives = "" }
WordHunterWoW_QuestEN[60422] = { title = "A Call to Ardenweald", description = "We cannot stand alone. If one section of the Shadowlands falls, we will all be in danger.\n\nThe great soul-trees of Ardenweald are under assault from many foes that seek to harness their power.\n\nWe must aid our allies in the Night Fae, and punish their enemies for these transgressions.\n\nWe are stronger together.", objectives = "" }
WordHunterWoW_QuestEN[60423] = { title = "A Call to Ardenweald", description = "Ardenweald was once a place of peace and regrowth, now beset by dark forces from all sides. \n\nMaldraxxus alone is responsible for challenging those that would disrupt the cycle.\n\nTake our banners, steady your weapons, and bring war to Ardenweald.\n\nFor the Shadowlands.", objectives = "" }
WordHunterWoW_QuestEN[60424] = { title = "A Call to Ardenweald", description = "Ardenweald is one of our closest allies, and to them we ferry some of the most powerful souls.\n\nShould the weald fall, the devastation that would be unleashed could destroy us all.\n\nWe must aid the Winter Queen. It is the will of the Archon.\n\nGo now, and provide support to the Night Fae.", objectives = "" }
WordHunterWoW_QuestEN[60425] = { title = "Troubles at Home", description = "Sometimes we must look inward to find true darkness. Here, in Bastion, where once there was harmony, now we face many foes.\n\nToday, we root them out.\n\nHead into the golden fields, with your weapon in hand. Cleanse us of these foul creatures, aid our forces when they have need of you.\n\nIn the name of the Archon.", objectives = "" }
WordHunterWoW_QuestEN[60426] = { title = "A Call to Bastion", description = "We, the defenders of the Shadowlands, will never let a great foe go unchallenged.\n\nThe Kyrians of Bastion have long served all denizens of the Shadowlands by ferrying souls. We would be lost without their services.\n\nNow, they too are under attack from within. We must defend them in their time of need.\n\nGo now, and bring glory in the name of the Primus.", objectives = "" }
WordHunterWoW_QuestEN[60427] = { title = "A Call to Bastion", description = "The denizens of Bastion are a key component to the cycle of power here in the Shadowlands. Without them, we cannot replenish our ranks, and the forces of the Jailer will grow ever stronger.\n\nThey have their own troubles in these times, as well. Today, we must look without, and aid our allies.\n\nTravel to the golden fields, and rid them of their foes. \n\nOnly with allies do we stand a chance against Denathrius.", objectives = "" }
WordHunterWoW_QuestEN[60428] = { title = "The Blade of the Primus", description = "That's everything I need. Time to get to work.\n\nI'd stay close, if I were you. Forging a weapon is never a simple task when the Primus's handiwork is involved.\n\nIf he taught me anything, it was to expect the unexpected.", objectives = "" }
WordHunterWoW_QuestEN[60429] = { title = "Troubles at Home", description = "Look! Look around you! All around us, foes await the crushing hand of victory.\n\nThere is an upset in the balance of power, and with it, the defenders of the Shadowlands are weakened.\n\nThe only cure is more combat!\n\nChallenge the houses that sought to disrupt Maldraxxus, bring them to heel under the weight of your boots.", objectives = "" }
WordHunterWoW_QuestEN[60430] = { title = "A Call to Maldraxxus", description = "The forces of Maldraxxus have long defended the Shadowlands from threats outside of our lands.\n\nNow, they face their greatest threats from within. The balance of power between the houses is broken. It has led them to assault us, and others.\n\nTheir problems are many, our solutions are just. \n\nTravel to Maldraxxus and slay those that would do the Shadowlands harm, providing shelter to your allies when you find them.", objectives = "" }
WordHunterWoW_QuestEN[60431] = { title = "A Call to Maldraxxus", description = "The forces of Maldraxxus were once intended to defend the Shadowlands against threats from beyond. They are all but broken, now.\n\nThe houses are in disarray, infighting with one another. We have few allies there, and those that have sided with us are bruised and beaten.\n\nGo now, aid them, and slay their foes. Bring balance back to Maldraxxus, and in turn, will they aid us.", objectives = "" }
WordHunterWoW_QuestEN[60432] = { title = "Troubles at Home", description = "There are many tasks that need your attention outside of the walls of Sinfall.\n\nOur closest allies are under assault from all sides, and the forces of Denathrius are unrelenting.\n\nTake your weapon and steel yourself. Today, we defend Revendreth, and in doing so, further bulwark ourselves against our enemies.\n\nWe will take back what is ours.", objectives = "" }
WordHunterWoW_QuestEN[60433] = { title = "A Call to Revendreth", description = "We fight not only for might and glory, but for the greater good of the Shadowlands. It is our calling to bring war upon those that would disrupt the flow of souls.\n\nThere is one such betrayer - Sire Denathrius.\n\nBring the vengeance of Maldraxxus down upon his foul crown. \n\nSlay his allies, serve his foes, end his reign in carnage.", objectives = "" }
WordHunterWoW_QuestEN[60434] = { title = "A Call to Revendreth", description = "We all serve the greater purpose here, even those in Revendreth that we may not agree with. We take souls to them in need of a harsher form of cleansing, and it is just.\n\nYet Sire Denathrius has gone too far, and now seeks to control all of the Shadowlands.\n\nWe have friends there, amongst the Venthyr. Aid them, and put their enemies to rest.\n\nThe Word of the Archon is with you.", objectives = "" }
WordHunterWoW_QuestEN[60435] = { title = "Challenges in Revendreth", description = "We never truly counted the forces of Denathrius as our allies, and now he has shown his true colors.\n\nOver many years, he has built an army. One capable of destroying any other land, provided we were divided, and not united. He has empowered monstrous creations and broken them to his will.\n\nWhat better way to secure our allies and test our strength, than to eliminate his most fervent champions.\n\nGo now, and hunt.", objectives = "" }
WordHunterWoW_QuestEN[60436] = { title = "Challenges in Maldraxxus", description = "Maldraxxus is a land of conflict and strife. There is little better place than to test yourself against the might of the Shadowlands.\n\nThere, you will find warriors that are bred on combat, honed by the sword and hammer, tested in arenas and battlegrounds.\n\nCrash into them like the felling of a great branch, let them see the might of Ardenweald is no less terrifying.", objectives = "" }
WordHunterWoW_QuestEN[60437] = { title = "Challenges in Bastion", description = "Bastion has long been one of our closest allies, and a key to the inner workings of the Shadowlands. We cannot abide dysfunctions in the passage of souls.\n\nThey are beset by a host of issues brought on by dissension in their ranks. Every day, doubt gnaws at their forces, bleeding away their hope, and plunging us further into chaos.\n\nDoubt is a powerful foe, and not easily dispatched. Keep your wits about you and crush these dark thoughts.", objectives = "" }
WordHunterWoW_QuestEN[60438] = { title = "Challenges in Ardenweald", description = "The Wild Hunt count as our prey the most dangerous creatures in the weald. Here, you may test yourself against challenges the likes of which you may not have faced in your previous life.\n\nIn our current state, my gravest concern is with Tirna Scithe. Once full of life, it is now overtaken by multitudes of foul creatures. They siphon its power, and though we may never regain the glade, we must not allow this to continue.\n\nTake on this trial, and put an end to the invaders of Tirna Scithe.", objectives = "" }
WordHunterWoW_QuestEN[60439] = { title = "Challenges in Ardenweald", description = "Our close companions in Ardenweald face challenges unlike any that have previously plagued their peaceful glades.\n\nReady your weapons, for now is the time that the golden shields of Bastion shine. Now is the time to take flight into the weald and show courage in the face of darkness.\n\nIt is not always about us, you see. True courage means fighting for others when necessary, even against overwhelming odds and the most vile of evils.\n\nLight shines only in darkness.", objectives = "" }
WordHunterWoW_QuestEN[60440] = { title = "Challenges in Ardenweald", description = "Looking to prove yourself? I hear there are powerful creatures invading Ardenweald. Sounds like a challenge, no?\n\nSo ready your weapon and get out there! What better place to prove your might?\n\nSmash them to pieces, in the name of Maldraxxus!", objectives = "" }
WordHunterWoW_QuestEN[60441] = { title = "Challenges in Ardenweald", description = "Ardenweald was once a place of peace and regrowth, but no longer.\n\nFoes assault the weald from all sides, dark creatures that serve no masters.\n\nThey will not be exempted from the hand of justice. We will bring the trials of Revendreth to bear upon them.\n\nThey will see what we do to those that must be broken.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", objectives = "" }
WordHunterWoW_QuestEN[60442] = { title = "Challenges in Bastion", description = "Sometimes we need look no further than our own golden hills to find a suitable challenge.\n\nDoubt has crept into the minds of some of the most stoic shieldbearers of the Kyrian people. It has poisoned them against us, and in doing so, harmed the ability of the Shadowlands to heal from this blight.\n\nWe must stand against them, now. \n\nIt will not be easy, but things that are worth fighting for rarely are.", objectives = "" }
WordHunterWoW_QuestEN[60443] = { title = "Challenges in Bastion", description = "We consider the denizens of Bastion to be allies of a sort. Without their service, we would have no souls, and without souls, we could not raise armies, and without armies, we could not smash our fists against one another in the glorious theatre of battle!\n\n<Grandmaster Volo laughs and smashes his weapon around.>\n\nWe must aid them against their foes, or else the arena will sit barren, and we can't have that!\n\nFind their greatest enemies and turn their bones into golden dust.", objectives = "" }
WordHunterWoW_QuestEN[60444] = { title = "Challenges in Bastion", description = "Our allies in Bastion have long served the cycle of the Shadowlands, delivering souls in need of our services.\n\nYet, within their ranks, doubt has grown and festered. If this continues, we will all pay.\n\nTheir loss of focus shall not be allowed to continue. We will punish their wandering hearts.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", objectives = "" }
WordHunterWoW_QuestEN[60445] = { title = "Challenges in Maldraxxus", description = "The purpose of Maldraxxus is to raise the most competent and confident warriors that the Shadowlands has ever seen, to create the perfect army in order to defend us against threats from the outer worlds.\n\nHere, you will find some of your greatest challenges.\n\nSeek out the champions of the strongest houses, stand against them, and let them see your might.", objectives = "" }
WordHunterWoW_QuestEN[60446] = { title = "Challenges in Maldraxxus", description = "Those of Maldraxxus are the chosen warriors of the Shadowlands, charged with defending us against threats from other worlds.\n\nFor many years, a careful balance has been maintained between the houses. Now, there are those that have broken this balance, and we are all left weakened and defenseless.\n\nThey must pay for these transgressions.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", objectives = "" }
WordHunterWoW_QuestEN[60447] = { title = "Challenges in Maldraxxus", description = "In Maldraxxus, the House of the Chosen have taken control of large swaths of land, upsetting the balance of power amongst the houses. To them flock the most seasoned gladiators and warriors.\n\nWhat better place to test yourself?\n\nHead into the land of bones and blood, and stand against their most powerful minions. Prove true what you know to be inside of yourself.", objectives = "" }
WordHunterWoW_QuestEN[60448] = { title = "Challenges in Revendreth", description = "Those that have taken up arms against us in the name of Sire Denathrius and the Jailer have turned their backs on us all.\n\nSome are mere pawns in this game, others command them. Those that lead the charge of this crisis bear the greatest responsibility. \n\nThey are the mightiest of Denathrius's allies, and they must be brought to justice.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", objectives = "" }
WordHunterWoW_QuestEN[60449] = { title = "Challenges in Revendreth", description = "I've never really trusted the Venthyr of Revendreth. Maybe it's those long coats they wear, or maybe it's those pointy teeth, but something about them creeps me out.\n\nTheir leader, Denathrius, has sided with the Jailer against the rest of us, so I guess I was right.\n\nI want you to find his most powerful allies in Revendreth and smash them to a bloody pulp. Send him a message from Maldraxxus.", objectives = "" }
WordHunterWoW_QuestEN[60450] = { title = "Challenges in Revendreth", description = "Challenging oneself is a necessary part of ascension, for what is courage in the face of normalcy? \n\nIn this current state of unrest, opportunities abound to prove ourselves. Consider it the gilded lining to a tarnished shield.\n\nNone more so than in Revendreth, where Sire Denathrius has consolidated power and influence, and seeks to overthrow the natural order of the Shadowlands.\n\nAnd here is where you must challenge yourself today.", objectives = "" }
WordHunterWoW_QuestEN[60451] = { title = "Never Enough", description = "Well done, recruit. These were merely the first of many assignments in your future.\n\nMatters here demand my attention. Report to Baroness Draka and see what need she has of you.\n\nI will watch closely as this war unfolds.", objectives = "" }
WordHunterWoW_QuestEN[60452] = { title = "Storm the Maw", description = "Oh no, no no no. The Jailer's taken all the souls, and now he's also got a whole lot of anima! Who knows what he's going to do with it!\n\nYou need to go back there! You're the Maw Walker!\n\nSee what you can learn of his power, and slow him down however you can. I believe in you!\n\nBe careful, ok?", objectives = "" }
WordHunterWoW_QuestEN[60453] = { title = "The Path to Glory", description = "It's been some time since I had a chance to craft a weapon that powerful! Good to know that the skills I learned from the Primus haven't dulled.\n\nYou'd best get back to the baroness with that runeblade. I'm sure the margrave will want to know you wield it, as well.\n\nThe Primus was notorious for thinking ten paces ahead of everyone else. I suspect he knew that someone like you would take up that blade.", objectives = "" }
WordHunterWoW_QuestEN[60454] = { title = "Storm the Maw", description = "We have been able to do little to stem the flood of souls into the maw, until now. You, Maw Walker, have the power to put a stop to this.\n\nWe know little about the Jailer's lands, save that he is powerful beyond imagining.\n\nI ask something of you today that I would not place upon anyone else. You must travel to his lands, and do what you can to slow the growth of his forces.\n\nWe must buy more time.", objectives = "" }
WordHunterWoW_QuestEN[60455] = { title = "Storm the Maw", description = "We cannot allow the Jailer to grow in power. You alone can take the battle to his lands, and you must do so, or we will all fall.\n\nReturn to his lands, Maw Walker. He has already shown his hand, and we know he grows in power with each passing day.\n\nHis forces must be slowed, make what progress you can.", objectives = "" }
WordHunterWoW_QuestEN[60456] = { title = "Storm the Maw", description = "We know little about the maw, Maw Walker. Only you have the power to traverse those lands and return.\n\nWhat I am about to ask of you I would not dare ask of another.\n\nWe cannot allow the Jailer to grow in power. You must travel to the Maw and take the battle to his lands.\n\nMake what progress you can, we must slow down his forces however possible.", objectives = "" }
WordHunterWoW_QuestEN[60457] = { title = "Anima Salvage", description = "So many souls that should have been nurtured here have been lost to the Maw, it pains me to think of it.\n\nMaw Walker, we ask you now to do that which we cannot. Traverse the Jailer's domain, walk his barren fields, climb his accursed tower.\n\nBring us that which we lack.", objectives = "" }
WordHunterWoW_QuestEN[60458] = { title = "Anima Salvage", description = "When we ferried souls to the Arbiter, we never thought this would happen. We watched in despair as they were cast into the Maw, one by one, then by the hundreds and thousands.\n\nSouls that have been devoured, consumed, their anima lost to us. Return to us what you can.", objectives = "" }
WordHunterWoW_QuestEN[60459] = { title = "Anima Salvage", description = "The Arbiter has done us a great disservice. Our armies dwindle in number as souls are cast into the Maw instead of taking their place on the battlefields of Maldraxxus.\n\nThe Undying Army must not be snuffed out. If the Shadowlands are to survive, we must be able to supply our troops.\n\nTravel now into the Maw, Maw Walker, and enter Torghast. Return with Anima Embers to help kindle our supplies.", objectives = "" }
WordHunterWoW_QuestEN[60460] = { title = "Anima Salvage", description = "Revendreth is not a place that many souls choose to go, but it is a place that they must go. Here, their sins are laid bare before them, and they are broken and re-formed to function in our society.\n\nThis is a necessary part of the cycle.\n\nYet now, the cycle is broken, and are unable to serve our great purpose.\n\nIn order for us to do our work we require Anima. Travel to Torghast, Maw Walker, gather that which we can not. Without it, we wither and fade.", objectives = "" }
WordHunterWoW_QuestEN[60461] = { title = "Meet the Margrave", description = "Word of the runeblade has reached Margrave Krexus. He wishes to see it for himself.\n\nWith such a weapon by your side, you pose a threat that the other houses cannot ignore. Perhaps we can use that to our advantage.\n\nBut enough talk. Follow me.", objectives = "" }
WordHunterWoW_QuestEN[60462] = { title = "Anima Appeal", description = "Maw Walker!\n\nThe Anima Reservoir is nearly depleted. Without more anima, the groves shall soon wither and die.\n\nSearch the realms for additional nourishment and deliver it to the sanctum.\n\nArdenweald cannot continue without your aid!", objectives = "" }
WordHunterWoW_QuestEN[60463] = { title = "Anima Appeal", description = "Maw Walker!\n\nOur anima stores have run low, and soon we will have nothing to sate our thirst...\n\nSeek out additional sources of anima amongst the realms of the Shadowlands and deliver it to the sanctum.\n\nThese are dire circumstances. Our fate is in your hands.", objectives = "" }
WordHunterWoW_QuestEN[60464] = { title = "Anima Appeal", description = "Maw Walker!\n\nOur anima reserves are nearly depleted. Without an additional supply of anima, our mission of conquest will be lost!\n\nScour the realms for all the anima you can gather and deliver it here to the sanctum.\n\nVictory depends on your success!", objectives = "" }
WordHunterWoW_QuestEN[60465] = { title = "Anima Appeal", description = "Maw Walker!\n\nOur supply of anima is dwindling and the reservoir is nearly depleted. We must replenish our reserves before it is too late!\n\nSearch the realms for all the anima you can gather and deliver it to the sanctum.\n\nTime is short. Move swiftly, {class}.", objectives = "" }
WordHunterWoW_QuestEN[60466] = { title = "The Old Ways", description = "You there! Might I ask your help?\n\nI must confess, with the lack of new souls arriving, our supplies have dwindled. We lack the means to clothe arrivals in proper kyrian attire.\n\nBefore the forging of the centurions, aspirants trained against the native wildlife. Perhaps there is another way these beasts can prove useful.\n\nIf you collect materials from the cloudstriders and larions nearby, we can use them to ensure our new arrivals look the part.\n\nOh, and some thread from Mirene, if you would!", objectives = "" }
WordHunterWoW_QuestEN[60467] = { title = "A Rousing Aroma", description = "<Sabina is unresponsive. Her exposed flesh cracked and blistered. Perhaps something with a pungent aroma will rouse her.>", objectives = "" }
WordHunterWoW_QuestEN[60468] = { title = "Rubble Rummaging", description = "I do not know how long it's been since my captors left me here, but the Light has... taken its toll. \n\nYou must help me escape. The key to my shackles should be hidden nearby. Perhaps among the rubble? That's likely where I'd hide something small.", objectives = "" }
WordHunterWoW_QuestEN[60469] = { title = "Safe in the Shadows", description = "I cannot recollect what happened. Perhaps the Light has burdened my memory? Who knows how long I've been out here...\n\nThe last thing I remember before things went dark... my companions and I had finally found refuge in the shadows. I worry for their well-being. \n\nSo long as my assailants remain at large, my companions could be in danger. Will you find them and ensure they're still safe in the shadows?", objectives = "" }
WordHunterWoW_QuestEN[60470] = { title = "Setting Sabina Free", description = "Release me. Please, you must do so. I cannot linger in the Light any longer. \n\nThis unease, it's so... familiar, but it will pass. I will feel myself once again, once I have returned to the shade.\n\nI'll stay as still as silence while you work the lock.", objectives = "" }
WordHunterWoW_QuestEN[60480] = { title = "The Endmire", description = "Oi! You.\n\nNot sure what landed you in the Endmire but I need your help.\n\nSee these torches? It's my gig to keep 'em lit. But it ain't like they runnin' on flint n' tinder.\n\nMy stash of infused rubies got hauled off by some devourers when my back was turned. Can ya find 'em before we both get ate by one of these horrors?", objectives = "" }
WordHunterWoW_QuestEN[60482] = { title = "See With My Eyes", description = "After the destruction of our house, the spiders in this area become increasingly hostile. They expand their domain, and prey upon the few survivors that live here. \n\nThere are weapons we could use to help protect ourselves, but they lie hidden within the Sightless Hold, webbed over by the weavers that inhabit it now.\n\nJourney to the hold, use my sightless vision to see the weapons and recover what you can.", objectives = "" }
WordHunterWoW_QuestEN[60487] = { title = "It Used to Be Quiet Here", description = "Well... You don't look like the rest of 'em, do you?\n\n<Chiselgrump shrugs.>\n\nDoesn't bother me. Keep my head down and do my job, making sure these sinstones stay in good shape.\n\nKeep breaking my tools, though.\n\nBring me some more chisels and I'll teach you an old dredger construction trick.", objectives = "" }
WordHunterWoW_QuestEN[60489] = { title = "The Path of Ascension", description = "With the anima you collected, we can once again start up the Path of Ascension.\n\nThe eternal training ground of the kyrian, the Path is an ancient tradition and favored amongst many of the kyrian, aspirant and ascended alike.\n\nThe Hands of Courage, Apolon and Artemede, have stepped up to lead this tradition. Once you herald the Path's rebirth, speak to them to learn more.", objectives = "" }
WordHunterWoW_QuestEN[60491] = { title = "Among the Kyrian", description = "You will be well at home among the kyrian, brother. We welcome your aid.\n\nThe Archon was so confident in this outcome that she has arranged a grand reception for you in honor of your efforts against the Maldraxxus incursion into our realm.\n\nFor now, all you must do is journey to the Seat of Eternal Hymns. I shall meet you there.", objectives = "" }
WordHunterWoW_QuestEN[60492] = { title = "A Proper Reception", description = "Though the path you follow is not that of a traditional ascended, it is a kyrian path all the same.\n\nTo follow it is to bask in the footsteps of the innumerable lives before us, forever in service to a good far greater than we can achieve alone.\n\nTo join us amidst such strife is an accomplishment worthy of recognition. Our Archon has called all among us to join her in welcoming you to our ranks.", objectives = "" }
WordHunterWoW_QuestEN[60493] = { title = "Humble Gatherer", description = "Before your soulbinds step foot in the coliseum, you must challenge your first opponent.\n\nThere is a tradition to this, as with all things. You will need to gather specific items, then bring them back here to fashion armaments to help execute your challenge.\n\nIn the case of your first challenge, you will find the materials throughout Bastion. Return to me once you have collected everything, then we will continue.", objectives = "" }
WordHunterWoW_QuestEN[60494] = { title = "Your Friend, Dactylis", description = "With the materials you gathered, you are now ready to craft your lure.\n\nReport to Dactylis. She will be able to help you craft not only this, but many more items of all kinds later.\n\nOnce you craft your lure, return to me and I will give you your next instruction.", objectives = "" }
WordHunterWoW_QuestEN[60495] = { title = "A Suitable Opponent", description = "The opponents you train against in the coliseum are not physical beings, but rather manifestations of such.\n\nYour first opponent is one you and your soulbinds have met numerous times before -- the Ascended Kalisthene.\n\nAsking another kyrian to be your opponent in the Path is a great honor, as it tells them that you have much to learn from them.\n\nGo to Aspirant's Awakening and use the cores to summon Kalisthene by calling back to your first introduction. It is as ceremony states.", objectives = "" }
WordHunterWoW_QuestEN[60496] = { title = "Into the Coliseum", description = "The time of your challenge has come!\n\nAs you are not a being of Bastion, you shall act as a tactician for your soulbinds. You have developed mighty bonds between each other... let us see how they handle the coliseum.\n\nLet me know when you are ready to begin. Show us the merit of your bonds!", objectives = "" }
WordHunterWoW_QuestEN[60497] = { title = "Herald's Footpads", description = "Sometimes, sheer force of will is not enough. A piece of equipment can save your life.\n\nThis blueprint you found can teach you to craft your first piece of equipment.\n\nBring it over to Dactylis. She will be able to aid you in this as well.", objectives = "" }
WordHunterWoW_QuestEN[60498] = { title = "Overcoming the Trial", description = "These new footpads can give Pelagos the edge he may need to defeat Kalisthene.\n\nReturn to the Path, {name}. Equip Pelagos with these footpads and overcome your opponent.\n\nIt may take a few tries, but all trials do.\n\nGo in service, and in glory!", objectives = "" }
WordHunterWoW_QuestEN[60500] = { title = "Halls of Atonement: Medallion of Pride", description = "Our attempts at a parley were met with skepticism, at best. Acquiring the medallions may take more work than originally intended. However, not all hope is lost. \n\nI do believe that we can win over many of the Harvesters, and for those we cannot, a more direct approach will need to be taken. \n\nLord Chamberlain falls into this latter category. His medallion must be taken by force.", objectives = "" }
WordHunterWoW_QuestEN[60501] = { title = "Redemption for the Redeemer", description = "<Energies of death and innervation struggle to free themselves from the blade and consume you to your very core.>\n\n<The bonds of warding placed on this blade by Prince Renathal will not hold for long. It should be taken to Sinfall where more permanent arrangements have been made for this prisoner.>", objectives = "" }
WordHunterWoW_QuestEN[60502] = { title = "Sanguine Depths: An Ally Within", description = "There are whispers of a prisoner within these depths that may be of use to our cause. \n\nWhether this information can be relied upon is unknown. It is just as likely to be a trap, but still, we must investigate. \nWe cannot afford to ignore an opportunity such as this. \n\nVenture into the Sanguine Depths and recover this valuable prisoner.", objectives = "" }
WordHunterWoW_QuestEN[60504] = { title = "Strengthen the Bond", description = "To bond souls is but the first step. You must now explore its potential.\n\nJust as Pelagos will gain strength from you, so too shall you grow from him. As your bond grows over time you will touch deeper into one another's souls, and so your strength shall increase. \n\nAll you must do is place your hand upon the Forge of Bonds to augment your bond. There is no price to pay--the only limitation is your connection to our sacred covenant.", objectives = "" }
WordHunterWoW_QuestEN[60505] = { title = "Spider's Lair", description = "When our house fell in ruins, Manipulator Zalisar seized the opportunity to reform the house under his leadership. He found few followers and soon vanished into the ruins nearby. \n\nHe has begun to manipulate the spiders and train them to be his soldiers. Spiders under his control have begun to prey upon our forces. We need to deal with this threat before it grows any worse.\n\nI need you eliminate Manipulator Zalisar and his spider forces.", objectives = "" }
WordHunterWoW_QuestEN[60506] = { title = "The Accuser", description = "It is time to hunt our final prey, the Accuser.\n\nAnima drought or not, her sycophantic adherence to sacred \"rituals\" flies in the face of the Master's will. I can't wait to see the fear in her eyes.", objectives = "" }
WordHunterWoW_QuestEN[60508] = { title = "On the Trail", description = "In my visions, I witnessed Tyrande cutting through an endless storm of malevolent, nightmarish beings.\n\nUp ahead... is that...? Yes. I believe it is the very place I saw.\n\nCome. It may hold a clue as to where my mother has gone.", objectives = "" }
WordHunterWoW_QuestEN[60509] = { title = "Not My Job", description = "Right. So, 'em devourers are going to start creepin' out of the Endmire soon. \n\nAnd with the anima drought puttin' the squeeze to the fangs... well... we ain't gettin' help from them until it's too late.\n\nUs dredgers could use someone in your line of work. Professional destroyer as it were. \n\nIf you can spare the time, meet me out at the Dredgewood. We'll scoop up a couple of lads and see if we can't make a stand.", objectives = "" }
WordHunterWoW_QuestEN[60510] = { title = "Descended", description = "Though we have stopped the creation of more juggernauts, one of their most vile creations yet draws breath. It was born of one of the most pained souls they took from my temple in Bastion.\n\nAs I flew above their ranks I could hear their surgeons chanting its name above the din of combat--Woeblade. It is an affront to all the kyrian stand for, an atrocity beyond any other.\n\nMark it with the flames of courage when you engage, and we will help you destroy it.", objectives = "" }
WordHunterWoW_QuestEN[60514] = { title = "Hunting Trophies", description = "To be a hopebreaker is to conquer all prey, not just souls.\n\nThe Banewood is home to many dangerous creatures: deathwalkers, fearspinners, and the horrifying doomfangs. If you wish to really master the art of the hunt, you should be able to defeat these foes.\n\nBring me trophies as proof of your conquests. Then, you may just earn my respect.", objectives = "" }
WordHunterWoW_QuestEN[60519] = { title = "Audience with the Winter Queen", description = "Zephyrs herald the Queen's arrival. Hushed silence descends upon the grove.\n\nWait, watch, and speak when the time has come.", objectives = "" }
WordHunterWoW_QuestEN[60520] = { title = "Nightmares Manifest", description = "Oh, this isn't good. As soon as you left, the spirit's nightmares spilled out all over Tirna Vaal. \n\nI've done everything to try to soothe her. I've tried singing to her, I've tried telling her stories, but nothing I do seems to calm her.\n\nPlease, would you confront and dispel her nightmares? That might be the only thing that will work.", objectives = "" }
WordHunterWoW_QuestEN[60521] = { title = "Call of the Hunt", description = "You've done so much, but the Queen's focus is still divided across the forest.\n\nIf you want to deliver your message, then we need to help lessen her burden.\n\nLet's start with the Wild Hunt. They are the protectors of Ardenweald, and dealing with the threat of the masked fae has stretched them thin.\n\nSeek out Hunt-Captain Korayn at Glitterfall Basin. Last I heard, her hunting party could use reinforcements.\n\nAnd don't let her ferocity put you off. She's quite nice as long as you're not her prey!", objectives = "" }
WordHunterWoW_QuestEN[60522] = { title = "Return to Tirna Vaal", description = "We of the Wild Hunt are always prepared to return to the cycle in defense of Ardenweald.\n\nI must move on, and so should you. I advise you to return to Droman Tashmur in Tirna Vaal. Others will need your help.\n\nHere, take this. It is a gift and a thank you.\n\nHelping each other is the only way to survive this drought.", objectives = "" }
WordHunterWoW_QuestEN[60530] = { title = "The Sea of Souls", description = "Some force here seeks to keep us from finding Tyrande.\n\nThe trail of bodies seems to go into this... stream of souls. \n\nI suggest we split up. I will follow along the bank of the river. You enter its current and follow the trail.\n\nShould you need me, I will be close at hand.\n\nWe will find Tyrande, no matter where this course leads.", objectives = "" }
WordHunterWoW_QuestEN[60545] = { title = "Shadowlands: A Chilling Summons", description = "The time has come, {class}.\n\nHighlord Bolvar Fordragon requests your presence atop Icecrown Citadel. Meet me in Stormwind, and I will take you to him.\n\nI would not keep him waiting.", objectives = "" }
WordHunterWoW_QuestEN[60557] = { title = "First Time? You Have to Fight!", description = "When it comes to warfare, strength of will is as critical as strength of arms. A demoralized soldier is a defeated soldier!\n\nWe have the numbers to overwhelm the constructs with a full scale assault, but only if our forces are fully committed to the charge. Some may fall, but their sacrifice will secure our victory!\n\nTake this battle horn and rally our troops. Remind them of their duty to the Chosen!", objectives = "" }
WordHunterWoW_QuestEN[60559] = { title = "Unused", description = "", objectives = "" }
WordHunterWoW_QuestEN[60563] = { title = "Tending to Wildseeds", description = "We infuse wildseeds with anima from the animacones we collect in the surrounding area.\n\nBut the caretakers are missing, and we have wildseeds in need of an anima infusion.\n\nThis is an absolute mess that must be corrected before the Winter Queen arrives!\n\nI've already gathered a basket of animacones. Can you use them to infuse a few of the wildseeds?\n\nI'll show you how it's done, but then I have to look for the missing caretakers.", objectives = "" }
WordHunterWoW_QuestEN[60566] = { title = "Into the Light", description = "I am afraid that you must endure the next stretch of the stroll without me, {name}.\n\nWhile my compatriots and I have secured access to the elevator that shall carry us up to Sinfall, we are unable to utilize it.\n\nThe Master has redirected a massive beam of Light directly onto the elevator's landing.\n\nVenthyr that get close are obliterated.\n\nDredgers sent up never return.\n\nWe need someone who can walk in the Light to discover what is happening up there.\n\nLady Sybille will show you the way.", objectives = "" }
WordHunterWoW_QuestEN[60567] = { title = "Shooing Wildlife", description = "Things are chaotic here in the Tranquil Pools. I'd be devastated if the Winter Queen saw this.\n\nThis is meant to be a peaceful place where we give anima to wildseeds.\n\nBut with the current drought, starving beasts have encroached on the pools and are trying to feed on the anima themselves.\n\nSadly, we need to put them down... or else they may endanger the spirits within the wildseeds.", objectives = "" }
WordHunterWoW_QuestEN[60572] = { title = "For the Sake of Spirit", description = "With all of the anima you recovered from Tirna Noch, it is only a matter of time before my grove becomes the target of every anima-seeking enemy of Ardenweald.\n\nI hope Dreamweaver knows what he is doing with this ritual.\n\nProceed quickly. Speak with Dreamweaver, and see what needs to be done to aid the spirit within the wildseed.", objectives = "" }
WordHunterWoW_QuestEN[60575] = { title = "Belly Full of Fae", description = "The local flora have gone somewhat wild during this anima drought.\n\nIt seems they swallowed most of the young fae who were tending to the wildseeds here.\n\nAt least now we know where they've been.\n\nOh, don't worry. This isn't the first time this has happened. We can last quite a while inside those plants.\n\nTake my dagger. Use it to cut through the shrubbery and free the other wildseed tenders.", objectives = "" }
WordHunterWoW_QuestEN[60577] = { title = "Hungry for Animacones", description = "I have to apologize for the state of the Tranquil Pools. Normally, it's quite peaceful here.\n\nThe wildseed tenders tell me that the plants you see walking around have eaten all the animacones intended for use in Tirna Vaal.\n\nCould you rip the animacones out of those plants?\n\nWe have wildseeds that are in need of that anima.", objectives = "" }
WordHunterWoW_QuestEN[60578] = { title = "Visions of the Dreamer: The Betrayal", description = "I sense that in the spirit's vision, she struggles with the memory of a betrayal that is truly profound. \n\nSomeone as close to her as a brother, turned to an enemy.\n\nGo to the second Dreamshrine in the Basin, and help vanquish the pain of this nightmare.", objectives = "" }
WordHunterWoW_QuestEN[60594] = { title = "One Special Spirit", description = "You've been a huge help to Tirna Vaal. I need to bring this anima to one of our newest wildseeds.\n\nI'd love for you to come with me. It's only fair, since you're the one who recovered the animacones.\n\nI'm quite excited for you! Let's go.", objectives = "" }
WordHunterWoW_QuestEN[60599] = { title = "Soul Shape", description = "", objectives = "" }
WordHunterWoW_QuestEN[60600] = { title = "Preparing for the Winter Queen", description = "Tirna Vaal is ready for the Winter Queen's arrival! And it's all thanks to you.\n\nYou have more than upheld your end of our bargain... and yet I was not able to do the same.\n\nThat is absolutely unacceptable for a faerie like me! What would the others think if they knew I had failed to honor our agreement?\n\nPlease, allow me to make it up to you. I may not have been able to deliver your message to the Queen, but I have a special surprise that I hope you'll accept instead!", objectives = "" }
WordHunterWoW_QuestEN[60605] = { title = "Glimmerfin Scale", description = "<A brightly-colored scale fell to the ground as the murloc ran off. It was unlike any other murloc you've seen in Northrend.\n\nPerhaps King Mrgl-Mrgl would know more about this new species?>", objectives = "" }
WordHunterWoW_QuestEN[60606] = { title = "Glimmerfin Welcome", description = "First thing's first, they're probably hungry. Life up here in the cold isn't quite as easy as it is elsewhere, and even the most acclimated murlocs sometimes have trouble finding food.\n\nWe're going to need to feed them, but also help them find food for themselves.\n\nThey're already watching you, so search the area around where you found the murlocs for food sources and show them what to hunt. Then bring the meat to their leader--just look for the biggest one.", objectives = "" }
WordHunterWoW_QuestEN[60614] = { title = "A Big Horkin' Task", description = "<Glimmergut begins to draw in the sand.\n\nThe murloc traces the outline of what appears to be a large seal. He points at the picture, then upwards, indicating that the creature must be somewhere on the surface of the water.\n\nThe murloc then digs a small, shallow hole in the sand, and points at it several times.>\n\nMrg! Mrg! Grml.\n\n<He cocks his head expectantly.>", objectives = "" }
WordHunterWoW_QuestEN[60615] = { title = "Seer of the Waves", description = "<Glimmergut points across the ship. He wants you to take the blubber to someone.>\n\nMrg m'grrl.", objectives = "" }
WordHunterWoW_QuestEN[60616] = { title = "Pearl in the Deeps", description = "<The oracle draws a circle in the sand, then points down into the deeps. There is something round down there that she is after, perhaps a pearl or stone?\n\nThe oracle motions for you to wait a moment before you leave. She waves her hands around frantically, then places them under her mouth, mimicking two large fangs.\n\nYou take this as a warning that there may be something waiting for you in the icy darkness.>", objectives = "" }
WordHunterWoW_QuestEN[60617] = { title = "Trainer's Test", description = "<The oracle finishes peering into the pearl and turns to face you. She appears to be deep in thought, staring directly at you and blinking a few times.\n\nFinally, she nods. \n\nThe oracle points at you, then points upwards. She places a hand a small distance above the ground, indicating something pet-sized.\n\nYour surmise that there may be test of your connection with your battle pets ahead.>", objectives = "" }
WordHunterWoW_QuestEN[60619] = { title = "Wrap it Up", description = "<The seems quite excited about the presence of the new egg. You get the sense that this is an important occasion for these murlocs--there may be few eggs left.\n\nThe oracle waves a small piece of seaweed in front of you, showing you the young buds of the immature plant.\n\nShe warps the seaweed around a small part of the egg, then points at you, then back at the wrapped seaweed.\n\nIt appears that the egg needs to be wrapped in more immature seaweed stalks.>", objectives = "" }
WordHunterWoW_QuestEN[60620] = { title = "Guardian of the Smallest", description = "<The oracle pats you on the shoulder, and seems quite pleased with all that you've done.\n\nShe holds up one finger, then spreads her hands wide and emits a terrible roar-like murgle.\n\nShe points outside, then at you, then your weapon, then nods seriously.\n\nThere must be one more trial to await you. It would appear to be a test of strength.>", objectives = "" }
WordHunterWoW_QuestEN[60621] = { title = "Enemies at the Gates", description = "Lorkron is here. \n\nI tracked him all the way from the Glittering Falls. Then I saw the Drust try to flank our forces.\n\nI'd say they were rather surprised that we turned the tables against them.\n\n<Korayn's smile is fierce. She lifts her weapon and her voice to address all present.>\n\nHuntsmen and huntresses, with me! We ride to defend the grove! Take no prisoners and leave none standing!", objectives = "" }
WordHunterWoW_QuestEN[60622] = { title = "Eye of the Scryer", description = "Evading the Mawsworn's scryers requires powerful magical countermeasures.\n\nThe prime reagent? A luminescent eye, pried from the skull of a scryer recently shaken from its trance.\n\nThe scrying ritual begins as we speak. You will, of course, be compensated only for an intact eye.\n\nRestraint is advised in its procurement.", objectives = "" }
WordHunterWoW_QuestEN[60624] = { title = "Ride to Heartwood Grove", description = "A storm of strife and fear rains down upon Heartwood Grove. Sylvar flee from the flood.\n\nBrave the torrent astride a stag. Becalm the deluge and be the salvation of those who would drown.\n\nMake haste. Time wanes.", objectives = "" }
WordHunterWoW_QuestEN[60628] = { title = "The Missing Hunters", description = "Strange creatures have been seen lurking just outside the grove. Terrible, ugly things.\n\nWhatever they might be, they are not native to Ardenweald. \n\nIt does not matter how they breached our borders, though. Every one of them must be eliminated.\n\nI sent my best huntsmen and huntresses to slay them, but not one has returned. See if you can determine what has delayed them.", objectives = "" }
WordHunterWoW_QuestEN[60629] = { title = "Extreme Recycling", description = "The Wild Hunt serves the Winter Queen under the leadership of Lord Herne. We are elite fighters, hunters, and trackers.\n\nBut we cannot fight without weapons and supplies. The droman here informs me that there are severe obstacles to their delivery.\n\nI do not have time to wait. We need equipment, and we need it now.\n\nSee what you can scavenge from the field. A broken weapon can always be mended and put to use again.", objectives = "" }
WordHunterWoW_QuestEN[60630] = { title = "Totem Eclipse", description = "I can smell our foes' dark magic, twisting the air and muddling my mind. They are up to something. Bringing awful powers into Ardenweald.\n\nIf you see any of their totems, destroy them immediately. \n\nI always feel better after smashing something to pieces, don't you?", objectives = "" }
WordHunterWoW_QuestEN[60631] = { title = "Big Problem, Little Vorkai", description = "Ara'lon's report matches what I have seen. Too many enemies, and too few of the Wild Hunt to dispose of them on our own.\n\nFortunately, I feel strongly inclined to take matters into my own hands. And avenge my fallen hunters. \n\nLet us depart. We will show those monsters the fury of nature.", objectives = "" }
WordHunterWoW_QuestEN[60632] = { title = "I Know Your Face", description = "This voice... I have heard it before. Though it is distorted and vengeful now.\n\nHe hunts us.\n\nBut I am not prey. And I will not let him gloat over his slain quarry. That is not the way of the Wild Hunt.\n\nThough he may draw us to ground of his choosing, we will fight him.\n\nAnd we will win. Are you with me?", objectives = "" }
WordHunterWoW_QuestEN[60637] = { title = "The End of Former Friends", description = "Heartwood Grove was to give up its anima so that other groves could survive.\n\nBut then... I started seeing these masks on many of the other fae. Soon, everyone was wearing them.\n\nI don't know what has come over them, but it's clear they mean us harm. Please... you have to...\n\nThey aren't the friends I once knew. Not anymore.", objectives = "" }
WordHunterWoW_QuestEN[60638] = { title = "Recovering Wildseeds", description = "One of my tasks in Heartwood Grove was to tend to the wildseeds.\n\nSome were chosen to be brought back to Tirna Vaal. But now the masked fae are draining the anima from them!\n\nWe need to save the ones that remain. I beg of you, recover any surviving wildseeds you can find.\n\nThe spirits within them were chosen to be reborn. I won't let them wither away!", objectives = "" }
WordHunterWoW_QuestEN[60639] = { title = "Heart of the Grove", description = "We were supposed to take the heart of the grove to Tirna Vaal when we left this place to wither.\n\nThe masked fae struck before that could happen. They must be after the heart of the grove!\n\nThe heart contains all of the anima that was meant to save the other groves. We can't afford to lose it.\n\nCan you secure it? I need to find Korenth, one of our healers. His skills will help any survivors we find.", objectives = "" }
WordHunterWoW_QuestEN[60640] = { title = "Regrowth of the Grove", description = "The grove thrives, my mortal friend, but there is yet room for it to grow.\n\nWith enough anima, it can nourish even more wildseeds at once. Each one is a spirit that might otherwise be lost forever.\n\nSpeak with Zayhad once again, and see to the regrowth of the conservatory.", objectives = "" }
WordHunterWoW_QuestEN[60641] = { title = "Blossoming of the Grove", description = "The conservatory grows hearty and hale. Now, it must blossom anew.\n\nThough it requires much in the way of anima, every additional spirit that the conservatory rebirths returns your generosity tenfold.\n\nConfer with Zayhad, so that this conservatory may grow ever larger.", objectives = "" }
WordHunterWoW_QuestEN[60642] = { title = "The Grove Resplendent", description = "You have done much to return the conservatory to its former splendor.\n\nIn ages past, this grove was a place of convalescence for spirits who were wounded upon their demise, and needed special care before being reborn.\n\nIt was a place rarely used... but now, it is critical to the continuation of the cycle.\n\nTell Zayhad that the time has come. The Queen's Conservatory must thrive for the good of Ardenweald.", objectives = "" }
WordHunterWoW_QuestEN[60643] = { title = "[OLD NOT USED]", description = ".", objectives = "" }
WordHunterWoW_QuestEN[60644] = { title = "Draw Out the Darkness", description = "Now that we have the dagger, it will take the combined will of all of us to sever the weapon's link to the High Chieftain. \n\nJaina, Anduin, and I must do our part to keep Baine's spirit grounded, so it will be up to you to deal with whatever force is unleashed when the blade is broken.\n\nAre you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[60645] = { title = "Gargantuan Seeker", description = "", objectives = "" }
WordHunterWoW_QuestEN[60646] = { title = "Misery Business", description = "The Mawsworn have begun harvesting the misery of the souls flowing through Gorgoa, the river of souls.\n\nWhy? I do not know yet. But it behooves us to stop them.\n\nDestroy the conduits that they deposit the misery into and bring me some samples of their work. \n\nPerhaps with some research, I can discern their intentions.", objectives = "" }
WordHunterWoW_QuestEN[60647] = { title = "Recovering the Animacones", description = "The grove's droman is wearing one of the masks. I fear he's going to drain all of the anima from the grove's heart!\n\nThat anima is meant for the forest's other groves. If we lose it... then Heartwood Grove would have been lost for nothing...\n\nWe'll carve a path to the Shrouded Mire to find the droman before it's too late.\n\nMany of these masked fae have stolen Heartwood Grove's animacones. We must recover them along the way. \n\nIn this drought, every bit of anima is precious.", objectives = "" }
WordHunterWoW_QuestEN[60648] = { title = "Survivors of Heartwood Grove", description = "Korenth... I can't believe he's...\n\nWe have to save whomever we can. Droman Krelnor is too strong for us to face alone.\n\nI saw a few other survivors scattered around the grove. Hurry, we have no time to waste!", objectives = "" }
WordHunterWoW_QuestEN[60651] = { title = "Champion: Meatball", description = "", objectives = "" }
WordHunterWoW_QuestEN[60660] = { title = "Flight Test", description = "I fix these to my arms... then they become wings, yes?\n\nThen I jump off cliff. And fly!\n\nYou watch?", objectives = "" }
WordHunterWoW_QuestEN[60661] = { title = "Dying Dreams", description = "We have lost so much... and this one is special.\n\n<Moonberry looks at you, resolute. Her voice is strangely formal, her manner commanding.>\n\nCome, {name}. We will carry her on the Path of Rebirth and entreat the Queen to save her.\n\nHurry and make preparations. We have little time.", objectives = "" }
WordHunterWoW_QuestEN[60669] = { title = "Cause for Distraction", description = "The Horde has come under siege, {name}.\n\nThe undead Scourge rises like a grim tide, in numbers not seen since Arthas Menethil sat upon the frozen throne. \n\nAnd as if that were not concerning enough... something terrible has occurred.\n\nWhat I am about to tell you, I share in the strictest confidence. This information will be known by all soon enough, but I needed to speak with you directly first.\n\nAllow me to explain.", objectives = "" }
WordHunterWoW_QuestEN[60670] = { title = "Return of the Crusade", description = "I have witnessed the relentless advance of the Scourge firsthand. It is only a matter of time before they swarm our gates. \n\nThe fate that befell Silvermoon must never be repeated. \n\nDeath knights from the Ebon Blade have stepped forward to combat the threat, but even they will need reinforcements.\n\nThe Argent Crusade has answered the call once more. I ask that you aid them in keeping our people safe, {name}.\n\nTheir commander awaits your arrival.", objectives = "" }
WordHunterWoW_QuestEN[60671] = { title = "The Sacrifices We Must Make", description = "Hurry! We can use the animacones we gathered to save Derawyn.\n\nI know they're intended for the wildseeds... but we can't let these monsters take anyone else from us.", objectives = "" }
WordHunterWoW_QuestEN[60673] = { title = "The Traitor", description = "Right, looks like I should let you in now.\n\nCan't promise Mateo will be too kind though. I prefer my old boss, but don't tell him that.\n\nWonder what happened to her. Denathrius seemed awfully upset when they last spoke.\n\nAnyways, let me just get that door open for ya.", objectives = "" }
WordHunterWoW_QuestEN[60709] = { title = "Recovering the Heart", description = "Darkness grasps the heart of Droman Krelnor, as he grasps the heart of the grove.\n\nAnima drains from the heart, nectar taken from ripened fruit. It must be stopped.\n\nFoul magic bars the way. Anima in peril, anima the salvation.\n\nBeseech Te'zan. An old soul, brimming with anima, the spark to ignite our hope.", objectives = "" }
WordHunterWoW_QuestEN[60721] = { title = "The Anima Must Flow", description = "This device you see here can be used to send anima to the thirsting wards, aiding our people.\n\nAs each ward regains its flow of anima, it will begin to flourish. You may find those that live there ready to aid you in your journeys, or you may even find new challenges that await you.\n\nOnce you have brought some anima to our sanctum, use the device to direct it to a ward, and see the results for yourself.", objectives = "" }
WordHunterWoW_QuestEN[60722] = { title = "Tower Power", description = "This device is used to channel anima to our towers across Maldraxxus, empowering our forces stationed at them.\n\nThough you may find the support they offer useful, bear in mind that the anima will likely attract the attention of our foes.\n\nUse the device to direct our stores of anima toward one of our towers. You will soon see what true power can accomplish.", objectives = "" }
WordHunterWoW_QuestEN[60723] = { title = "The Roots Thirst", description = "This device can soak the roots of our great canopy in anima. The branches thirst for it.\n\nAs each of the great trunks is filled with anima, it will begin to bloom once more. You may find those under its boughs ready to aid you, or you may find new challenges that await you in the shade.\n\nNow, bring anima to the sanctum, and use the device to direct it out into the weald. Let the blooms flourish once more.", objectives = "" }
WordHunterWoW_QuestEN[60724] = { title = "Heartless", description = "So many of my friends have returned to the cycle... all because of those strange masks.\n\nWhy did they take my friends? What was the point of destroying the heart of my grove?\n\nYou have to return to Tirna Vaal and tell Droman Tashmur what happened here. \n\nI'll make my way there eventually. I just... need some time to say goodbye.", objectives = "" }
WordHunterWoW_QuestEN[60725] = { title = "Field Reports", description = "We cannot anticipate where and when the Scourge will strike.\n\nIn order to mount a defense, the Argent Crusade has set up outposts at several key locations. But we have yet to receive word from them.\n\nSeek out my field officers along the southern road. I expect a full report when you return.", objectives = "" }
WordHunterWoW_QuestEN[60726] = { title = "[OLD NOT USED]", description = "[OLD NOT USED]", objectives = "" }
WordHunterWoW_QuestEN[60727] = { title = "A Message from Icecrown", description = "Our forces in Northrend have sent word. Justicar Trueheart requests our immediate assistance.\n\nWe must respond to this summons at once, no matter what terrors await us in Icecrown.\n\nA {class} like you would do much to bolster our chances on the battlefield.\n\nYou have my word that Orgrimmar will be protected in your absence.\n\nBattle calls, {name}. I trust you are ready.", objectives = "" }
WordHunterWoW_QuestEN[60732] = { title = "Disrupting the Flow", description = "<The tortured embodiment of the soul before you burns with magmatic flame. Whatever purpose it was meant for here in the cauldron has since been served.\n\nThe complete disregard for the remaining husk of this soul is unsettling. These efforts will continue if something isn't done.\n\nSend the inhabitants of Zovaal's Cauldron a message.>", objectives = "" }
WordHunterWoW_QuestEN[60733] = { title = "Front and Center", description = "The runes on that blade... they are the same as the ones etched on the door to the Seat of the Primus. \n\nAnd one of them just began to glow...\n\nIs this what I think it is, {name}? Do you have the means to unseal the Seat? \n\nIf so, then perhaps Vyraz's gambit was not for nothing. This could turn the tide of the entire war!", objectives = "" }
WordHunterWoW_QuestEN[60735] = { title = "Trouble in Paradise", description = "I have given your presence here some thought, {name}.\n\nIt is clear to me that you are no ordinary arrival from Oribos. I do not know why you are here, nor what you hope to achieve. That alone is simply unprecedented.\n\nYou must understand... individuals do not merely come to Bastion on a whim. This fate is earned, and those that are chosen for it are uniquely suited to this existence.\n\nSo... I ask you... why are you here, truly?", objectives = "" }
WordHunterWoW_QuestEN[60736] = { title = "Quest 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[60737] = { title = "The Door to the Unknown", description = "You empowered the final rune? Then we might yet turn the tide of battle!\n\nOpen the door, {name}! We'll hold the enemy back as long as we can!", objectives = "" }
WordHunterWoW_QuestEN[60738] = { title = "The Way to Hibernal Hollow", description = "I've never seen a wildseed quite like this one. Even the ones that bonded with their caretakers in the past never manifested nightmares like this.\n\nThen again, we've also never had a living mortal in our midst.\n\nWe need to bring this wildseed to Hibernal Hollow. There it can receive the care and attention it needs.\n\nI'll place it into the spirit cradle. Can you ask Niya if she would accompany you?\n\nThe poor sylvar has been directionless since the fall of her grove. This would be good for her.", objectives = "" }
WordHunterWoW_QuestEN[60759] = { title = "Damned Intruders", description = "It is imperative that these reports reach Commander Throgg, but we are hard-pressed to defend the Crossroads.\n\nBefore you depart, I ask that you aid us in thinning the Scourge's numbers. It may grant us the reprieve we need.", objectives = "" }
WordHunterWoW_QuestEN[60761] = { title = "Return of the Scourge", description = "Deliver these reports to Commander Throgg. He must be told of the full extent of the threat we face.\n\nIf we fail to hold the line against the Scourge... then Light help us all.", objectives = "" }
WordHunterWoW_QuestEN[60762] = { title = "Death Motes", description = "I have a task for you, Maw Walker.\n\nSouls deemed suitable for service among the Mawsworn are broken down to their barest essence. The resulting creature forms a black shade, devoid of all individual will.\n\nIt is a tragic end.\n\nI wish to better understand this process--what is it about a soul that causes this transformation?\n\nFragments of broken souls rain down across Ruin's Cradle. Bring me some of them, so that I might learn more about our common adversaries.", objectives = "" }
WordHunterWoW_QuestEN[60763] = { title = "I Moustache You to Lend a Hand", description = "A message from the Primus of Maldraxxus, you say? We haven't heard from him in... Well, it's been a long time.\n\nThis isn't a prank, is it? The Queen doesn't have time for pranks. But I do!\n\n<Moonberry leans in close and whispers to you.>\n\nAnd for this one, I think we need one more lily.\n\n<Moonberry winks.>\n\nLet me take a look at this message. You bring that last night lily to Featherlight, and then we'll talk.", objectives = "" }
WordHunterWoW_QuestEN[60764] = { title = "Soothing Song", description = "I will fly ahead to Hibernal Hollow and convince the Droman Aliothe to help us. Hopefully she will have agreed by the time you and Niya arrive.\n\nThis wildseed seems to take comfort in your presence, so you'll need to stick close to it.\n\nNiya will also need to sing to the wildseed to keep it calm... or else the nightmares may return.\n\nSpriggans love to interrupt our songs, so be on the lookout for them.\n\nLet me know when you're ready to head off.", objectives = "" }
WordHunterWoW_QuestEN[60765] = { title = "Cure For All Ills", description = "Many survivors from the House of Plagues are still in need help. Their suffering fills me with great sadness.\n\nMaw Walker, I'd do anything to help them. Even saving a few is better than saving none.\n\nPlease, help me cure them!", objectives = "" }
WordHunterWoW_QuestEN[60766] = { title = "Damned Intruders", description = "Before you depart... we are in desperate need of reinforcements.\n\nThese reports must reach Commander Gregor. But if you would help us thin the Scourge's numbers first, it would grant us a much needed reprieve.", objectives = "" }
WordHunterWoW_QuestEN[60767] = { title = "Return of the Scourge", description = "Deliver my report to Commander Gregor. He must be informed of what we are up against. \n\nThe Scourge's numbers are on the rise, and if they do not abate... then the Light help us all.", objectives = "" }
WordHunterWoW_QuestEN[60775] = { title = "A Suitable Demise", description = "Surviving in this miserable place has been difficult, but I must confess... sending a few Mawsworn to a suitable demise does bring me joy.\n\nThe soulforgers in Zovaal's Cauldron are among the cruelest minions the Jailer employs. I find satisfaction in disposing of their cores in the very forges which they maintain.\n\nThis of course has the added benefit of temporarily slowing down their arms production, if you require more sober justification for your actions.", objectives = "" }
WordHunterWoW_QuestEN[60778] = { title = "Wildseed Rescue", description = "<Featherlight checks his notes.>\n\nLet's see... There was a request for help regarding an imperiled wildseed and... something about an egg? The original note wasn't entirely clear, but the fae who sent it was... Ah! It was Korenth. Again.\n\nWell, I suppose we'll find out what his trouble is soon enough!\n\nI'll fly ahead and look for him. Stick to the path.", objectives = "" }
WordHunterWoW_QuestEN[60827] = { title = "Advancing the Effort", description = "While the other crusaders regain control of the tournament grounds, you and I must press on.\n\nOur forces previously attempted to set up a forward camp farther into Icecrown, but they were overrun.\n\nWith you by our side, I am confident we can reclaim the area.", objectives = "" }
WordHunterWoW_QuestEN[60828] = { title = "A New Foothold", description = "Our preparations are complete. It is time we take the fight to the Scourge.\n\nJusticar Trueheart has tasked me with leading our efforts at the forward camp.\n\nMeet me there and we shall continue our work together.", objectives = "" }
WordHunterWoW_QuestEN[60831] = { title = "Fit For a Margrave", description = "We're finally ready, my apprentice. We shall craft our greatest potion!\n\nThough what the potion is meant for escapes me, I'm simply so proud of your progress. Margrave Stradama will be thrilled by your achievements!\n\nCome, now. Let's present what we've made to her!", objectives = "" }
WordHunterWoW_QuestEN[60839] = { title = "Remnants of the Wild Hunt", description = "The Wild Hunt is holding the line against these monsters, lest they overrun the road to Hibernal Hollow.\n\nToo many of my fellow hunters have been possessed by the dark magic of those twisted masks.\n\nBut with you here, we might be able to turn the tide. \n\nAid any hunters you can find before our foes turn them against us.\n\nI will meet you farther within the meadow. If we rally our numbers, we can bring an end to this battle.", objectives = "" }
WordHunterWoW_QuestEN[60841] = { title = "Evacuation Effort", description = "Our forces are in danger, and the fault is my own. Believing that the surrounding area was safe, I sent a small team to secure the abandoned camp in the valley to the southwest.\n\nBut our field reports were outdated or mistaken. The camp is a lost cause. We must now focus on rescuing those whom I assigned to it.\n\nHead for the camp. Do what you can to save our allies.", objectives = "" }
WordHunterWoW_QuestEN[60843] = { title = "Cult Couture", description = "Though our scouts have been able to infiltrate the cultist forces at Aldur'thar, sneaking into Mord'rethar has proven all but impossible.\n\nPerhaps it is time to explore other methods of ingress.\n\nStart by investigating the cult's nearby ritual chambers. You may find something of use.", objectives = "" }
WordHunterWoW_QuestEN[60856] = { title = "Toppling the Brute", description = "A nearby monstrosity has been thwarting our efforts to clear the meadow.\n\nTogether, we can bring it down.\n\nYou and I will face off against the beast. When the time is right, I will call for the hunt to charge.\n\nThe Wild Hunt has suffered too many losses. Today we will claim victory against these monsters!", objectives = "" }
WordHunterWoW_QuestEN[60857] = { title = "We Can't Save Them All", description = "I am surprised--but pleased--that you weren't torn to pieces! Well done.\n\nBut now... I fear we have a far more serious task to complete.\n\nThe Winter Queen has decreed that Heartwood Grove's anima is to be reclaimed, and its denizens must leave it to wither. Not all of their wildseeds will go with them. In fact, only a few have been chosen to be saved.\n\nWe are to bring the final list to Droman Krelnor.", objectives = "" }
WordHunterWoW_QuestEN[60859] = { title = "Souls of the Forest", description = "If you're standing in for Lady Moonberry, then maybe you can help!\n\nWagonmaster Derawyn was escorting a bunch of us to a new grove when we were attacked by a pack of hungry predators! The wolf be a fast soulshape, so I got away... but some of the little ones weren't so lucky. They're being hunted like prey!\n\nCome on! They're just down the road!", objectives = "" }
WordHunterWoW_QuestEN[60861] = { title = "Secrets in Shadows", description = "Though we have been monitoring the cultist presence at Mord'rethar, we have not yet discovered what mysteries lie within its chambers.\n\nTake these robes. Make your way into the inner sanctum and see what you can discover.\n\nThis may be our only chance to learn their intentions, {name}.", objectives = "" }
WordHunterWoW_QuestEN[60867] = { title = "A Message from Above", description = "This is troubling news, {name}. Whoever this \"Banished One\" may be, it is clear he is behind the Scourge's return.\n\nThat the undead are amassing in great numbers outside Icecrown Citadel cannot be a coincidence. Lead our hippogryph riders in surveying the area from above.\n\nDetermine if the dark herald you saw is among them, and then clear a path for reinforcements.\n\nLet us hope she possesses the answers we seek.", objectives = "" }
WordHunterWoW_QuestEN[60869] = { title = "With Hope in Hand", description = "You must bring word of what we have uncovered back to Orgrimmar. One of our mages can open a portal for you at the tournament grounds.\n\nAs for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use.\n\nMay the Light protect you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[60871] = { title = "With Hope in Hand", description = "You must bring word of what we have uncovered back to Stormwind. One of our mages can open a portal for you at the tournament grounds.\n\nAs for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use.\n\nMay the Light protect you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[60881] = { title = "Ride of the Wild Hunt", description = "Thanks to your efforts, we have turned the tide of battle. We won't soon forget your aid. \n\nWe should be able to hold Soryn's Meadow, now that this brute is dead. \n\nRide with us, {name}. Let us return to the road and your wildseed.", objectives = "" }
WordHunterWoW_QuestEN[60886] = { title = "The Seat of the Primus", description = "This cannot be a coincidence. It is clear that your runeblade is somehow connected to the Seat of the Primus.\n\nI will not pretend to know the Primus's agenda. But I would not be surprised if he left behind a way for the worthy to open the door to his sanctum.\n\nDraka will bring you to the Seat of the Primus. If you hold the key, mortal, then our victory is all but assured.", objectives = "" }
WordHunterWoW_QuestEN[60898] = { title = "The Fate of Ara'lon", description = "{name}, I have an urgent request to make of you.\n\nRecently, the Wild Hunt has been encountering the masked fae in greater numbers... particularly in the area surrounding Blackthorn Grove. I sent a hunting party to investigate, but they have yet to return.\n\nAra'lon was leading the hunt. You have offered him aid before, yes? I ask that you do so again.\n\nSearch the area for signs of the missing hunters and report back to me.", objectives = "" }
WordHunterWoW_QuestEN[60900] = { title = "Archival Protection", description = "The rarest volumes are kept at the top of this tower, protected by an entity called the Archivist.\n\nThis stoic guardian is incorruptible. Intractable. Completely uninterested in striking a fair bargain!\n\nIts utter lack of business acumen is really quite upsetting.\n\nAh, well. I fear we have no choice but to dispatch this impediment. Shall we?", objectives = "" }
WordHunterWoW_QuestEN[60901] = { title = "Passage to Hibernal Hollow", description = "You have done the Wild Hunt a great service. I must repay you in some way.\n\nThe battle for Soryn's Meadow has turned. With the brute defeated, the Blighted forces lose their strength.\n\nAllow us to escort you to Hibernal Hollow.\n\nSpeak to me whenever you wish to depart.", objectives = "" }
WordHunterWoW_QuestEN[60904] = { title = "Medallion of Desire", description = "The Medallion of Desire rests upon the neck of the Countess. \n\nIt is a source of power for her, but not her only source of power. Claiming it by force would merit us only a short victory. For this we must be much more subtle.\n\nLucky for us, Theotar has come to me with a plan but he will need your help. Speak with him and see what the two of you can do. \n\nHe was closer to the Countess than any of us for a long time and I would consider him our resident expert on her.", objectives = "" }
WordHunterWoW_QuestEN[60905] = { title = "Infusing the Wildseed", description = "Dreamweaver tells me of a ritual to quell the wildseed's nightmares... but it will require anima.\n\nA soul named Proglo lives beneath this tree, gathering anima for the grove's caretakers to use.\n\nHis mortal life came to a violent end, and his soul has been skittish ever since. He will not respond well to your current form.\n\nI will grant you the ability to assume the soulshape of a fox. Approach Proglo in your new form to gain his trust and ask for his anima.", objectives = "" }
WordHunterWoW_QuestEN[60906] = { title = "Rightful Resting Place", description = "You have truly proven yourself a hero in the eyes of those who are its absolute judge.\n\nI thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place.\n\nLet us meet at Hero's Rest where you can do the honors.", objectives = "" }
WordHunterWoW_QuestEN[60907] = { title = "Ascension Calling: Kleia", description = "<This scroll details an invitation for Kleia to join you and Pelagos on the Path of Ascension.\n\nIt would be wise to deliver this to her at once.>", objectives = "" }
WordHunterWoW_QuestEN[60910] = { title = "Masks of Deception", description = "My hunting party was ambushed not far from here. I narrowly escaped capture, but the others were taken deeper into Blackthorn Grove.\n\nWe must find and rescue them, but we are vastly outnumbered. We'll need to disguise ourselves while we search the grove.\n\nSee if you can find something we can use to do so. I need just a little longer to recover from my wounds.", objectives = "" }
WordHunterWoW_QuestEN[60928] = { title = "Blackthorn Captives", description = "These disguises will allow us to explore the grove undetected, but beware of the overseers. Their Drust magic will more than likely be able to pierce through our deception.\n\nWe need to save the rest of my hunting party while we still can.", objectives = "" }
WordHunterWoW_QuestEN[60932] = { title = "Only Shadows Remain", description = "We may not know who this dark herald serves, but it is clear that the message she brings has emboldened the Scourge and the Cult of the Damned alike.\n\nThis cannot be allowed to continue. We must vanquish her and strike a definitive blow against her master's new minions.\n\nLead the charge, {name}. The Argent Crusade stands with you.\n\nLight willing, we will put an end to this madness here and now.", objectives = "" }
WordHunterWoW_QuestEN[60934] = { title = "Report to Lord Herne", description = "I will do whatever it takes to save Gweyir from the Drust's curse.\n\nLord Herne must be informed of what befell my hunting party. Deliver my report to him while I escort Gweyir back to the Heart of the Forest.\n\nGweyir was under my leadership during the ambush... she is my responsibility. I will make sure she gets home safely.", objectives = "" }
WordHunterWoW_QuestEN[60935] = { title = "Medallion of Avarice", description = "The Medallion of Avarice was the tool of the Curator.\n\nWith its power it granted her authority over the Catacombs Ward. Combined with her knowledge of the vast library of sinstones Revendreth has accumulated over the ages, the Curator was a master of her craft.\n\nWhen Denathrius defeated my first rebellion, he tossed both myself and the Curator into the Maw. \n\nThe Curator was clever, though, and she hid the medallion before Denathrius could act. Come, let us speak of plans.", objectives = "" }
WordHunterWoW_QuestEN[60937] = { title = "[DNT] Blueprint: Herald's Footpads", description = "PH - Take this to Dactylis.", objectives = "" }
WordHunterWoW_QuestEN[60945] = { title = "Deep Echo Trident", description = "<The trident glistens in the sunlight.\n\nThis should give your soulbinds the ability to interrupt their foes in the Path of Ascension.>", objectives = "" }
WordHunterWoW_QuestEN[60946] = { title = "Blueprint: Deep Echo Trident", description = "<You have discovered plans for a trident that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", objectives = "" }
WordHunterWoW_QuestEN[60947] = { title = "Blueprint: Charm of Fortitude", description = "<You have discovered plans for a charm that seems to fortify your soulbinds in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "" }
WordHunterWoW_QuestEN[60972] = { title = "The Hunt for the Baron", description = "<The amulet Bolvar gave you flickers with a faint red light, then grows dim.\n\nTo be useful in finding Darion Mograine, you must find a way to restore its potency.\n\nYou recall an area called Zovaal's Cauldron that was teeming with dark magic.\n\nPerhaps the amulet's power could be restored there.>", objectives = "" }
WordHunterWoW_QuestEN[60973] = { title = "Blueprint: Phial of Serenity", description = "<You have discovered plans for a phial that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", objectives = "" }
WordHunterWoW_QuestEN[60974] = { title = "Phial of Serenity", description = "<Your steward friend gave you an extra bottle to store this potion in.\n\nThis should keep your soulbinds fighting in the Path of Ascension, as your phial does.>", objectives = "" }
WordHunterWoW_QuestEN[60975] = { title = "Blueprint: Spiritforged Aegis", description = "<You have discovered plans for a shield that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", objectives = "" }
WordHunterWoW_QuestEN[60993] = { title = "Citadel of Loyalty", description = "The medallions, the source of magic the crown focuses, are still bent to the will of Denathrius. \n\nForge cannot solve this. Citadel of Loyalty can.\n\nTaken over by the Forsworn in recent times. If we can get the crown to the temple, we can break the loyalty to the medallion's former master.", objectives = "" }
WordHunterWoW_QuestEN[60994] = { title = "Lowering Their Defenses", description = "We can alter the crown to expunge Denathrius's corruption in the medallions.\n\nProblem, Forsworn have set large barrier protecting the temple. Only there can Denathrius's influence be truly broken.\n\nDrain the anima from the barrier's sources that power it. Barrier will disappear.", objectives = "" }
WordHunterWoW_QuestEN[60995] = { title = "Disloyalty", description = "There are many enemies of Bastion here. \n\nIf we thin their numbers, it will further mend the tension between our realms. \n\nShow no remorse. \n\nI will take to the skies to support from above. I will be able to provide ground support when needed.", objectives = "" }
WordHunterWoW_QuestEN[60996] = { title = "Face Your Fears", description = "The temple is now accessible. We must go now to aid Mikanikos in breaking the Sire's influence on the crown.\n\nPrepare yourself. Denathrius's magic has always been potent and destructive. \n\nThis won't be easy.", objectives = "" }
